window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[7]={"700":{"example:700:exzh":"What do you want to eat?","example:700:exzh2":"When are you going?","example:700:exzh3":"What is he doing?","example:700:exzh4":"Do you have any questions?","example:700:exzh5":"Is there anything I can help with?","grammar:700:ex:trans":"What do you want to eat?","grammar:700:ex:structure":"何を〜たいですか","grammar:700:ex:explain":"This sentence uses the desire pattern 「〜たい」 (to want to …). 「食べたい」 is formed from 「食べる」 plus 「たい」 and expresses wanting to eat. 「何を」 uses 「を」 to mark what you want to eat, and 「ですか」 at the end makes it a question. The whole sentence means: what do you want to eat? Note that 「何」 is read 「なに」 before 「を」, but often becomes 「なん」 before 「です」, 「で」, and so on. 「〜たい」 expresses the speaker's own desire or asks about the listener's.","grammar:700:ex:words:0:zh":"what","grammar:700:ex:words:0:note":"なに","grammar:700:ex:words:0:pos":"question word","grammar:700:ex:words:1:zh":"(object marker)","grammar:700:ex:words:1:pos":"particle","grammar:700:ex:words:2:zh":"want to eat","grammar:700:ex:words:2:note":"たべたい","grammar:700:ex:words:2:pos":"verb","grammar:700:ex:words:3:zh":"(polite form)","grammar:700:ex:words:3:pos":"copula","grammar:700:ex:words:4:zh":"(question)","grammar:700:ex:words:4:pos":"particle","grammar:700:ex:points:0":"❗何 (なに／なん): what; it is read なに before を.","grammar:700:ex:points:1":"〜たい: to want to ….","grammar:700:ex2:trans":"What time are you going?","grammar:700:ex2:structure":"何時に行きますか","grammar:700:ex2:words:0:zh":"what time","grammar:700:ex2:words:0:note":"なんじ","grammar:700:ex2:words:0:pos":"question word","grammar:700:ex2:words:1:zh":"(point in time)","grammar:700:ex2:words:1:pos":"particle","grammar:700:ex2:words:2:zh":"go","grammar:700:ex2:words:2:pos":"verb","grammar:700:ex2:words:3:zh":"(question)","grammar:700:ex2:words:3:pos":"particle","grammar:700:ex2:points:0":"❗何＋時＝何時 (なんじ): what time (何 is read なん).","grammar:700:ex2:points:1":"何時に行く: to go at what time.","grammar:700:ex3:trans":"What is he doing?","grammar:700:ex3:structure":"何をしていますか","grammar:700:ex3:words:0:zh":"he","grammar:700:ex3:words:0:note":"かれ","grammar:700:ex3:words:0:pos":"pronoun","grammar:700:ex3:words:1:zh":"(topic)","grammar:700:ex3:words:1:pos":"particle","grammar:700:ex3:words:2:zh":"what","grammar:700:ex3:words:2:note":"なに","grammar:700:ex3:words:2:pos":"question word","grammar:700:ex3:words:3:zh":"(object marker)","grammar:700:ex3:words:3:pos":"particle","grammar:700:ex3:words:4:zh":"is doing","grammar:700:ex3:words:4:pos":"verb","grammar:700:ex3:words:5:zh":"(question)","grammar:700:ex3:words:5:pos":"particle","grammar:700:ex3:points:0":"何をしている: to be doing what.","grammar:700:ex3:points:1":"〜ている: ongoing action.","grammar:700:ex4:trans":"Do you have any questions?","grammar:700:ex4:structure":"何か〜がありますか","grammar:700:ex4:words:0:zh":"what","grammar:700:ex4:words:0:note":"なにか","grammar:700:ex4:words:0:pos":"pronoun","grammar:700:ex4:words:1:zh":"problem","grammar:700:ex4:words:1:note":"しつもん","grammar:700:ex4:words:1:pos":"noun","grammar:700:ex4:words:2:zh":"(nominative)","grammar:700:ex4:words:2:pos":"particle","grammar:700:ex4:words:3:zh":"there is / are","grammar:700:ex4:words:3:pos":"verb","grammar:700:ex4:words:4:zh":"(question)","grammar:700:ex4:words:4:pos":"particle","grammar:700:ex4:points:0":"❗何か: something, anything (indefinite).","grammar:700:ex4:points:1":"質問がある: to have a question.","grammar:700:ex5:trans":"Is there anything I can help with?","grammar:700:ex5:structure":"何か〜ことはありますか","grammar:700:ex5:words:0:zh":"what","grammar:700:ex5:words:0:note":"なにか","grammar:700:ex5:words:0:pos":"pronoun","grammar:700:ex5:words:1:zh":"help","grammar:700:ex5:words:1:note":"てつだう","grammar:700:ex5:words:1:pos":"verb","grammar:700:ex5:words:2:zh":"thing / matter","grammar:700:ex5:words:2:pos":"noun","grammar:700:ex5:words:3:zh":"(topic)","grammar:700:ex5:words:3:pos":"particle","grammar:700:ex5:words:4:zh":"there is / are","grammar:700:ex5:words:4:pos":"verb","grammar:700:ex5:words:5:zh":"(question)","grammar:700:ex5:words:5:pos":"particle","grammar:700:ex5:points:0":"何か手伝うこと: something to help with.","grammar:700:ex5:points:1":"〜ことはありますか: is there anything that …?","exam:700:zh":"What is this flower called in Japanese?","exam:700:why":"To ask for a name, use 「何と言いますか」. 「誰」 asks who a person is and can't be used to ask the name of a flower."},"701":{"example:701:exzh":"He's a student.","example:701:exzh2":"He's Japanese.","example:701:exzh3":"I like him.","example:701:exzh4":"He's kind.","example:701:exzh5":"He's good at soccer.","grammar:701:ex:trans":"He is a student.","grammar:701:ex:structure":"彼は〜です","grammar:701:ex:explain":"This is the most basic identifying sentence, 「彼は学生です」. 「は」 marks 「彼」 as the topic, and 「学生」 is a noun; adding 「です」 gives the meaning is a student and makes the tone polite. The whole sentence means he is a student. 「彼」 is read 「かれ」 and, depending on context, can refer not only to him but also to a boyfriend. This A は B です pattern is the core of Japanese, so mastering it first makes everything else easier to build on.","grammar:701:ex:words:0:zh":"he","grammar:701:ex:words:0:note":"かれ","grammar:701:ex:words:0:pos":"pronoun","grammar:701:ex:words:1:zh":"(topic)","grammar:701:ex:words:1:pos":"particle","grammar:701:ex:words:2:zh":"student","grammar:701:ex:words:2:note":"がくせい","grammar:701:ex:words:2:pos":"noun","grammar:701:ex:words:3:zh":"is","grammar:701:ex:words:3:pos":"copula","grammar:701:ex:points:0":"彼 (かれ): he; also means boyfriend.","grammar:701:ex:points:1":"彼は〜です: he is …","grammar:701:ex2:trans":"He is Japanese.","grammar:701:ex2:structure":"彼は〜です","grammar:701:ex2:words:0:zh":"he","grammar:701:ex2:words:0:note":"かれ","grammar:701:ex2:words:0:pos":"pronoun","grammar:701:ex2:words:1:zh":"(topic)","grammar:701:ex2:words:1:pos":"particle","grammar:701:ex2:words:2:zh":"Japanese","grammar:701:ex2:words:2:note":"にほんじん","grammar:701:ex2:words:2:pos":"noun","grammar:701:ex2:words:3:zh":"is","grammar:701:ex2:words:3:pos":"copula","grammar:701:ex2:points:0":"日本人: a Japanese person.","grammar:701:ex2:points:1":"彼は日本人: he is Japanese.","grammar:701:ex3:trans":"I like him.","grammar:701:ex3:structure":"彼が好きです","grammar:701:ex3:words:0:zh":"he","grammar:701:ex3:words:0:note":"かれ","grammar:701:ex3:words:0:pos":"pronoun","grammar:701:ex3:words:1:zh":"(object)","grammar:701:ex3:words:1:pos":"particle","grammar:701:ex3:words:2:zh":"to like","grammar:701:ex3:words:2:note":"すき","grammar:701:ex3:words:2:pos":"na-adjective","grammar:701:ex3:words:3:zh":"(polite form)","grammar:701:ex3:words:3:pos":"copula","grammar:701:ex3:points:0":"❗彼が好き: I like him (with 好き, the object takes が).","grammar:701:ex3:points:1":"It can also mean liking the person himself.","grammar:701:ex4:trans":"He is kind.","grammar:701:ex4:structure":"彼は〜です","grammar:701:ex4:words:0:zh":"he","grammar:701:ex4:words:0:note":"かれ","grammar:701:ex4:words:0:pos":"pronoun","grammar:701:ex4:words:1:zh":"(topic)","grammar:701:ex4:words:1:pos":"particle","grammar:701:ex4:words:2:zh":"kind","grammar:701:ex4:words:2:note":"やさしい","grammar:701:ex4:words:2:pos":"adjective","grammar:701:ex4:words:3:zh":"(polite form)","grammar:701:ex4:words:3:pos":"copula","grammar:701:ex4:points:0":"優しい: gentle, kind.","grammar:701:ex4:points:1":"彼は優しい: he is kind.","grammar:701:ex5:trans":"He is good at soccer.","grammar:701:ex5:structure":"彼は〜が得意です","grammar:701:ex5:words:0:zh":"he","grammar:701:ex5:words:0:note":"かれ","grammar:701:ex5:words:0:pos":"pronoun","grammar:701:ex5:words:1:zh":"(topic)","grammar:701:ex5:words:1:pos":"particle","grammar:701:ex5:words:2:zh":"soccer","grammar:701:ex5:words:2:note":"loanword","grammar:701:ex5:words:2:pos":"noun","grammar:701:ex5:words:3:zh":"(object)","grammar:701:ex5:words:3:pos":"particle","grammar:701:ex5:words:4:zh":"good at","grammar:701:ex5:words:4:note":"とくい","grammar:701:ex5:words:4:pos":"na-adjective","grammar:701:ex5:words:5:zh":"(polite form)","grammar:701:ex5:words:5:pos":"copula","grammar:701:ex5:points:0":"The object of 「得意」 takes が.","grammar:701:ex5:points:1":"サッカーが得意: good at soccer.","exam:701:zh":"Yamada is a man, so you refer to Yamada as 「彼」 (he).","exam:701:why":"「彼」 can refer to a man in the third person. 「彼女」 refers to a woman, which doesn't match 「男の人」 in the sentence."},"702":{"example:702:exzh":"Where are you going?","example:702:exzh2":"Are you okay today?","example:702:exzh3":"What's your name?","example:702:exzh4":"I want to watch a movie with you.","example:702:exzh5":"You're really kind, aren't you.","grammar:702:ex:trans":"Where are you going?","grammar:702:ex:structure":"君はどこに〜の？","grammar:702:ex:explain":"The key point here is the second-person 「君（きみ）」. It sounds intimate and is also used toward people below you, and men use it more often; it does not suit elders or formal situations. The sentence-ending 「の？」 is a casual question with a soft, caring tone. In 「どこに行く」, 「に」 marks the destination. The whole sentence means: where are you going? In Japanese you choose your word for you based on the relationship (あなた, 君, お前), and getting it wrong can be rude.","grammar:702:ex:words:0:zh":"you","grammar:702:ex:words:0:note":"きみ","grammar:702:ex:words:0:pos":"pronoun","grammar:702:ex:words:1:zh":"(topic)","grammar:702:ex:words:1:pos":"particle","grammar:702:ex:words:2:zh":"where","grammar:702:ex:words:2:pos":"question word","grammar:702:ex:words:3:zh":"(destination)","grammar:702:ex:words:3:pos":"particle","grammar:702:ex:words:4:zh":"go","grammar:702:ex:words:4:note":"いく","grammar:702:ex:words:4:pos":"verb","grammar:702:ex:words:5:zh":"(question)","grammar:702:ex:words:5:pos":"particle","grammar:702:ex:points:0":"❗君（きみ）: you (intimate / toward someone below you, often used by men).","grammar:702:ex:points:1":"どこに行く: go where.","grammar:702:ex2:trans":"Are you doing okay today?","grammar:702:ex2:structure":"君は〜ですか","grammar:702:ex2:words:0:zh":"you","grammar:702:ex2:words:0:note":"きみ","grammar:702:ex2:words:0:pos":"pronoun","grammar:702:ex2:words:1:zh":"(topic)","grammar:702:ex2:words:1:pos":"particle","grammar:702:ex2:words:2:zh":"today","grammar:702:ex2:words:2:note":"きょう","grammar:702:ex2:words:2:pos":"noun","grammar:702:ex2:words:3:zh":"well / healthy","grammar:702:ex2:words:3:note":"げんき","grammar:702:ex2:words:3:pos":"na-adjective","grammar:702:ex2:words:4:zh":"(polite form)","grammar:702:ex2:words:4:pos":"copula","grammar:702:ex2:words:5:zh":"(question)","grammar:702:ex2:words:5:pos":"particle","grammar:702:ex2:points:0":"元気ですか: are you well, are you healthy.","grammar:702:ex2:points:1":"君は: you (topic).","grammar:702:ex3:trans":"What is your name?","grammar:702:ex3:structure":"君の〜は何ですか","grammar:702:ex3:words:0:zh":"you","grammar:702:ex3:words:0:note":"きみ","grammar:702:ex3:words:0:pos":"pronoun","grammar:702:ex3:words:1:zh":"'s","grammar:702:ex3:words:1:pos":"particle","grammar:702:ex3:words:2:zh":"name","grammar:702:ex3:words:2:note":"なまえ","grammar:702:ex3:words:2:pos":"noun","grammar:702:ex3:words:3:zh":"(topic)","grammar:702:ex3:words:3:pos":"particle","grammar:702:ex3:words:4:zh":"what","grammar:702:ex3:words:4:note":"なん","grammar:702:ex3:words:4:pos":"question word","grammar:702:ex3:words:5:zh":"is","grammar:702:ex3:words:5:pos":"copula","grammar:702:ex3:words:6:zh":"(question)","grammar:702:ex3:words:6:pos":"particle","grammar:702:ex3:points:0":"君の名前: your name.","grammar:702:ex3:points:1":"何ですか: what is it.","grammar:702:ex4:trans":"I want to watch a movie with you.","grammar:702:ex4:structure":"君と一緒に〜たい","grammar:702:ex4:words:0:zh":"you","grammar:702:ex4:words:0:note":"きみ","grammar:702:ex4:words:0:pos":"pronoun","grammar:702:ex4:words:1:zh":"with","grammar:702:ex4:words:1:pos":"particle","grammar:702:ex4:words:2:zh":"together","grammar:702:ex4:words:2:note":"いっしょに","grammar:702:ex4:words:2:pos":"adverb","grammar:702:ex4:words:3:zh":"movie","grammar:702:ex4:words:3:note":"えいが","grammar:702:ex4:words:3:pos":"noun","grammar:702:ex4:words:4:zh":"(object marker)","grammar:702:ex4:words:4:pos":"particle","grammar:702:ex4:words:5:zh":"want to watch","grammar:702:ex4:words:5:note":"みたい","grammar:702:ex4:words:5:pos":"verb","grammar:702:ex4:points:0":"君と一緒に: together with you.","grammar:702:ex4:points:1":"〜たい: to want to ….","grammar:702:ex5:trans":"You're really kind, aren't you.","grammar:702:ex5:structure":"君は〜ね","grammar:702:ex5:words:0:zh":"you","grammar:702:ex5:words:0:note":"きみ","grammar:702:ex5:words:0:pos":"pronoun","grammar:702:ex5:words:1:zh":"(topic)","grammar:702:ex5:words:1:pos":"particle","grammar:702:ex5:words:2:zh":"really","grammar:702:ex5:words:2:note":"ほんとうに","grammar:702:ex5:words:2:pos":"adverb","grammar:702:ex5:words:3:zh":"kind","grammar:702:ex5:words:3:note":"やさしい","grammar:702:ex5:words:3:pos":"adjective","grammar:702:ex5:words:4:zh":"right?","grammar:702:ex5:words:4:pos":"particle","grammar:702:ex5:points:0":"本当に優しい: really kind.","grammar:702:ex5:points:1":"ね: seeking agreement / exclamation."},"703":{"example:703:exzh":"I understand why you worked so hard.","example:703:exzh2":"I understand how he feels.","example:703:exzh3":"Some people don't understand Japanese.","example:703:exzh4":"I finally get it!","grammar:703:ex:trans":"I get why you worked so hard.","grammar:703:ex:structure":"［どうして〜たのか］分かる","grammar:703:ex:explain":"The whole clause 「どうしてそんなに頑張ったのか」 expresses the question of why someone worked so hard, and 「分かる」 follows it to mean understanding the reason behind it. 「頑張った」 is the past form of 「頑張る」, and 「そんなに」 describes the degree of effort. 「のか」 carries a tone of probing the background of the matter. The original sentence leaves out both the person who worked hard and the person who understands; following the translation given, they are supplied as you and I.","grammar:703:ex:words:0:zh":"why","grammar:703:ex:words:0:pos":"adverb","grammar:703:ex:words:1:zh":"that much","grammar:703:ex:words:1:pos":"adverb","grammar:703:ex:words:2:zh":"effort","grammar:703:ex:words:2:note":"がんばっ","grammar:703:ex:words:2:pos":"verb","grammar:703:ex:words:3:zh":"(past)","grammar:703:ex:words:3:pos":"auxiliary verb","grammar:703:ex:words:4:zh":"(explaining the background of the matter)","grammar:703:ex:words:4:pos":"particle","grammar:703:ex:words:5:zh":"(embedding a question inside a sentence)","grammar:703:ex:words:5:pos":"particle","grammar:703:ex:words:6:zh":"understand, grasp","grammar:703:ex:words:6:note":"わかる","grammar:703:ex:words:6:pos":"verb","grammar:703:ex:points:0":"「疑問詞＋普通形＋か」 lets you put the content of a question inside another sentence.","grammar:703:ex:points:1":"The 「の」 in 「頑張ったのか」 carries a tone of probing the background or cause of something.","grammar:703:ex:points:2":"「分かる」 itself already means to understand; it is not the potential form.","grammar:703:ex2:trans":"I understand his feelings.","grammar:703:ex2:structure":"〜が分かる","grammar:703:ex2:words:0:zh":"he","grammar:703:ex2:words:0:note":"かれ","grammar:703:ex2:words:0:pos":"pronoun","grammar:703:ex2:words:1:zh":"'s","grammar:703:ex2:words:1:pos":"particle","grammar:703:ex2:words:2:zh":"feeling","grammar:703:ex2:words:2:note":"きもち","grammar:703:ex2:words:2:pos":"noun","grammar:703:ex2:words:3:zh":"(object)","grammar:703:ex2:words:3:pos":"particle","grammar:703:ex2:words:4:zh":"understanding","grammar:703:ex2:words:4:note":"わかる","grammar:703:ex2:words:4:pos":"verb","grammar:703:ex2:points:0":"❗分かる: to understand, to get it (the object takes が, not を).","grammar:703:ex2:points:1":"気持ちが分かる: understand how someone feels.","grammar:703:ex3:trans":"Some people don't understand Japanese.","grammar:703:ex3:structure":"〜が分からない人もいます","grammar:703:ex3:words:0:zh":"Japanese","grammar:703:ex3:words:0:note":"にほんご","grammar:703:ex3:words:0:pos":"noun","grammar:703:ex3:words:1:zh":"(object)","grammar:703:ex3:words:1:pos":"particle","grammar:703:ex3:words:2:zh":"do not understand","grammar:703:ex3:words:2:note":"わからない","grammar:703:ex3:words:2:pos":"verb","grammar:703:ex3:words:3:zh":"person","grammar:703:ex3:words:3:note":"ひと","grammar:703:ex3:words:3:pos":"noun","grammar:703:ex3:words:4:zh":"also, too","grammar:703:ex3:words:4:pos":"particle","grammar:703:ex3:words:5:zh":"there is / are","grammar:703:ex3:words:5:pos":"verb","grammar:703:ex3:points:0":"日本語が分からない: doesn't understand Japanese.","grammar:703:ex3:points:1":"〜人もいる: there are also people who…","grammar:703:ex4:trans":"I finally get it!","grammar:703:ex4:structure":"やっと分かった","grammar:703:ex4:words:0:zh":"finally","grammar:703:ex4:words:0:pos":"adverb","grammar:703:ex4:words:1:zh":"got it","grammar:703:ex4:words:1:note":"わかった","grammar:703:ex4:words:1:pos":"verb","grammar:703:ex4:points:0":"やっと: finally, at last.","grammar:703:ex4:points:1":"分かった: got it, understood.","exam:703:zh":"Anyone who knows what this word means, please tell me.","exam:703:why":"「意味が分かる」 means understanding the meaning. 「読む」 is to read, and it can't go with 「意味が」 here to mean understanding."},"705":{"example:705:exzh":"What do you want to ask?","example:705:exzh2":"I ask my teacher about things I don't understand.","example:705:exzh3":"I heard his voice.","example:705:exzh4":"Did you hear the latest news?","grammar:705:ex:trans":"What do you want to ask?","grammar:705:ex:structure":"何を〜たいのですか","grammar:705:ex:explain":"This sentence is a reminder that 「聞く」 has more than one meaning: besides listening, it often means asking or inquiring. Here 「何を聞きたい」 means what do you want to ask, not what do you want to listen to — you have to judge from the context. 「〜たい」 expresses desire, and 「のですか」 adds a tone of explaining or confirming. The whole sentence means: what do you want to ask? Whether a given 「聞く」 means listening or asking has to be decided from the context.","grammar:705:ex:words:0:zh":"what","grammar:705:ex:words:0:note":"なに","grammar:705:ex:words:0:pos":"question word","grammar:705:ex:words:1:zh":"(object marker)","grammar:705:ex:words:1:pos":"particle","grammar:705:ex:words:2:zh":"want to ask","grammar:705:ex:words:2:note":"ききたい","grammar:705:ex:words:2:pos":"verb","grammar:705:ex:words:3:zh":"(explanation)","grammar:705:ex:words:3:pos":"particle","grammar:705:ex:words:4:zh":"(polite form)","grammar:705:ex:words:4:pos":"copula","grammar:705:ex:words:5:zh":"(question)","grammar:705:ex:words:5:pos":"particle","grammar:705:ex:points:0":"❗聞く: to listen; also means to ask.","grammar:705:ex:points:1":"何を聞きたい: what one wants to ask.","grammar:705:ex2:trans":"I ask the teacher about the parts I don't understand.","grammar:705:ex2:structure":"人に分からないことを聞きます","grammar:705:ex2:explain":"「分からないこと」 means the thing or content you don't understand; here 「こと」 is not a physical place. 「先生に」 indicates that the teacher is the one being asked, and 「を」 marks what is being asked about. Besides listening, 「聞く」 can also mean asking; because this sentence has both someone to ask and something to ask about, it should be understood as asking the teacher.","grammar:705:ex2:words:0:zh":"teacher","grammar:705:ex2:words:0:note":"せんせい","grammar:705:ex2:words:0:pos":"noun","grammar:705:ex2:words:1:zh":"(the person being asked)","grammar:705:ex2:words:1:pos":"particle","grammar:705:ex2:words:2:zh":"understand","grammar:705:ex2:words:2:note":"わから","grammar:705:ex2:words:2:pos":"verb","grammar:705:ex2:words:3:zh":"(negative)","grammar:705:ex2:words:3:pos":"auxiliary verb","grammar:705:ex2:words:4:zh":"thing, matter","grammar:705:ex2:words:4:pos":"noun","grammar:705:ex2:words:5:zh":"(what is being asked about)","grammar:705:ex2:words:5:pos":"particle","grammar:705:ex2:words:6:zh":"ask","grammar:705:ex2:words:6:note":"きき","grammar:705:ex2:words:6:pos":"verb","grammar:705:ex2:words:7:zh":"(polite tone)","grammar:705:ex2:words:7:pos":"auxiliary verb","grammar:705:ex2:points:0":"「分からない」 is the negative form of 「分かる」 and modifies 「こと」 directly.","grammar:705:ex2:points:1":"In 「人に内容を聞く」, 「に」 marks the person you ask and 「を」 marks what you ask about.","grammar:705:ex3:trans":"I heard his voice.","grammar:705:ex3:structure":"人の声を聞きました","grammar:705:ex3:explain":"「彼の声」 means his voice, with 「の」 marking possession. 「声を」 is the object of 「聞く」, showing what was heard. 「聞きました」 shows that the act of listening already happened; to say that a sound simply reached your ears, 「声が聞こえました」 is also common.","grammar:705:ex3:words:0:zh":"he","grammar:705:ex3:words:0:note":"かれ","grammar:705:ex3:words:0:pos":"pronoun","grammar:705:ex3:words:1:zh":"(possession)","grammar:705:ex3:words:1:pos":"particle","grammar:705:ex3:words:2:zh":"voice","grammar:705:ex3:words:2:note":"こえ","grammar:705:ex3:words:2:pos":"noun","grammar:705:ex3:words:3:zh":"(object)","grammar:705:ex3:words:3:pos":"particle","grammar:705:ex3:words:4:zh":"listen","grammar:705:ex3:words:4:note":"きき","grammar:705:ex3:words:4:pos":"verb","grammar:705:ex3:words:5:zh":"(polite tone)","grammar:705:ex3:words:5:pos":"auxiliary verb","grammar:705:ex3:words:6:zh":"(past, completed)","grammar:705:ex3:words:6:pos":"auxiliary verb","grammar:705:ex3:points:0":"In 「彼の声」, 「の」 shows whose voice it is.","grammar:705:ex3:points:1":"「声を聞く」 means to listen to someone's voice, and 「聞きました」 is the polite past form.","grammar:705:ex4:trans":"Did you hear the new information?","grammar:705:ex4:structure":"〜を聞きましたか","grammar:705:ex4:words:0:zh":"new","grammar:705:ex4:words:0:note":"あたらしい","grammar:705:ex4:words:0:pos":"adjective","grammar:705:ex4:words:1:zh":"information","grammar:705:ex4:words:1:note":"じょうほう","grammar:705:ex4:words:1:pos":"noun","grammar:705:ex4:words:2:zh":"(object marker)","grammar:705:ex4:words:2:pos":"particle","grammar:705:ex4:words:3:zh":"heard","grammar:705:ex4:words:3:note":"ききました","grammar:705:ex4:words:3:pos":"verb","grammar:705:ex4:words:4:zh":"(question)","grammar:705:ex4:words:4:pos":"particle","grammar:705:ex4:points:0":"情報を聞く: to hear news.","grammar:705:ex4:points:1":"新しい情報: new information.","exam:705:zh":"When you listen to music on the radio, please turn the volume down.","exam:705:why":"To take in the sound of music you use 「聞く」. 「話す」 means to speak, so it can't express listening to music playing on the radio."},"706":{"example:706:exzh":"I take the book out of the bag.","example:706:exzh2":"It's important to give your opinion.","example:706:exzh3":"Please lend a hand and help.","example:706:exzh4":"I came up with a new idea.","example:706:exzh5":"Don't forget to hand over the money.","grammar:706:ex:trans":"I take the book out of the bag.","grammar:706:ex:structure":"〜を〜から出します","grammar:706:ex:explain":"This sentence requires telling the transitive 「出す」 apart from the intransitive 「出る」: 「出す」 means someone takes something out (with a doer), while 「出る」 means something goes out by itself. Here 「本を出す」 marks the object with 「を」 and means take out the book. 「バッグから」 uses 「から」 to mark the starting point, out of the bag. The whole sentence means I take the book out of the bag. Learn transitive/intransitive pairs from the same root as sets.","grammar:706:ex:words:0:zh":"book","grammar:706:ex:words:0:note":"ほん","grammar:706:ex:words:0:pos":"noun","grammar:706:ex:words:1:zh":"(object marker)","grammar:706:ex:words:1:pos":"particle","grammar:706:ex:words:2:zh":"bag","grammar:706:ex:words:2:note":"loanword","grammar:706:ex:words:2:pos":"noun","grammar:706:ex:words:3:zh":"from","grammar:706:ex:words:3:pos":"particle","grammar:706:ex:words:4:zh":"take out","grammar:706:ex:words:4:note":"だします","grammar:706:ex:words:4:pos":"verb","grammar:706:ex:points:0":"❗出す (transitive verb: take out / submit); vs 出る (intransitive verb: go out).","grammar:706:ex:points:1":"〜から出す: take … out of ….","grammar:706:ex2:trans":"It's important to offer your opinion.","grammar:706:ex2:structure":"〜のは大切です","grammar:706:ex2:words:0:zh":"opinion","grammar:706:ex2:words:0:note":"いけん","grammar:706:ex2:words:0:pos":"noun","grammar:706:ex2:words:1:zh":"(object marker)","grammar:706:ex2:words:1:pos":"particle","grammar:706:ex2:words:2:zh":"propose","grammar:706:ex2:words:2:note":"だす","grammar:706:ex2:words:2:pos":"verb","grammar:706:ex2:words:3:zh":"(nominalizer)","grammar:706:ex2:words:3:pos":"particle","grammar:706:ex2:words:4:zh":"(topic)","grammar:706:ex2:words:4:pos":"particle","grammar:706:ex2:words:5:zh":"important","grammar:706:ex2:words:5:note":"たいせつ","grammar:706:ex2:words:5:pos":"na-adjective","grammar:706:ex2:words:6:zh":"(polite form)","grammar:706:ex2:words:6:pos":"copula","grammar:706:ex2:points:0":"❗意見を出す: to offer an opinion.","grammar:706:ex2:points:1":"〜のは大切: doing … is important.","grammar:706:ex3:trans":"Please lend a hand and help.","grammar:706:ex3:structure":"手を出して〜てください","grammar:706:ex3:words:0:zh":"hand","grammar:706:ex3:words:0:note":"て","grammar:706:ex3:words:0:pos":"noun","grammar:706:ex3:words:1:zh":"(object marker)","grammar:706:ex3:words:1:pos":"particle","grammar:706:ex3:words:2:zh":"reach out","grammar:706:ex3:words:2:note":"だして","grammar:706:ex3:words:2:pos":"verb","grammar:706:ex3:words:3:zh":"help","grammar:706:ex3:words:3:note":"たすけて","grammar:706:ex3:words:3:pos":"verb","grammar:706:ex3:words:4:zh":"please","grammar:706:ex3:words:4:pos":"auxiliary verb","grammar:706:ex3:points:0":"❗手を出す: to reach out with your hand (also means to meddle, to make a move).","grammar:706:ex3:points:1":"助けて: help.","grammar:706:ex4:trans":"I put forward a new idea.","grammar:706:ex4:structure":"〜を出しました","grammar:706:ex4:words:0:zh":"new","grammar:706:ex4:words:0:note":"あたらしい","grammar:706:ex4:words:0:pos":"adjective","grammar:706:ex4:words:1:zh":"idea","grammar:706:ex4:words:1:note":"loanword","grammar:706:ex4:words:1:pos":"noun","grammar:706:ex4:words:2:zh":"(object marker)","grammar:706:ex4:words:2:pos":"particle","grammar:706:ex4:words:3:zh":"gave","grammar:706:ex4:words:3:note":"だしました","grammar:706:ex4:words:3:pos":"verb","grammar:706:ex4:points:0":"アイデアを出す: to put forward an idea.","grammar:706:ex4:points:1":"出す→出しました。","grammar:706:ex5:trans":"Don't forget to hand over the money.","grammar:706:ex5:structure":"〜を出すのを忘れないで","grammar:706:ex5:words:0:zh":"money","grammar:706:ex5:words:0:note":"おかね","grammar:706:ex5:words:0:pos":"noun","grammar:706:ex5:words:1:zh":"(object marker)","grammar:706:ex5:words:1:pos":"particle","grammar:706:ex5:words:2:zh":"take out","grammar:706:ex5:words:2:note":"だす","grammar:706:ex5:words:2:pos":"verb","grammar:706:ex5:words:3:zh":"(nominalizer)","grammar:706:ex5:words:3:pos":"particle","grammar:706:ex5:words:4:zh":"(object marker)","grammar:706:ex5:words:4:pos":"particle","grammar:706:ex5:words:5:zh":"don't forget","grammar:706:ex5:words:5:note":"わすれないで","grammar:706:ex5:words:5:pos":"verb","grammar:706:ex5:points:0":"❗お金を出す: to pay, to put out money.","grammar:706:ex5:points:1":"〜のを忘れないで: don't forget to ….","exam:706:zh":"To send the letter, I'm going to drop it in the mailbox nearby.","exam:706:why":"「手紙をポストに出す」 means putting a letter in a mailbox to send it. 「持つ」 only means to hold, which doesn't express mailing a letter."},"707":{"example:707:exzh":"Please wait until eight.","example:707:exzh2":"I'll finish my homework by tomorrow.","example:707:exzh3":"Work is until five.","example:707:exzh4":"This is where the running ends.","example:707:exzh5":"School is on break until March.","grammar:707:ex:trans":"Please wait until eight o'clock.","grammar:707:ex:structure":"〜まで待ってください","grammar:707:ex:explain":"The key here is the particle 「まで」 (until), which shows an action continuing up to a certain point in time. 「八時まで待つ」 means wait until eight, with 「まで」 marking the ending time. 「待って」 is the te-form plus 「ください」, making a request. The whole sentence means: please wait until eight. 「まで」 emphasizes continuing up to a boundary; when you mean a deadline — by which something must be done — 「までに」 is often used, so the two need to be kept apart.","grammar:707:ex:words:0:zh":"eight o'clock","grammar:707:ex:words:0:note":"はちじ","grammar:707:ex:words:0:pos":"noun","grammar:707:ex:words:1:zh":"until","grammar:707:ex:words:1:pos":"particle","grammar:707:ex:words:2:zh":"wait","grammar:707:ex:words:2:note":"まって","grammar:707:ex:words:2:pos":"verb","grammar:707:ex:words:3:zh":"please","grammar:707:ex:words:3:pos":"auxiliary verb","grammar:707:ex:points:0":"❗〜まで: until… (continuing up to a point in time).","grammar:707:ex:points:1":"八時まで待つ: wait until eight.","grammar:707:ex2:trans":"I'll finish my homework by tomorrow.","grammar:707:ex2:structure":"〜までに〜ます","grammar:707:ex2:words:0:zh":"tomorrow","grammar:707:ex2:words:0:note":"あした","grammar:707:ex2:words:0:pos":"noun","grammar:707:ex2:words:1:zh":"before","grammar:707:ex2:words:1:pos":"particle","grammar:707:ex2:words:2:zh":"homework","grammar:707:ex2:words:2:note":"しゅくだい","grammar:707:ex2:words:2:pos":"noun","grammar:707:ex2:words:3:zh":"(object marker)","grammar:707:ex2:words:3:pos":"particle","grammar:707:ex2:words:4:zh":"to finish (something)","grammar:707:ex2:words:4:note":"おわらせます (causative form)","grammar:707:ex2:words:4:pos":"verb","grammar:707:ex2:points:0":"❗〜までに: by… (a deadline, vs まで = continuing until).","grammar:707:ex2:points:1":"終わらせる: to make… end (the causative of 終わる).","grammar:707:ex3:trans":"Work is until five.","grammar:707:ex3:structure":"〜は〜までです","grammar:707:ex3:words:0:zh":"work","grammar:707:ex3:words:0:note":"しごと","grammar:707:ex3:words:0:pos":"noun","grammar:707:ex3:words:1:zh":"(topic)","grammar:707:ex3:words:1:pos":"particle","grammar:707:ex3:words:2:zh":"five o'clock","grammar:707:ex3:words:2:note":"ごじ","grammar:707:ex3:words:2:pos":"noun","grammar:707:ex3:words:3:zh":"until","grammar:707:ex3:words:3:pos":"particle","grammar:707:ex3:words:4:zh":"(polite form)","grammar:707:ex3:words:4:pos":"copula","grammar:707:ex3:points:0":"〜までです: up to…","grammar:707:ex3:points:1":"五時まで: until five.","grammar:707:ex4:trans":"This is where the running stops.","grammar:707:ex4:structure":"〜のはここまでです","grammar:707:ex4:words:0:zh":"run","grammar:707:ex4:words:0:note":"はしる","grammar:707:ex4:words:0:pos":"verb","grammar:707:ex4:words:1:zh":"(nominalizer)","grammar:707:ex4:words:1:pos":"particle","grammar:707:ex4:words:2:zh":"(topic)","grammar:707:ex4:words:2:pos":"particle","grammar:707:ex4:words:3:zh":"here","grammar:707:ex4:words:3:pos":"pronoun","grammar:707:ex4:words:4:zh":"until","grammar:707:ex4:words:4:pos":"particle","grammar:707:ex4:words:5:zh":"(polite form)","grammar:707:ex4:words:5:pos":"copula","grammar:707:ex4:points:0":"ここまで: up to here.","grammar:707:ex4:points:1":"走るのはここまで: run up to here.","grammar:707:ex5:trans":"School is on holiday until March.","grammar:707:ex5:structure":"〜は〜まで〜です","grammar:707:ex5:words:0:zh":"school","grammar:707:ex5:words:0:note":"がっこう","grammar:707:ex5:words:0:pos":"noun","grammar:707:ex5:words:1:zh":"(topic)","grammar:707:ex5:words:1:pos":"particle","grammar:707:ex5:words:2:zh":"March","grammar:707:ex5:words:2:note":"さんがつ","grammar:707:ex5:words:2:pos":"noun","grammar:707:ex5:words:3:zh":"until","grammar:707:ex5:words:3:pos":"particle","grammar:707:ex5:words:4:zh":"holiday","grammar:707:ex5:words:4:note":"やすみ","grammar:707:ex5:words:4:pos":"noun","grammar:707:ex5:words:5:zh":"(polite form)","grammar:707:ex5:words:5:pos":"copula","grammar:707:ex5:points:0":"三月まで: until March.","grammar:707:ex5:points:1":"休みです: is on holiday.","exam:707:zh":"This shop is open until eight in the evening and closes at eight.","exam:707:why":"「まで」 means continuing until a certain time, and eight o'clock is the end of business hours. 「から」 marks a starting point, which would mean the shop starts business at eight."},"708":{"example:708:exzh":"I want to go, but I don't have money.","example:708:exzh2":"It's going to rain today, but I'm still going out.","example:708:exzh3":"It's difficult, but I'll do my best.","example:708:exzh4":"She's kind, but sometimes strict.","example:708:exzh5":"The book is interesting, but a little long.","grammar:708:ex:trans":"I want to go, but I don't have money.","grammar:708:ex:structure":"〜けど、〜","grammar:708:ex:explain":"The key here is the contrastive particle 「〜けど」 (but). It is very common in casual speech and corresponds to 「が／けれど」 but is more relaxed. 「行きたいけど」 means I want to go, but…, linking two opposed ideas with 「けど」. The whole sentence means: I want to go, but I don't have money. Mid-sentence, 「けど」 marks a turn in meaning, and it can also end a sentence as a soft, trailing finish (〜んだけど…). It is an extremely high-frequency connector in everyday conversation.","grammar:708:ex:words:0:zh":"want to go","grammar:708:ex:words:0:note":"いきたい","grammar:708:ex:words:0:pos":"verb","grammar:708:ex:words:1:zh":"but","grammar:708:ex:words:1:pos":"particle","grammar:708:ex:words:2:zh":"money","grammar:708:ex:words:2:note":"おかね","grammar:708:ex:words:2:pos":"noun","grammar:708:ex:words:3:zh":"(nominative)","grammar:708:ex:words:3:pos":"particle","grammar:708:ex:words:4:zh":"don't have","grammar:708:ex:words:4:pos":"adjective","grammar:708:ex:points:0":"❗〜けど: but (contrastive, casual, = が／けれど).","grammar:708:ex:points:1":"行きたいけど: I want to go, but…","grammar:708:ex2:trans":"It will rain today, but I'm going out anyway.","grammar:708:ex2:structure":"〜けど、〜ます","grammar:708:ex2:words:0:zh":"today","grammar:708:ex2:words:0:note":"きょう","grammar:708:ex2:words:0:pos":"noun","grammar:708:ex2:words:1:zh":"(topic)","grammar:708:ex2:words:1:pos":"particle","grammar:708:ex2:words:2:zh":"rain","grammar:708:ex2:words:2:note":"あめ","grammar:708:ex2:words:2:pos":"noun","grammar:708:ex2:words:3:zh":"(nominative)","grammar:708:ex2:words:3:pos":"particle","grammar:708:ex2:words:4:zh":"down","grammar:708:ex2:words:4:note":"ふる","grammar:708:ex2:words:4:pos":"verb","grammar:708:ex2:words:5:zh":"but","grammar:708:ex2:words:5:pos":"particle","grammar:708:ex2:words:6:zh":"go out","grammar:708:ex2:words:6:note":"でかけます","grammar:708:ex2:words:6:pos":"verb","grammar:708:ex2:points:0":"雨が降るけど: although it will rain.","grammar:708:ex2:points:1":"出かける: to go out.","grammar:708:ex3:trans":"It's difficult, but I'll do my best.","grammar:708:ex3:structure":"〜けど、〜ます","grammar:708:ex3:words:0:zh":"difficult","grammar:708:ex3:words:0:note":"むずかしい","grammar:708:ex3:words:0:pos":"adjective","grammar:708:ex3:words:1:zh":"but","grammar:708:ex3:words:1:pos":"particle","grammar:708:ex3:words:2:zh":"effort","grammar:708:ex3:words:2:note":"がんばります","grammar:708:ex3:words:2:pos":"verb","grammar:708:ex3:points:0":"難しいけど: although it's difficult.","grammar:708:ex3:points:1":"「頑張る」: to work hard, to do your best.","grammar:708:ex4:trans":"She is kind, but sometimes strict.","grammar:708:ex4:structure":"〜けど、時々〜","grammar:708:ex4:words:0:zh":"she","grammar:708:ex4:words:0:note":"かのじょ","grammar:708:ex4:words:0:pos":"pronoun","grammar:708:ex4:words:1:zh":"(topic)","grammar:708:ex4:words:1:pos":"particle","grammar:708:ex4:words:2:zh":"kind","grammar:708:ex4:words:2:note":"やさしい","grammar:708:ex4:words:2:pos":"adjective","grammar:708:ex4:words:3:zh":"but","grammar:708:ex4:words:3:pos":"particle","grammar:708:ex4:words:4:zh":"sometimes","grammar:708:ex4:words:4:note":"ときどき","grammar:708:ex4:words:4:pos":"adverb","grammar:708:ex4:words:5:zh":"strict","grammar:708:ex4:words:5:note":"きびしい","grammar:708:ex4:words:5:pos":"adjective","grammar:708:ex4:points:0":"優しいけど: kind, but…","grammar:708:ex4:points:1":"時々厳しい: sometimes strict.","grammar:708:ex5:trans":"The book is interesting, but a little long.","grammar:708:ex5:structure":"〜けど、ちょっと〜","grammar:708:ex5:words:0:zh":"book","grammar:708:ex5:words:0:note":"ほん","grammar:708:ex5:words:0:pos":"noun","grammar:708:ex5:words:1:zh":"(topic)","grammar:708:ex5:words:1:pos":"particle","grammar:708:ex5:words:2:zh":"interesting","grammar:708:ex5:words:2:note":"おもしろい","grammar:708:ex5:words:2:pos":"adjective","grammar:708:ex5:words:3:zh":"but","grammar:708:ex5:words:3:pos":"particle","grammar:708:ex5:words:4:zh":"a little","grammar:708:ex5:words:4:pos":"adverb","grammar:708:ex5:words:5:zh":"long","grammar:708:ex5:words:5:note":"ながい","grammar:708:ex5:words:5:pos":"adjective","grammar:708:ex5:points:0":"面白いけど: interesting, but…","grammar:708:ex5:points:1":"ちょっと長い: a little long."},"709":{"example:709:exzh":"This fish can be eaten.","example:709:exzh2":"You can see photos here.","example:709:exzh3":"The rules are followed here.","example:709:exzh4":"You can eat fresh fish at this shop.","example:709:exzh5":"I was praised by my teacher.","grammar:709:ex:trans":"This fish can be eaten.","grammar:709:ex:structure":"この魚＋は＋食べ＋られる","grammar:709:ex:explain":"「られる」 attaches to the stem of an ichidan verb and often expresses ability or possibility. The point of this sentence is not who eats the fish, but whether the fish is edible. When studying, keep the potential usage separate from the passive usage.","grammar:709:ex:words:0:zh":"this","grammar:709:ex:words:0:pos":"pre-noun adjectival","grammar:709:ex:words:1:zh":"fish","grammar:709:ex:words:1:note":"さかな: fish","grammar:709:ex:words:1:pos":"noun","grammar:709:ex:words:2:zh":"topic marker","grammar:709:ex:words:2:pos":"particle","grammar:709:ex:words:3:zh":"eat","grammar:709:ex:words:3:note":"たべ; the stem of 食べる","grammar:709:ex:words:3:pos":"verb","grammar:709:ex:words:4:zh":"be able to","grammar:709:ex:words:4:pos":"auxiliary verb","grammar:709:ex:points:0":"The 「られる」 in 「食べられる」 marks potential, meaning it can be eaten.","grammar:709:ex:points:1":"「は」 brings 「この魚」 forward as the topic, and what follows says whether it can be eaten.","grammar:709:ex2:trans":"You can see photos here.","grammar:709:ex2:structure":"ここで＋写真が＋見られる","grammar:709:ex2:words:0:zh":"here","grammar:709:ex2:words:0:pos":"pronoun","grammar:709:ex2:words:1:zh":"exist","grammar:709:ex2:words:1:pos":"particle","grammar:709:ex2:words:2:zh":"photo","grammar:709:ex2:words:2:note":"しゃしん; photo","grammar:709:ex2:words:2:pos":"noun","grammar:709:ex2:words:3:zh":"subject marker","grammar:709:ex2:words:3:pos":"particle","grammar:709:ex2:words:4:zh":"look","grammar:709:ex2:words:4:note":"み; the stem of 見る","grammar:709:ex2:words:4:pos":"verb","grammar:709:ex2:words:5:zh":"be able to","grammar:709:ex2:words:5:pos":"auxiliary verb","grammar:709:ex2:points:0":"「見られる」 uses 「られる」 to mark potential, meaning it can be seen.","grammar:709:ex2:points:1":"「ここで」 marks the place where the action happens or is possible.","grammar:709:ex3:trans":"The rules are being followed here.","grammar:709:ex3:structure":"〜が守られている","grammar:709:ex3:words:0:zh":"here","grammar:709:ex3:words:0:pos":"pronoun","grammar:709:ex3:words:1:zh":"(place)","grammar:709:ex3:words:1:pos":"particle","grammar:709:ex3:words:2:zh":"(contrast)","grammar:709:ex3:words:2:pos":"particle","grammar:709:ex3:words:3:zh":"rule","grammar:709:ex3:words:3:note":"loanword","grammar:709:ex3:words:3:pos":"noun","grammar:709:ex3:words:4:zh":"(nominative)","grammar:709:ex3:words:4:pos":"particle","grammar:709:ex3:words:5:zh":"are followed","grammar:709:ex3:words:5:note":"まもられている","grammar:709:ex3:words:5:pos":"verb","grammar:709:ex3:points:0":"❗守られる: to be followed (passive of 守る); ルールが守られる＝the rules are followed.","grammar:709:ex3:points:1":"守られる: be followed.","grammar:709:ex4:trans":"You can eat fresh fish at this shop.","grammar:709:ex4:structure":"この店では＋新鮮な魚が＋食べられる","grammar:709:ex4:words:0:zh":"this","grammar:709:ex4:words:0:pos":"pre-noun adjectival","grammar:709:ex4:words:1:zh":"store","grammar:709:ex4:words:1:note":"みせ; store","grammar:709:ex4:words:1:pos":"noun","grammar:709:ex4:words:2:zh":"exist","grammar:709:ex4:words:2:pos":"particle","grammar:709:ex4:words:3:zh":"topic marker","grammar:709:ex4:words:3:pos":"particle","grammar:709:ex4:words:4:zh":"fresh","grammar:709:ex4:words:4:note":"しんせん; fresh","grammar:709:ex4:words:4:pos":"na-adjective","grammar:709:ex4:words:5:zh":"'s","grammar:709:ex4:words:5:pos":"auxiliary verb","grammar:709:ex4:words:6:zh":"fish","grammar:709:ex4:words:6:note":"さかな: fish","grammar:709:ex4:words:6:pos":"noun","grammar:709:ex4:words:7:zh":"subject marker","grammar:709:ex4:words:7:pos":"particle","grammar:709:ex4:words:8:zh":"eat","grammar:709:ex4:words:8:note":"たべ; the stem of 食べる","grammar:709:ex4:words:8:pos":"verb","grammar:709:ex4:words:9:zh":"be able to","grammar:709:ex4:words:9:pos":"auxiliary verb","grammar:709:ex4:points:0":"The 「られる」 in 「食べられる」 marks potential, meaning you can eat it.","grammar:709:ex4:points:1":"「この店では」 marks that this holds within the scope of this shop.","grammar:709:ex5:trans":"I was praised by my teacher.","grammar:709:ex5:structure":"私は＋先生に＋ほめられました","grammar:709:ex5:words:0:zh":"I","grammar:709:ex5:words:0:note":"わたし; I","grammar:709:ex5:words:0:pos":"pronoun","grammar:709:ex5:words:1:zh":"topic marker","grammar:709:ex5:words:1:pos":"particle","grammar:709:ex5:words:2:zh":"teacher","grammar:709:ex5:words:2:note":"せんせい; teacher","grammar:709:ex5:words:2:pos":"noun","grammar:709:ex5:words:3:zh":"the doer in a passive sentence","grammar:709:ex5:words:3:pos":"particle","grammar:709:ex5:words:4:zh":"praise","grammar:709:ex5:words:4:pos":"verb","grammar:709:ex5:words:5:zh":"by","grammar:709:ex5:words:5:pos":"auxiliary verb","grammar:709:ex5:words:6:zh":"polite past","grammar:709:ex5:words:6:pos":"auxiliary verb","grammar:709:ex5:points:0":"「ほめられました」 is the ichidan verb 「ほめる」 with 「る」 dropped and 「られる」 attached; here it is passive: to be praised by the teacher.","grammar:709:ex5:points:1":"In a passive sentence, 「に」 marks the person doing the action: 「先生に」＝by the teacher.","grammar:709:ex5:points:2":"「られ＋ました」: 「られる」 conjugates like an ichidan verb, and with 「ました」 it becomes the polite past."},"711":{"example:711:exzh":"I like watching movies.","example:711:exzh2":"When I looked outside through the window, it was raining.","example:711:exzh3":"When I rode the Ferris wheel with my friend, I looked at the view.","example:711:exzh4":"Have you ever seen that flower?","example:711:exzh5":"Let's go see the stars.","grammar:711:ex:trans":"I like watching movies.","grammar:711:ex:structure":"〜のが好きです","grammar:711:ex:explain":"This sentence uses 「〜のが好きです」 to say you like doing something. 「映画を見る」 (watch a movie) is turned into a noun with 「の」, and 「が」 marks it as what 「好き」 applies to, giving the meaning of liking to watch movies. 「を」 marks 「映画」 as the object of 「見る」. The whole sentence means: I like watching movies. When you want to make an action the thing you like, use 「動詞辭書形＋のが好き」; this is an extremely common pattern.","grammar:711:ex:words:0:zh":"movie","grammar:711:ex:words:0:note":"えいが","grammar:711:ex:words:0:pos":"noun","grammar:711:ex:words:1:zh":"(object marker)","grammar:711:ex:words:1:pos":"particle","grammar:711:ex:words:2:zh":"look","grammar:711:ex:words:2:note":"みる","grammar:711:ex:words:2:pos":"verb","grammar:711:ex:words:3:zh":"(nominalizer)","grammar:711:ex:words:3:pos":"particle","grammar:711:ex:words:4:zh":"(object)","grammar:711:ex:words:4:pos":"particle","grammar:711:ex:words:5:zh":"to like","grammar:711:ex:words:5:note":"すき","grammar:711:ex:words:5:pos":"na-adjective","grammar:711:ex:words:6:zh":"(polite form)","grammar:711:ex:words:6:pos":"copula","grammar:711:ex:points:0":"映画を見る: to watch a movie.","grammar:711:ex:points:1":"〜のが好き: to like doing…","grammar:711:ex2:trans":"When I looked outside through the window, it was raining.","grammar:711:ex2:structure":"〜と、〜ていました","grammar:711:ex2:words:0:zh":"window","grammar:711:ex2:words:0:note":"まど","grammar:711:ex2:words:0:pos":"noun","grammar:711:ex2:words:1:zh":"from","grammar:711:ex2:words:1:pos":"particle","grammar:711:ex2:words:2:zh":"outside","grammar:711:ex2:words:2:note":"そと","grammar:711:ex2:words:2:pos":"noun","grammar:711:ex2:words:3:zh":"(object marker)","grammar:711:ex2:words:3:pos":"particle","grammar:711:ex2:words:4:zh":"look","grammar:711:ex2:words:4:note":"みる","grammar:711:ex2:words:4:pos":"verb","grammar:711:ex2:words:5:zh":"(as soon as…)","grammar:711:ex2:words:5:pos":"particle","grammar:711:ex2:words:6:zh":"rain","grammar:711:ex2:words:6:note":"あめ","grammar:711:ex2:words:6:pos":"noun","grammar:711:ex2:words:7:zh":"(nominative)","grammar:711:ex2:words:7:pos":"particle","grammar:711:ex2:words:8:zh":"was falling","grammar:711:ex2:words:8:note":"ふっていました","grammar:711:ex2:words:8:pos":"verb","grammar:711:ex2:points:0":"❗〜と: as soon as… (and then you find)…","grammar:711:ex2:points:1":"窓から外を見る: look outside from the window.","grammar:711:ex3:trans":"When I rode the Ferris wheel with my friend, I looked at the view.","grammar:711:ex3:structure":"人と一緒に〜に乗ったとき、景色を見ました","grammar:711:ex3:explain":"「友達と一緒に」 indicates that the person riding along is a friend. The whole clause 「観覧車に乗った」 modifies 「とき」, meaning when we rode the Ferris wheel; here it is naturally understood as once we were on board, during the ride. 「景色を見ました」 is the main statement, saying that I looked at the view at that time. The verb modifying 「とき」 is in the plain form, while the main clause ends in the polite form.","grammar:711:ex3:words:0:zh":"friend","grammar:711:ex3:words:0:note":"ともだち","grammar:711:ex3:words:0:pos":"noun","grammar:711:ex3:words:1:zh":"(the person taking part together)","grammar:711:ex3:words:1:pos":"particle","grammar:711:ex3:words:2:zh":"together","grammar:711:ex3:words:2:note":"いっしょ","grammar:711:ex3:words:2:pos":"noun","grammar:711:ex3:words:3:zh":"(「一緒に」 forming how the action is done)","grammar:711:ex3:words:3:pos":"particle","grammar:711:ex3:words:4:zh":"Ferris wheel","grammar:711:ex3:words:4:note":"かんらんしゃ","grammar:711:ex3:words:4:pos":"noun","grammar:711:ex3:words:5:zh":"(the vehicle or attraction being ridden)","grammar:711:ex3:words:5:pos":"particle","grammar:711:ex3:words:6:zh":"to ride, to board","grammar:711:ex3:words:6:note":"のっ","grammar:711:ex3:words:6:pos":"verb","grammar:711:ex3:words:7:zh":"(past, completed)","grammar:711:ex3:words:7:pos":"auxiliary verb","grammar:711:ex3:words:8:zh":"time","grammar:711:ex3:words:8:pos":"noun","grammar:711:ex3:words:9:zh":"scenery","grammar:711:ex3:words:9:note":"けしき","grammar:711:ex3:words:9:pos":"noun","grammar:711:ex3:words:10:zh":"(object)","grammar:711:ex3:words:10:pos":"particle","grammar:711:ex3:words:11:zh":"look","grammar:711:ex3:words:11:note":"み","grammar:711:ex3:words:11:pos":"verb","grammar:711:ex3:words:12:zh":"(polite tone)","grammar:711:ex3:words:12:pos":"auxiliary verb","grammar:711:ex3:words:13:zh":"(past, completed)","grammar:711:ex3:words:13:pos":"auxiliary verb","grammar:711:ex3:points:0":"「人と一緒に」 means doing something together with someone.","grammar:711:ex3:points:1":"In 「〜に乗る」, 「に」 marks the vehicle or attraction you ride.","grammar:711:ex3:points:2":"「動詞た形＋とき」 describes the situation in which an action happens or is completed.","grammar:711:ex4:trans":"Have you ever seen that flower?","grammar:711:ex4:structure":"〜たことがありますか","grammar:711:ex4:words:0:zh":"that","grammar:711:ex4:words:0:pos":"pre-noun adjectival","grammar:711:ex4:words:1:zh":"flowers","grammar:711:ex4:words:1:note":"はな","grammar:711:ex4:words:1:pos":"noun","grammar:711:ex4:words:2:zh":"(object marker)","grammar:711:ex4:words:2:pos":"particle","grammar:711:ex4:words:3:zh":"have seen","grammar:711:ex4:words:3:note":"みた","grammar:711:ex4:words:3:pos":"verb","grammar:711:ex4:words:4:zh":"(experience)","grammar:711:ex4:words:4:pos":"noun","grammar:711:ex4:words:5:zh":"(nominative)","grammar:711:ex4:words:5:pos":"particle","grammar:711:ex4:words:6:zh":"there is / are","grammar:711:ex4:words:6:pos":"verb","grammar:711:ex4:words:7:zh":"(question)","grammar:711:ex4:words:7:pos":"particle","grammar:711:ex4:points:0":"〜たことがありますか: have you ever …? (experience)","grammar:711:ex4:points:1":"花を見る: to look at flowers.","grammar:711:ex5:trans":"Let's go see the stars.","grammar:711:ex5:structure":"〜を見に行こう","grammar:711:ex5:words:0:zh":"star","grammar:711:ex5:words:0:note":"ほし","grammar:711:ex5:words:0:pos":"noun","grammar:711:ex5:words:1:zh":"(object marker)","grammar:711:ex5:words:1:pos":"particle","grammar:711:ex5:words:2:zh":"look","grammar:711:ex5:words:2:note":"み","grammar:711:ex5:words:2:pos":"noun","grammar:711:ex5:words:3:zh":"(purpose)","grammar:711:ex5:words:3:pos":"particle","grammar:711:ex5:words:4:zh":"let's go","grammar:711:ex5:words:4:note":"いこう","grammar:711:ex5:words:4:pos":"verb","grammar:711:ex5:points:0":"〜に行く: to go in order to do … (見に行く = to go see).","grammar:711:ex5:points:1":"行こう: let's go (volitional form).","exam:711:zh":"Tonight I'm planning to watch a soccer match on the TV at home.","exam:711:why":"Watching a match on TV is 「見る」. 「する」 means playing in the match yourself, which doesn't fit watching it on TV."},"712":{"example:712:exzh":"Where are you going?","example:712:exzh2":"You're really funny.","example:712:exzh3":"I'm worried about you.","example:712:exzh4":"You're strong, aren't you?","example:712:exzh5":"I want to talk with you.","grammar:712:ex:trans":"Where are you going?","grammar:712:ex:structure":"お前、〜の？","grammar:712:ex:words:0:zh":"you","grammar:712:ex:words:0:note":"おまえ","grammar:712:ex:words:0:pos":"pronoun","grammar:712:ex:words:1:zh":"where","grammar:712:ex:words:1:pos":"question word","grammar:712:ex:words:2:zh":"(destination)","grammar:712:ex:words:2:pos":"particle","grammar:712:ex:words:3:zh":"go","grammar:712:ex:words:3:note":"いく","grammar:712:ex:words:3:pos":"verb","grammar:712:ex:words:4:zh":"(question)","grammar:712:ex:words:4:pos":"particle","grammar:712:ex:points:0":"❗お前（おまえ）: you (very casual / rude, to close friends or people below you).","grammar:712:ex:points:1":"どこに行く: go where.","grammar:712:ex2:trans":"You're really funny.","grammar:712:ex2:structure":"お前は〜よ","grammar:712:ex2:words:0:zh":"you","grammar:712:ex2:words:0:note":"おまえ","grammar:712:ex2:words:0:pos":"pronoun","grammar:712:ex2:words:1:zh":"(topic)","grammar:712:ex2:words:1:pos":"particle","grammar:712:ex2:words:2:zh":"really","grammar:712:ex2:words:2:note":"ほんとうに","grammar:712:ex2:words:2:pos":"adverb","grammar:712:ex2:words:3:zh":"interesting","grammar:712:ex2:words:3:note":"おもしろい","grammar:712:ex2:words:3:pos":"adjective","grammar:712:ex2:words:4:zh":"(tone)","grammar:712:ex2:words:4:pos":"particle","grammar:712:ex2:points:0":"お前: you (rough).","grammar:712:ex2:points:1":"よ: (informing / emphasizing) tone.","grammar:712:ex3:trans":"I'm worried about you.","grammar:712:ex3:structure":"〜のことが心配だ","grammar:712:ex3:words:0:zh":"you","grammar:712:ex3:words:0:note":"おまえ","grammar:712:ex3:words:0:pos":"pronoun","grammar:712:ex3:words:1:zh":"'s","grammar:712:ex3:words:1:pos":"particle","grammar:712:ex3:words:2:zh":"thing / matter","grammar:712:ex3:words:2:pos":"noun","grammar:712:ex3:words:3:zh":"(nominative)","grammar:712:ex3:words:3:pos":"particle","grammar:712:ex3:words:4:zh":"worry","grammar:712:ex3:words:4:note":"しんぱい","grammar:712:ex3:words:4:pos":"na-adjective","grammar:712:ex3:words:5:zh":"is","grammar:712:ex3:words:5:pos":"copula","grammar:712:ex3:points:0":"❗〜のことが心配: worried about… (お前のこと = things about you / you).","grammar:712:ex3:points:1":"心配だ: worried.","grammar:712:ex4:trans":"You're strong, aren't you.","grammar:712:ex4:structure":"お前は〜ね","grammar:712:ex4:words:0:zh":"you","grammar:712:ex4:words:0:note":"おまえ","grammar:712:ex4:words:0:pos":"pronoun","grammar:712:ex4:words:1:zh":"(topic)","grammar:712:ex4:words:1:pos":"particle","grammar:712:ex4:words:2:zh":"strong","grammar:712:ex4:words:2:note":"つよい","grammar:712:ex4:words:2:pos":"adjective","grammar:712:ex4:words:3:zh":"right?","grammar:712:ex4:words:3:pos":"particle","grammar:712:ex4:points:0":"強い: strong, tough.","grammar:712:ex4:points:1":"ね: seeking agreement.","grammar:712:ex5:trans":"I want to talk with you.","grammar:712:ex5:structure":"お前と〜たい","grammar:712:ex5:words:0:zh":"you","grammar:712:ex5:words:0:note":"おまえ","grammar:712:ex5:words:0:pos":"pronoun","grammar:712:ex5:words:1:zh":"with","grammar:712:ex5:words:1:pos":"particle","grammar:712:ex5:words:2:zh":"want to talk","grammar:712:ex5:words:2:note":"はなしたい","grammar:712:ex5:words:2:pos":"verb","grammar:712:ex5:points:0":"お前と話す: talk with you.","grammar:712:ex5:points:1":"〜たい: to want to …."},"713":{"example:713:exzh":"I like talking with him.","example:713:exzh2":"Can you speak Japanese?","example:713:exzh3":"Tomorrow I'll talk about something important.","example:713:exzh4":"I had a great time talking with my friend.","example:713:exzh5":"Please speak a little more slowly.","grammar:713:ex:trans":"I like talking with him.","grammar:713:ex:structure":"〜と話すのが好きです","grammar:713:ex:explain":"The focus here is 「〜と話す」: the person you talk with is marked with 「と」, meaning to talk with…, and 「と」 carries a sense of two-way, interactive exchange. The following 「〜のが好き」 turns 「話す」 into a noun with 「の」 as the thing you like. The whole sentence means: I like talking with him. Note that the person you converse with takes 「と」, not 「に」; 「に」 is used for one-way telling, as in 「彼に言う」.","grammar:713:ex:words:0:zh":"he","grammar:713:ex:words:0:note":"かれ","grammar:713:ex:words:0:pos":"pronoun","grammar:713:ex:words:1:zh":"with","grammar:713:ex:words:1:pos":"particle","grammar:713:ex:words:2:zh":"talk","grammar:713:ex:words:2:note":"はなす","grammar:713:ex:words:2:pos":"verb","grammar:713:ex:words:3:zh":"(nominalizer)","grammar:713:ex:words:3:pos":"particle","grammar:713:ex:words:4:zh":"(object)","grammar:713:ex:words:4:pos":"particle","grammar:713:ex:words:5:zh":"to like","grammar:713:ex:words:5:note":"すき","grammar:713:ex:words:5:pos":"na-adjective","grammar:713:ex:words:6:zh":"(polite form)","grammar:713:ex:words:6:pos":"copula","grammar:713:ex:points:0":"❗〜と話す: to talk with… (the other person takes と).","grammar:713:ex:points:1":"〜のが好き: to like doing…","grammar:713:ex2:trans":"Can you speak Japanese?","grammar:713:ex2:structure":"〜を話せますか","grammar:713:ex2:words:0:zh":"Japanese","grammar:713:ex2:words:0:note":"にほんご","grammar:713:ex2:words:0:pos":"noun","grammar:713:ex2:words:1:zh":"(object marker)","grammar:713:ex2:words:1:pos":"particle","grammar:713:ex2:words:2:zh":"can speak","grammar:713:ex2:words:2:note":"はなせます","grammar:713:ex2:words:2:pos":"verb","grammar:713:ex2:words:3:zh":"(question)","grammar:713:ex2:words:3:pos":"particle","grammar:713:ex2:points:0":"❗話せる: can speak (the potential form of 話す).","grammar:713:ex2:points:1":"日本語を話せる: can speak Japanese.","grammar:713:ex3:trans":"Tomorrow I'm going to talk about something important.","grammar:713:ex3:structure":"明日は大事なことを話します","grammar:713:ex3:explain":"「明日は」 brings up tomorrow as the time being talked about, and it may also carry a contrastive tone against today or other days. 「大事なこと」 means something important, and 「を」 marks what is to be discussed. 「話します」 itself carries no past marking, so with 「明日」 it is understood as something to say or discuss tomorrow.","grammar:713:ex3:words:0:zh":"tomorrow","grammar:713:ex3:words:0:note":"あした","grammar:713:ex3:words:0:pos":"noun","grammar:713:ex3:words:1:zh":"(topic, contrast)","grammar:713:ex3:words:1:pos":"particle","grammar:713:ex3:words:2:zh":"important","grammar:713:ex3:words:2:note":"だいじ","grammar:713:ex3:words:2:pos":"na-adjective","grammar:713:ex3:words:3:zh":"(links a na-adjective to a noun)","grammar:713:ex3:words:3:pos":"auxiliary verb","grammar:713:ex3:words:4:zh":"thing / matter","grammar:713:ex3:words:4:pos":"noun","grammar:713:ex3:words:5:zh":"(what is talked about)","grammar:713:ex3:words:5:pos":"particle","grammar:713:ex3:words:6:zh":"talk, say","grammar:713:ex3:words:6:note":"はなし","grammar:713:ex3:words:6:pos":"verb","grammar:713:ex3:words:7:zh":"(polite tone)","grammar:713:ex3:words:7:pos":"auxiliary verb","grammar:713:ex3:points:0":"「大事」 is a na-adjective, so it takes 「な」 when it modifies 「こと」.","grammar:713:ex3:points:1":"「話します」 is the non-past form, so with 「明日」 it refers to a future action.","grammar:713:ex4:trans":"I had a great time talking with my friend.","grammar:713:ex4:structure":"〜と〜話せました","grammar:713:ex4:words:0:zh":"friend","grammar:713:ex4:words:0:note":"ともだち","grammar:713:ex4:words:0:pos":"noun","grammar:713:ex4:words:1:zh":"with","grammar:713:ex4:words:1:pos":"particle","grammar:713:ex4:words:2:zh":"enjoyably","grammar:713:ex4:words:2:note":"たのしく","grammar:713:ex4:words:2:pos":"adverb","grammar:713:ex4:words:3:zh":"can say","grammar:713:ex4:words:3:note":"はなせました","grammar:713:ex4:words:3:pos":"verb","grammar:713:ex4:points:0":"楽しく話せる: can talk enjoyably.","grammar:713:ex4:points:1":"話せる→話せました。","grammar:713:ex5:trans":"Please speak a little more slowly.","grammar:713:ex5:structure":"もう少し〜話してください","grammar:713:ex5:words:0:zh":"a little more","grammar:713:ex5:words:0:note":"もうすこし","grammar:713:ex5:words:0:pos":"adverb","grammar:713:ex5:words:1:zh":"slowly","grammar:713:ex5:words:1:pos":"adverb","grammar:713:ex5:words:2:zh":"tell","grammar:713:ex5:words:2:note":"はなして","grammar:713:ex5:words:2:pos":"verb","grammar:713:ex5:words:3:zh":"please","grammar:713:ex5:words:3:pos":"auxiliary verb","grammar:713:ex5:points:0":"ゆっくり話す: speak slowly.","grammar:713:ex5:points:1":"もう少し: a little more.","exam:713:zh":"On the phone you can't see the other person's face, so it's important to open your mouth wide and speak clearly.","exam:713:why":"「話す」 means to speak, which fits conveying a message clearly with your mouth. 「聞く」 means to listen, which doesn't match the action of opening your mouth and making sound."},"714":{"example:714:exzh":"I can speak Japanese.","example:714:exzh2":"He's good at playing the piano.","example:714:exzh3":"This job can be done easily.","example:714:exzh4":"She can exercise every day.","example:714:exzh5":"You can make this dish at home.","grammar:714:ex:trans":"I can speak Japanese.","grammar:714:ex:structure":"〜ことができる","grammar:714:ex:explain":"This sentence uses the ability pattern 「〜ことができる」 (be able to). A verb in the dictionary form plus 「ことができる」 expresses having the ability or the conditions to do something, so 「話すことができる」 means can speak. 「が」 marks what 「できる」 applies to. The whole sentence means: I can speak Japanese. This is one way to express potential, and it is more written and formal than the potential form of the verb (話せる). The two mean much the same and can be swapped depending on the context.","grammar:714:ex:words:0:zh":"I","grammar:714:ex:words:0:note":"わたし","grammar:714:ex:words:0:pos":"pronoun","grammar:714:ex:words:1:zh":"(topic)","grammar:714:ex:words:1:pos":"particle","grammar:714:ex:words:2:zh":"Japanese","grammar:714:ex:words:2:note":"にほんご","grammar:714:ex:words:2:pos":"noun","grammar:714:ex:words:3:zh":"(object marker)","grammar:714:ex:words:3:pos":"particle","grammar:714:ex:words:4:zh":"tell","grammar:714:ex:words:4:note":"はなす","grammar:714:ex:words:4:pos":"verb","grammar:714:ex:words:5:zh":"(nominalizer)","grammar:714:ex:words:5:pos":"noun","grammar:714:ex:words:6:zh":"(nominative)","grammar:714:ex:words:6:pos":"particle","grammar:714:ex:words:7:zh":"be able to","grammar:714:ex:words:7:pos":"verb","grammar:714:ex:points:0":"❗〜ことができる: can… (ability / possibility).","grammar:714:ex:points:1":"話すことができる: can speak.","grammar:714:ex2:trans":"He plays the piano well.","grammar:714:ex2:structure":"〜が上手にできる","grammar:714:ex2:words:0:zh":"he","grammar:714:ex2:words:0:note":"かれ","grammar:714:ex2:words:0:pos":"pronoun","grammar:714:ex2:words:1:zh":"(topic)","grammar:714:ex2:words:1:pos":"particle","grammar:714:ex2:words:2:zh":"piano","grammar:714:ex2:words:2:note":"loanword","grammar:714:ex2:words:2:pos":"noun","grammar:714:ex2:words:3:zh":"(object)","grammar:714:ex2:words:3:pos":"particle","grammar:714:ex2:words:4:zh":"skillfully","grammar:714:ex2:words:4:note":"じょうずに","grammar:714:ex2:words:4:pos":"adverb","grammar:714:ex2:words:5:zh":"can, be able to do","grammar:714:ex2:words:5:pos":"verb","grammar:714:ex2:points:0":"できる: can, be able to do (potential verb).","grammar:714:ex2:points:1":"上手にできる: do well.","grammar:714:ex3:trans":"This job can be finished easily.","grammar:714:ex3:structure":"〜は簡単にできる","grammar:714:ex3:words:0:zh":"this","grammar:714:ex3:words:0:pos":"pre-noun adjectival","grammar:714:ex3:words:1:zh":"work","grammar:714:ex3:words:1:note":"しごと","grammar:714:ex3:words:1:pos":"noun","grammar:714:ex3:words:2:zh":"(topic)","grammar:714:ex3:words:2:pos":"particle","grammar:714:ex3:words:3:zh":"easily","grammar:714:ex3:words:3:note":"かんたんに","grammar:714:ex3:words:3:pos":"adverb","grammar:714:ex3:words:4:zh":"can be done","grammar:714:ex3:words:4:pos":"verb","grammar:714:ex3:points:0":"簡単にできる: can be done easily.","grammar:714:ex3:points:1":"簡単に: easily.","grammar:714:ex4:trans":"She can exercise every day.","grammar:714:ex4:structure":"〜ことができる","grammar:714:ex4:words:0:zh":"she","grammar:714:ex4:words:0:note":"かのじょ","grammar:714:ex4:words:0:pos":"pronoun","grammar:714:ex4:words:1:zh":"(topic)","grammar:714:ex4:words:1:pos":"particle","grammar:714:ex4:words:2:zh":"every day","grammar:714:ex4:words:2:note":"まいにち","grammar:714:ex4:words:2:pos":"adverb","grammar:714:ex4:words:3:zh":"exercise","grammar:714:ex4:words:3:note":"うんどう","grammar:714:ex4:words:3:pos":"noun","grammar:714:ex4:words:4:zh":"(object marker)","grammar:714:ex4:words:4:pos":"particle","grammar:714:ex4:words:5:zh":"do","grammar:714:ex4:words:5:pos":"verb","grammar:714:ex4:words:6:zh":"(nominalizer)","grammar:714:ex4:words:6:pos":"noun","grammar:714:ex4:words:7:zh":"(nominative)","grammar:714:ex4:words:7:pos":"particle","grammar:714:ex4:words:8:zh":"be able to","grammar:714:ex4:words:8:pos":"verb","grammar:714:ex4:points:0":"運動をすることができる: can exercise.","grammar:714:ex4:points:1":"〜ことができる: to be able to…","grammar:714:ex5:trans":"This dish can be made at home.","grammar:714:ex5:structure":"〜でできる","grammar:714:ex5:words:0:zh":"this","grammar:714:ex5:words:0:pos":"pre-noun adjectival","grammar:714:ex5:words:1:zh":"dish","grammar:714:ex5:words:1:note":"りょうり","grammar:714:ex5:words:1:pos":"noun","grammar:714:ex5:words:2:zh":"(topic)","grammar:714:ex5:words:2:pos":"particle","grammar:714:ex5:words:3:zh":"one's own home","grammar:714:ex5:words:3:note":"じたく","grammar:714:ex5:words:3:pos":"noun","grammar:714:ex5:words:4:zh":"(place)","grammar:714:ex5:words:4:pos":"particle","grammar:714:ex5:words:5:zh":"can do","grammar:714:ex5:words:5:pos":"verb","grammar:714:ex5:points:0":"自宅でできる: can be made at home.","grammar:714:ex5:points:1":"❓で: the place where the cooking happens (at home).","exam:714:zh":"I can't play the piano, but I can play the guitar.","exam:714:why":"「ギターができる」 can mean being able to play the guitar, and here 「なら」 sets up the contrast. 「分かる」 means understanding and can't directly express playing ability."},"716":{"example:716:exzh":"If we have time, let's go hang out.","grammar:716:ex:trans":"If we have time, let's go out and have some fun.","grammar:716:ex:structure":"もし〜ば、〜","grammar:716:ex:explain":"This sentence uses the conditional pattern 「もし〜ば」 (if). The opening 「もし」 signals that a hypothetical is coming and pairs with the conditional form 「あれば」 (if there is), bracketing the condition at both ends. The following 「遊びに行こう」 is the volitional form of 「行く」, meaning let's go and have fun, with 「に」 marking purpose. The whole sentence means: if we have time, let's go out and have fun. 「もし」 strengthens the hypothetical tone but can often be left out.","grammar:716:ex:words:0:zh":"if","grammar:716:ex:words:0:pos":"adverb","grammar:716:ex:words:1:zh":"time","grammar:716:ex:words:1:note":"じかん","grammar:716:ex:words:1:pos":"noun","grammar:716:ex:words:2:zh":"(nominative)","grammar:716:ex:words:2:pos":"particle","grammar:716:ex:words:3:zh":"if there is","grammar:716:ex:words:3:pos":"verb","grammar:716:ex:words:4:zh":"hang out","grammar:716:ex:words:4:note":"あそび","grammar:716:ex:words:4:pos":"noun","grammar:716:ex:words:5:zh":"(purpose)","grammar:716:ex:words:5:pos":"particle","grammar:716:ex:words:6:zh":"let's go","grammar:716:ex:words:6:note":"いこう","grammar:716:ex:words:6:pos":"verb","grammar:716:ex:points:0":"❗もし〜ば: if… (もし pairs with the conditional).","grammar:716:ex:points:1":"遊びに行こう: let's go and have fun (volitional form)."},"717":{"example:717:exzh":"We're just friends."},"725":{"example:725:exzh":"Humans build society.","example:725:exzh2":"He's a kind person.","example:725:exzh3":"Human relationships are important.","example:725:exzh4":"Let's think about human nature.","example:725:exzh5":"Humans can learn.","grammar:725:ex:trans":"Humans build society.","grammar:725:ex:structure":"〜を作り上げる","grammar:725:ex:explain":"The key here is the compound verb 「作り上げる」 (to build up, to complete). It is made of 「作る」 (to make) plus 「上げる」 (to carry through to completion), and here 「上げる」 means seeing the action through to the end, stressing the result more than plain 「作る」 does. 「を」 marks the object 「社会」. The whole sentence means: humans build society. Other 「〜上げる」 compounds such as 仕上げる and 書き上げる carry the same sense of completion.","grammar:725:ex:words:0:zh":"humans","grammar:725:ex:words:0:note":"にんげん","grammar:725:ex:words:0:pos":"noun","grammar:725:ex:words:1:zh":"(topic)","grammar:725:ex:words:1:pos":"particle","grammar:725:ex:words:2:zh":"society","grammar:725:ex:words:2:note":"しゃかい","grammar:725:ex:words:2:pos":"noun","grammar:725:ex:words:3:zh":"(object marker)","grammar:725:ex:words:3:pos":"particle","grammar:725:ex:words:4:zh":"build","grammar:725:ex:words:4:note":"つくりあげる","grammar:725:ex:words:4:pos":"verb","grammar:725:ex:points:0":"人間（にんげん）: human beings, people.","grammar:725:ex:points:1":"作り上げる: to build up, to complete (作る＋上げる).","grammar:725:ex2:trans":"He is a kind person.","grammar:725:ex2:structure":"〜は〜人間です","grammar:725:ex2:words:0:zh":"he","grammar:725:ex2:words:0:note":"かれ","grammar:725:ex2:words:0:pos":"pronoun","grammar:725:ex2:words:1:zh":"(topic)","grammar:725:ex2:words:1:pos":"particle","grammar:725:ex2:words:2:zh":"kind","grammar:725:ex2:words:2:note":"やさしい","grammar:725:ex2:words:2:pos":"adjective","grammar:725:ex2:words:3:zh":"person","grammar:725:ex2:words:3:note":"にんげん","grammar:725:ex2:words:3:pos":"noun","grammar:725:ex2:words:4:zh":"is","grammar:725:ex2:words:4:pos":"copula","grammar:725:ex2:points:0":"優しい人間: a kind person.","grammar:725:ex2:points:1":"人間: a person (= 人).","grammar:725:ex3:trans":"Human relationships are important.","grammar:725:ex3:structure":"〜は大切です","grammar:725:ex3:words:0:zh":"human relationships","grammar:725:ex3:words:0:note":"にんげんかんけい","grammar:725:ex3:words:0:pos":"noun","grammar:725:ex3:words:1:zh":"(topic)","grammar:725:ex3:words:1:pos":"particle","grammar:725:ex3:words:2:zh":"important","grammar:725:ex3:words:2:note":"たいせつ","grammar:725:ex3:words:2:pos":"na-adjective","grammar:725:ex3:words:3:zh":"(polite form)","grammar:725:ex3:words:3:pos":"copula","grammar:725:ex3:points:0":"人間関係: human relationships (人間＋関係).","grammar:725:ex3:points:1":"大切です: is important.","grammar:725:ex4:trans":"Let's think about the essence of what it means to be human.","grammar:725:ex4:structure":"〜について考えよう","grammar:725:ex4:words:0:zh":"person","grammar:725:ex4:words:0:note":"にんげん","grammar:725:ex4:words:0:pos":"noun","grammar:725:ex4:words:1:zh":"'s","grammar:725:ex4:words:1:pos":"particle","grammar:725:ex4:words:2:zh":"essence","grammar:725:ex4:words:2:note":"ほんしつ","grammar:725:ex4:words:2:pos":"noun","grammar:725:ex4:words:3:zh":"about","grammar:725:ex4:words:3:pos":"set phrase","grammar:725:ex4:words:4:zh":"let's think","grammar:725:ex4:words:4:note":"かんがえよう","grammar:725:ex4:words:4:pos":"verb","grammar:725:ex4:points:0":"❗〜について: about…","grammar:725:ex4:points:1":"考えよう: let's think (volitional form).","grammar:725:ex5:trans":"Humans are able to learn.","grammar:725:ex5:structure":"〜ことができる","grammar:725:ex5:words:0:zh":"humans","grammar:725:ex5:words:0:note":"にんげん","grammar:725:ex5:words:0:pos":"noun","grammar:725:ex5:words:1:zh":"(topic)","grammar:725:ex5:words:1:pos":"particle","grammar:725:ex5:words:2:zh":"study","grammar:725:ex5:words:2:note":"まなぶ","grammar:725:ex5:words:2:pos":"verb","grammar:725:ex5:words:3:zh":"(nominalizer)","grammar:725:ex5:words:3:pos":"noun","grammar:725:ex5:words:4:zh":"(nominative)","grammar:725:ex5:words:4:pos":"particle","grammar:725:ex5:words:5:zh":"be able to","grammar:725:ex5:words:5:pos":"verb","grammar:725:ex5:points:0":"学ぶことができる: can learn.","grammar:725:ex5:points:1":"人間は: human beings (in general)."},"726":{"example:726:exzh":"There are many countries in the world.","example:726:exzh2":"She likes traveling around the world.","example:726:exzh3":"We hope for a peaceful world.","example:726:exzh4":"I want to learn about world cultures.","example:726:exzh5":"This world is mysterious.","grammar:726:ex:trans":"There are many countries in the world.","grammar:726:ex:structure":"〜には〜があります (〜 has 〜)","grammar:726:ex:explain":"This is an existence sentence of the form 「〜には〜があります」. 「世界に」 uses 「に」 to mark the location, with 「は」 added to highlight it. 「多くの国」 uses 「多く」 (many) plus 「の」 to modify 「国」, and then 「が」 marks the thing that exists, while 「あります」 states the existence of something inanimate. The whole sentence means: there are many countries in the world. 「多くの＋noun」 is a common written way of saying many…","grammar:726:ex:words:0:zh":"world","grammar:726:ex:words:0:note":"せかい","grammar:726:ex:words:0:pos":"noun","grammar:726:ex:words:1:zh":"(location of existence)","grammar:726:ex:words:1:pos":"particle","grammar:726:ex:words:2:zh":"(contrast)","grammar:726:ex:words:2:pos":"particle","grammar:726:ex:words:3:zh":"a lot","grammar:726:ex:words:3:note":"おおく","grammar:726:ex:words:3:pos":"noun","grammar:726:ex:words:4:zh":"'s","grammar:726:ex:words:4:pos":"particle","grammar:726:ex:words:5:zh":"country","grammar:726:ex:words:5:note":"くに","grammar:726:ex:words:5:pos":"noun","grammar:726:ex:words:6:zh":"(nominative)","grammar:726:ex:words:6:pos":"particle","grammar:726:ex:words:7:zh":"there is / are","grammar:726:ex:words:7:pos":"verb","grammar:726:ex:points:0":"世界（せかい）: world.","grammar:726:ex:points:1":"〜には〜がある: … has…, there is… in…","grammar:726:ex2:trans":"She likes traveling around the world.","grammar:726:ex2:structure":"〜が好きです","grammar:726:ex2:words:0:zh":"she","grammar:726:ex2:words:0:note":"かのじょ","grammar:726:ex2:words:0:pos":"pronoun","grammar:726:ex2:words:1:zh":"(topic)","grammar:726:ex2:words:1:pos":"particle","grammar:726:ex2:words:2:zh":"traveling around the world","grammar:726:ex2:words:2:note":"せかいりょこう","grammar:726:ex2:words:2:pos":"noun","grammar:726:ex2:words:3:zh":"(object)","grammar:726:ex2:words:3:pos":"particle","grammar:726:ex2:words:4:zh":"to like","grammar:726:ex2:words:4:note":"すき","grammar:726:ex2:words:4:pos":"na-adjective","grammar:726:ex2:words:5:zh":"(polite form)","grammar:726:ex2:words:5:pos":"copula","grammar:726:ex2:points:0":"世界旅行: traveling around the world.","grammar:726:ex2:points:1":"〜が好き: to like …","grammar:726:ex3:trans":"We hope for a peaceful world.","grammar:726:ex3:structure":"〜を望んでいます","grammar:726:ex3:words:0:zh":"we","grammar:726:ex3:words:0:note":"わたしたち","grammar:726:ex3:words:0:pos":"pronoun","grammar:726:ex3:words:1:zh":"(topic)","grammar:726:ex3:words:1:pos":"particle","grammar:726:ex3:words:2:zh":"peace","grammar:726:ex3:words:2:note":"へいわ","grammar:726:ex3:words:2:pos":"na-adjective","grammar:726:ex3:words:3:zh":"(attributive form)","grammar:726:ex3:words:3:pos":"auxiliary verb","grammar:726:ex3:words:4:zh":"world","grammar:726:ex3:words:4:note":"せかい","grammar:726:ex3:words:4:pos":"noun","grammar:726:ex3:words:5:zh":"(object marker)","grammar:726:ex3:words:5:pos":"particle","grammar:726:ex3:words:6:zh":"is hoping","grammar:726:ex3:words:6:note":"のぞんでいます","grammar:726:ex3:words:6:pos":"verb","grammar:726:ex3:points:0":"平和な世界: a peaceful world.","grammar:726:ex3:points:1":"望む: to hope, to wish for.","grammar:726:ex4:trans":"I want to learn about the cultures of the world.","grammar:726:ex4:structure":"〜を学びたい","grammar:726:ex4:words:0:zh":"world","grammar:726:ex4:words:0:note":"せかい","grammar:726:ex4:words:0:pos":"noun","grammar:726:ex4:words:1:zh":"'s","grammar:726:ex4:words:1:pos":"particle","grammar:726:ex4:words:2:zh":"culture","grammar:726:ex4:words:2:note":"ぶんか","grammar:726:ex4:words:2:pos":"noun","grammar:726:ex4:words:3:zh":"(object marker)","grammar:726:ex4:words:3:pos":"particle","grammar:726:ex4:words:4:zh":"want to learn","grammar:726:ex4:words:4:note":"まなびたい","grammar:726:ex4:words:4:pos":"verb","grammar:726:ex4:points:0":"世界の文化: the cultures of the world.","grammar:726:ex4:points:1":"〜たい: to want to ….","grammar:726:ex5:trans":"This world is a mysterious place.","grammar:726:ex5:structure":"〜は不思議です","grammar:726:ex5:words:0:zh":"this","grammar:726:ex5:words:0:pos":"pre-noun adjectival","grammar:726:ex5:words:1:zh":"world","grammar:726:ex5:words:1:note":"せかい","grammar:726:ex5:words:1:pos":"noun","grammar:726:ex5:words:2:zh":"(topic)","grammar:726:ex5:words:2:pos":"particle","grammar:726:ex5:words:3:zh":"mysterious, wondrous","grammar:726:ex5:words:3:note":"ふしぎ","grammar:726:ex5:words:3:pos":"na-adjective","grammar:726:ex5:words:4:zh":"(polite form)","grammar:726:ex5:words:4:pos":"copula","grammar:726:ex5:points:0":"不思議: mysterious, wondrous.","grammar:726:ex5:points:1":"この世界: this world."},"727":{"example:727:exzh":"I bought a new car.","example:727:exzh2":"I live in an area with a lot of cars.","example:727:exzh3":"May I sit in the passenger seat of the car?","example:727:exzh4":"This car is very fast.","example:727:exzh5":"Where is the parking lot?","grammar:727:ex:trans":"I bought a new car.","grammar:727:ex:structure":"〜を買いました","grammar:727:ex:explain":"This is a basic transitive sentence: 「〜を買いました」. In 「車を買う」, 「を」 marks the object 「車」, and 「買いました」 is the past polite form of 「買う」. 「新しい」 is an i-adjective modifying 「車」. The whole sentence means I bought a new car. 「車」 is read 「くるま」. This noun＋を＋verb pattern is the most fundamental transitive structure, so get comfortable with it first before expanding.","grammar:727:ex:words:0:zh":"new","grammar:727:ex:words:0:note":"あたらしい","grammar:727:ex:words:0:pos":"adjective","grammar:727:ex:words:1:zh":"car","grammar:727:ex:words:1:note":"くるま","grammar:727:ex:words:1:pos":"noun","grammar:727:ex:words:2:zh":"(object marker)","grammar:727:ex:words:2:pos":"particle","grammar:727:ex:words:3:zh":"bought","grammar:727:ex:words:3:note":"かいました","grammar:727:ex:words:3:pos":"verb","grammar:727:ex:points:0":"車 (くるま): car.","grammar:727:ex:points:1":"車を買う: to buy a car.","grammar:727:ex2:trans":"I live in an area with lots of cars.","grammar:727:ex2:structure":"〜に住んでいます","grammar:727:ex2:words:0:zh":"car","grammar:727:ex2:words:0:note":"くるま","grammar:727:ex2:words:0:pos":"noun","grammar:727:ex2:words:1:zh":"(nominative)","grammar:727:ex2:words:1:pos":"particle","grammar:727:ex2:words:2:zh":"many","grammar:727:ex2:words:2:note":"おおい","grammar:727:ex2:words:2:pos":"adjective","grammar:727:ex2:words:3:zh":"area","grammar:727:ex2:words:3:note":"ちいき","grammar:727:ex2:words:3:pos":"noun","grammar:727:ex2:words:4:zh":"(location of existence)","grammar:727:ex2:words:4:pos":"particle","grammar:727:ex2:words:5:zh":"live (there)","grammar:727:ex2:words:5:note":"すんでいます","grammar:727:ex2:words:5:pos":"verb","grammar:727:ex2:points:0":"車が多い地域: an area with many cars (attributive).","grammar:727:ex2:points:1":"〜に住む: to live in/at …","grammar:727:ex3:trans":"May I sit in the passenger seat of the car?","grammar:727:ex3:structure":"〜に座ってもいいですか","grammar:727:ex3:words:0:zh":"car","grammar:727:ex3:words:0:note":"くるま","grammar:727:ex3:words:0:pos":"noun","grammar:727:ex3:words:1:zh":"'s","grammar:727:ex3:words:1:pos":"particle","grammar:727:ex3:words:2:zh":"front passenger seat","grammar:727:ex3:words:2:note":"じょしゅせき","grammar:727:ex3:words:2:pos":"noun","grammar:727:ex3:words:3:zh":"(the destination point)","grammar:727:ex3:words:3:pos":"particle","grammar:727:ex3:words:4:zh":"sit","grammar:727:ex3:words:4:note":"すわって; the te-form of 座る","grammar:727:ex3:words:4:pos":"verb","grammar:727:ex3:words:5:zh":"even if (used to form a permission request)","grammar:727:ex3:words:5:pos":"particle","grammar:727:ex3:words:6:zh":"okay, good","grammar:727:ex3:words:6:pos":"adjective","grammar:727:ex3:words:7:zh":"(polite form)","grammar:727:ex3:words:7:pos":"copula","grammar:727:ex3:words:8:zh":"(question)","grammar:727:ex3:words:8:pos":"particle","grammar:727:ex3:points:0":"❗車の助手席: 「車 (くるま)」 plus 「の」 modifies 「助手席」, referring to the seat next to the driver in a car.","grammar:727:ex3:points:1":"「〜に座る」: the particle 「に」 marks the place you sit.","grammar:727:ex3:points:2":"「〜てもいいですか」: verb te-form ＋ もいいですか, used to politely ask permission (may I 〜?).","grammar:727:ex4:trans":"This car is very fast.","grammar:727:ex4:structure":"〜はとても〜です","grammar:727:ex4:words:0:zh":"this","grammar:727:ex4:words:0:pos":"pre-noun adjectival","grammar:727:ex4:words:1:zh":"car","grammar:727:ex4:words:1:note":"くるま","grammar:727:ex4:words:1:pos":"noun","grammar:727:ex4:words:2:zh":"(topic)","grammar:727:ex4:words:2:pos":"particle","grammar:727:ex4:words:3:zh":"extremely","grammar:727:ex4:words:3:pos":"adverb","grammar:727:ex4:words:4:zh":"fast","grammar:727:ex4:words:4:note":"はやい","grammar:727:ex4:words:4:pos":"adjective","grammar:727:ex4:words:5:zh":"(polite form)","grammar:727:ex4:words:5:pos":"copula","grammar:727:ex4:points:0":"速い: fast (in speed).","grammar:727:ex4:points:1":"この車: this car.","grammar:727:ex5:trans":"Where is the parking lot?","grammar:727:ex5:structure":"〜はどこですか","grammar:727:ex5:words:0:zh":"parking lot","grammar:727:ex5:words:0:note":"ちゅうしゃじょう","grammar:727:ex5:words:0:pos":"noun","grammar:727:ex5:words:1:zh":"(topic)","grammar:727:ex5:words:1:pos":"particle","grammar:727:ex5:words:2:zh":"where","grammar:727:ex5:words:2:pos":"question word","grammar:727:ex5:words:3:zh":"is","grammar:727:ex5:words:3:pos":"copula","grammar:727:ex5:words:4:zh":"(question)","grammar:727:ex5:words:4:pos":"particle","grammar:727:ex5:points:0":"駐車場: parking lot (駐車＋場).","grammar:727:ex5:points:1":"どこですか: where is it.","exam:727:zh":"My dad drove a car that can seat four people and took the family to the station.","exam:727:why":"The vehicle that can hold four people, is driven by dad, and takes the family to the station is a 「車」. A 「自転車」 is a bicycle, which doesn't fit four people riding."},"728":{"example:728:exzh":"It's 3:05 now.","example:728:exzh2":"Please wait just one minute.","example:728:exzh3":"I'll be five minutes late.","example:728:exzh4":"We need ten minutes to get ready.","example:728:exzh5":"Can you get there in three minutes?","grammar:728:ex:trans":"It's 3:05 right now.","grammar:728:ex:structure":"今は〜時〜分です","grammar:728:ex:explain":"「今は」 brings up the current time. 「三時」 means three o'clock and 「五分」 means five minutes, so together they make 3:05. Both 「時」 and 「分」 are units that follow a number. 「です」 politely states the time it is now, and no 「に」 marking the time of an action is needed here.","grammar:728:ex:words:0:zh":"now","grammar:728:ex:words:0:note":"いま","grammar:728:ex:words:0:pos":"noun","grammar:728:ex:words:1:zh":"(topic)","grammar:728:ex:words:1:pos":"particle","grammar:728:ex:words:2:zh":"three","grammar:728:ex:words:2:note":"さん","grammar:728:ex:words:2:pos":"numeral","grammar:728:ex:words:3:zh":"o'clock (time of day)","grammar:728:ex:words:3:note":"じ","grammar:728:ex:words:3:pos":"suffix","grammar:728:ex:words:4:zh":"five","grammar:728:ex:words:4:note":"ご","grammar:728:ex:words:4:pos":"numeral","grammar:728:ex:words:5:zh":"minute(s)","grammar:728:ex:words:5:note":"ふん","grammar:728:ex:words:5:pos":"suffix","grammar:728:ex:words:6:zh":"is (polite tone)","grammar:728:ex:words:6:pos":"auxiliary verb","grammar:728:ex:points:0":"Times are expressed as number＋時＋number＋分, and 「三時五分」 is read 「さんじごふん」.","grammar:728:ex:points:1":"「分」 is read 「ふん」 or 「ぷん」 depending on the number before it; in this sentence it's 「ふん」.","grammar:728:ex2:trans":"Please wait — just one minute.","grammar:728:ex2:structure":"〜だけ待ってください","grammar:728:ex2:words:0:zh":"one minute","grammar:728:ex2:words:0:note":"いっぷん","grammar:728:ex2:words:0:pos":"noun","grammar:728:ex2:words:1:zh":"only","grammar:728:ex2:words:1:pos":"particle","grammar:728:ex2:words:2:zh":"wait","grammar:728:ex2:words:2:note":"まって","grammar:728:ex2:words:2:pos":"verb","grammar:728:ex2:words:3:zh":"please","grammar:728:ex2:words:3:pos":"auxiliary verb","grammar:728:ex2:points:0":"❗一分 (いっぷん): one minute (with a sound change).","grammar:728:ex2:points:1":"〜だけ: only…","grammar:728:ex3:trans":"I'll be five minutes late.","grammar:728:ex3:structure":"〜分遅れます","grammar:728:ex3:words:0:zh":"five minutes","grammar:728:ex3:words:0:note":"ごふん","grammar:728:ex3:words:0:pos":"noun","grammar:728:ex3:words:1:zh":"be late","grammar:728:ex3:words:1:note":"おくれます","grammar:728:ex3:words:1:pos":"verb","grammar:728:ex3:points:0":"五分 (ごふん): five minutes.","grammar:728:ex3:points:1":"遅れる: to be late, to fall behind.","grammar:728:ex4:trans":"Sufficient preparation is needed.","grammar:728:ex4:structure":"〜が必要です","grammar:728:ex4:words:0:zh":"sufficient; enough","grammar:728:ex4:words:0:note":"じゅうぶん","grammar:728:ex4:words:0:pos":"noun","grammar:728:ex4:words:1:zh":"'s","grammar:728:ex4:words:1:pos":"particle","grammar:728:ex4:words:2:zh":"prepare","grammar:728:ex4:words:2:note":"じゅんび","grammar:728:ex4:words:2:pos":"noun","grammar:728:ex4:words:3:zh":"(nominative)","grammar:728:ex4:words:3:pos":"particle","grammar:728:ex4:words:4:zh":"necessary","grammar:728:ex4:words:4:note":"ひつよう","grammar:728:ex4:words:4:pos":"na-adjective","grammar:728:ex4:words:5:zh":"(polite form)","grammar:728:ex4:words:5:pos":"copula","grammar:728:ex4:points:0":"❗十分: read 「じゅうぶん」 = sufficient (as here); 「じゅっぷん」 = ten minutes.","grammar:728:ex4:points:1":"十分の準備: sufficient preparation.","grammar:728:ex5:trans":"Can you get there in three minutes?","grammar:728:ex5:structure":"〜で行けますか","grammar:728:ex5:words:0:zh":"three minutes","grammar:728:ex5:words:0:note":"さんぷん","grammar:728:ex5:words:0:pos":"noun","grammar:728:ex5:words:1:zh":"(within a time frame)","grammar:728:ex5:words:1:pos":"particle","grammar:728:ex5:words:2:zh":"can go","grammar:728:ex5:words:2:note":"いけます","grammar:728:ex5:words:2:pos":"verb","grammar:728:ex5:words:3:zh":"(question)","grammar:728:ex5:words:3:pos":"particle","grammar:728:ex5:points:0":"❓で: within … (a length of time).","grammar:728:ex5:points:1":"三分で行ける: can get there in three minutes.","exam:728:zh":"One hour is sixty minutes.","exam:728:why":"One hour equals sixty 「分」. 「時」 is used for the hour of the day and can't stand here for sixty minutes."},"731":{"example:731:exzh":"That place is quiet.","example:731:exzh2":"This place is my favorite.","example:731:exzh3":"Where should we meet?","example:731:exzh4":"He knows that place.","example:731:exzh5":"I moved to a new place.","grammar:731:ex:trans":"That place is quiet.","grammar:731:ex:structure":"〜は静かです","grammar:731:ex:explain":"This sentence uses the na-adjective 「静か」 (quiet) as the predicate. In 「その場所は静かです」, 「は」 marks the topic — that place — and 「静か」 plus 「です」 forms the predicate. 「場所 (ばしょ)」 means place, location. The whole sentence means that place is quiet. Remember that a na-adjective takes no 「な」 as a predicate; 「な」 is only added when it modifies a noun (静かな場所).","grammar:731:ex:words:0:zh":"that","grammar:731:ex:words:0:pos":"pre-noun adjectival","grammar:731:ex:words:1:zh":"place","grammar:731:ex:words:1:note":"ばしょ","grammar:731:ex:words:1:pos":"noun","grammar:731:ex:words:2:zh":"(topic)","grammar:731:ex:words:2:pos":"particle","grammar:731:ex:words:3:zh":"quiet","grammar:731:ex:words:3:note":"しずか","grammar:731:ex:words:3:pos":"na-adjective","grammar:731:ex:words:4:zh":"(polite form)","grammar:731:ex:words:4:pos":"copula","grammar:731:ex:points:0":"場所 (ばしょ): place, location.","grammar:731:ex:points:1":"静か: quiet.","grammar:731:ex2:trans":"This place is my favorite.","grammar:731:ex2:structure":"〜はお気に入りです","grammar:731:ex2:words:0:zh":"this","grammar:731:ex2:words:0:pos":"pre-noun adjectival","grammar:731:ex2:words:1:zh":"place","grammar:731:ex2:words:1:note":"ばしょ","grammar:731:ex2:words:1:pos":"noun","grammar:731:ex2:words:2:zh":"(topic)","grammar:731:ex2:words:2:pos":"particle","grammar:731:ex2:words:3:zh":"I","grammar:731:ex2:words:3:note":"わたし","grammar:731:ex2:words:3:pos":"pronoun","grammar:731:ex2:words:4:zh":"'s","grammar:731:ex2:words:4:pos":"particle","grammar:731:ex2:words:5:zh":"favorite","grammar:731:ex2:words:5:note":"おきにいり","grammar:731:ex2:words:5:pos":"noun","grammar:731:ex2:words:6:zh":"is","grammar:731:ex2:words:6:pos":"copula","grammar:731:ex2:points:0":"❗お気に入り: favorite (person or thing).","grammar:731:ex2:points:1":"この場所: this place.","grammar:731:ex3:trans":"Which place should we meet at?","grammar:731:ex3:structure":"どの〜で〜ますか","grammar:731:ex3:words:0:zh":"which","grammar:731:ex3:words:0:pos":"pre-noun adjectival","grammar:731:ex3:words:1:zh":"place","grammar:731:ex3:words:1:note":"ばしょ","grammar:731:ex3:words:1:pos":"noun","grammar:731:ex3:words:2:zh":"(place)","grammar:731:ex3:words:2:pos":"particle","grammar:731:ex3:words:3:zh":"meet up","grammar:731:ex3:words:3:note":"まちあわせます","grammar:731:ex3:words:3:pos":"verb","grammar:731:ex3:words:4:zh":"(question)","grammar:731:ex3:words:4:pos":"particle","grammar:731:ex3:points:0":"待ち合わせる: to meet up (as arranged).","grammar:731:ex3:points:1":"どの場所で: at which place.","grammar:731:ex4:trans":"He knows that place.","grammar:731:ex4:structure":"〜を知っている","grammar:731:ex4:words:0:zh":"he","grammar:731:ex4:words:0:note":"かれ","grammar:731:ex4:words:0:pos":"pronoun","grammar:731:ex4:words:1:zh":"(topic)","grammar:731:ex4:words:1:pos":"particle","grammar:731:ex4:words:2:zh":"that","grammar:731:ex4:words:2:pos":"pre-noun adjectival","grammar:731:ex4:words:3:zh":"place","grammar:731:ex4:words:3:note":"ばしょ","grammar:731:ex4:words:3:pos":"noun","grammar:731:ex4:words:4:zh":"(object marker)","grammar:731:ex4:words:4:pos":"particle","grammar:731:ex4:words:5:zh":"know","grammar:731:ex4:words:5:note":"しっている","grammar:731:ex4:words:5:pos":"verb","grammar:731:ex4:points:0":"場所を知る: to know a place.","grammar:731:ex4:points:1":"知っている: to know (a state).","grammar:731:ex5:trans":"I moved to a new place.","grammar:731:ex5:structure":"〜へ引っ越しました","grammar:731:ex5:words:0:zh":"new","grammar:731:ex5:words:0:note":"あたらしい","grammar:731:ex5:words:0:pos":"adjective","grammar:731:ex5:words:1:zh":"place","grammar:731:ex5:words:1:note":"ばしょ","grammar:731:ex5:words:1:pos":"noun","grammar:731:ex5:words:2:zh":"to","grammar:731:ex5:words:2:pos":"particle","grammar:731:ex5:words:3:zh":"moved","grammar:731:ex5:words:3:note":"ひっこしました","grammar:731:ex5:words:3:pos":"verb","grammar:731:ex5:points:0":"❗〜へ: toward … (direction, = に).","grammar:731:ex5:points:1":"引っ越す: to move house."},"732":{"example:732:exzh":"My father is a teacher.","example:732:exzh2":"My father runs every morning.","example:732:exzh3":"The food my father makes is delicious.","example:732:exzh4":"His father is a very kind person.","example:732:exzh5":"I went to see a movie with my father.","grammar:732:ex:trans":"My father is a teacher.","grammar:732:ex:structure":"〜は〜です","grammar:732:ex:explain":"The key point here is the humble-versus-respectful distinction in family terms. 「父 (ちち)」 is the humble word for one's own father; when referring to someone else's father you use 「お父さん」. This inside-versus-outside distinction in kinship terms matters a lot in Japanese. 「私の父は先生です」 = my father is a teacher. The whole sentence means my father is a teacher. Likewise 「母／お母さん」 and 「娘／娘さん」 each have separate forms for your own family and someone else's.","grammar:732:ex:words:0:zh":"I","grammar:732:ex:words:0:note":"わたし","grammar:732:ex:words:0:pos":"pronoun","grammar:732:ex:words:1:zh":"'s","grammar:732:ex:words:1:pos":"particle","grammar:732:ex:words:2:zh":"father","grammar:732:ex:words:2:note":"ちち","grammar:732:ex:words:2:pos":"noun","grammar:732:ex:words:3:zh":"(topic)","grammar:732:ex:words:3:pos":"particle","grammar:732:ex:words:4:zh":"teacher","grammar:732:ex:words:4:note":"せんせい","grammar:732:ex:words:4:pos":"noun","grammar:732:ex:words:5:zh":"is","grammar:732:ex:words:5:pos":"copula","grammar:732:ex:points:0":"❗父 (ちち): (humble) one's own father; for someone else's father, use お父さん.","grammar:732:ex:points:1":"先生: teacher.","grammar:732:ex2:trans":"My father goes running every morning.","grammar:732:ex2:structure":"〜は〜ます","grammar:732:ex2:words:0:zh":"father","grammar:732:ex2:words:0:note":"ちち","grammar:732:ex2:words:0:pos":"noun","grammar:732:ex2:words:1:zh":"(topic)","grammar:732:ex2:words:1:pos":"particle","grammar:732:ex2:words:2:zh":"every morning","grammar:732:ex2:words:2:note":"まいあさ","grammar:732:ex2:words:2:pos":"adverb","grammar:732:ex2:words:3:zh":"run","grammar:732:ex2:words:3:note":"はしります","grammar:732:ex2:words:3:pos":"verb","grammar:732:ex2:points:0":"毎朝: every morning.","grammar:732:ex2:points:1":"走る→走ります。","grammar:732:ex3:trans":"The food my father makes is delicious.","grammar:732:ex3:structure":"〜が作った〜は〜","grammar:732:ex3:words:0:zh":"father","grammar:732:ex3:words:0:note":"ちち","grammar:732:ex3:words:0:pos":"noun","grammar:732:ex3:words:1:zh":"(nominative)","grammar:732:ex3:words:1:pos":"particle","grammar:732:ex3:words:2:zh":"made","grammar:732:ex3:words:2:note":"つくった","grammar:732:ex3:words:2:pos":"verb","grammar:732:ex3:words:3:zh":"dish","grammar:732:ex3:words:3:note":"りょうり","grammar:732:ex3:words:3:pos":"noun","grammar:732:ex3:words:4:zh":"(topic)","grammar:732:ex3:words:4:pos":"particle","grammar:732:ex3:words:5:zh":"delicious","grammar:732:ex3:words:5:note":"おいしい","grammar:732:ex3:words:5:pos":"adjective","grammar:732:ex3:points:0":"❗父が作った料理: the food my father made (the subject inside a modifying clause takes が).","grammar:732:ex3:points:1":"美味しい: delicious.","grammar:732:ex4:trans":"His father is a very kind person.","grammar:732:ex4:structure":"〜は〜人だ","grammar:732:ex4:words:0:zh":"he","grammar:732:ex4:words:0:note":"かれ","grammar:732:ex4:words:0:pos":"pronoun","grammar:732:ex4:words:1:zh":"'s","grammar:732:ex4:words:1:pos":"particle","grammar:732:ex4:words:2:zh":"father","grammar:732:ex4:words:2:note":"ちち","grammar:732:ex4:words:2:pos":"noun","grammar:732:ex4:words:3:zh":"(topic)","grammar:732:ex4:words:3:pos":"particle","grammar:732:ex4:words:4:zh":"extremely","grammar:732:ex4:words:4:pos":"adverb","grammar:732:ex4:words:5:zh":"gentle","grammar:732:ex4:words:5:note":"やさしい","grammar:732:ex4:words:5:pos":"adjective","grammar:732:ex4:words:6:zh":"person","grammar:732:ex4:words:6:note":"ひと","grammar:732:ex4:words:6:pos":"noun","grammar:732:ex4:words:7:zh":"is","grammar:732:ex4:words:7:pos":"copula","grammar:732:ex4:points:0":"❗彼の父: his father (you can use 父, or say お父さん).","grammar:732:ex4:points:1":"優しい人: a kind person.","grammar:732:ex5:trans":"I went to see a movie with my father.","grammar:732:ex5:structure":"〜と〜を見に行きました","grammar:732:ex5:words:0:zh":"father","grammar:732:ex5:words:0:note":"ちち","grammar:732:ex5:words:0:pos":"noun","grammar:732:ex5:words:1:zh":"with","grammar:732:ex5:words:1:pos":"particle","grammar:732:ex5:words:2:zh":"together","grammar:732:ex5:words:2:note":"いっしょに","grammar:732:ex5:words:2:pos":"adverb","grammar:732:ex5:words:3:zh":"movie","grammar:732:ex5:words:3:note":"えいが","grammar:732:ex5:words:3:pos":"noun","grammar:732:ex5:words:4:zh":"(object marker)","grammar:732:ex5:words:4:pos":"particle","grammar:732:ex5:words:5:zh":"look","grammar:732:ex5:words:5:note":"み","grammar:732:ex5:words:5:pos":"noun","grammar:732:ex5:words:6:zh":"(purpose)","grammar:732:ex5:words:6:pos":"particle","grammar:732:ex5:words:7:zh":"went","grammar:732:ex5:words:7:note":"いきました","grammar:732:ex5:words:7:pos":"verb","grammar:732:ex5:points:0":"父と一緒に: together with my father.","grammar:732:ex5:points:1":"見に行く: to go to see.","exam:732:zh":"My mother's husband, the man who raised me, is my father.","exam:732:why":"What's described here is 「父」, your own father. 「祖父」 means grandfather, on either side, which doesn't fit the relationship of your mother's husband."},"733":{"example:733:exzh":"How many times have you been here?","example:733:exzh2":"No matter how many times you buy this product, the quality is the same.","example:733:exzh3":"This summer's temperature is two degrees higher than last year's.","example:733:exzh4":"She has studied English many times.","example:733:exzh5":"This dish is delicious no matter how many times you eat it.","grammar:733:ex:trans":"How many times have you been here?","grammar:733:ex:structure":"〜のは何度目ですか","grammar:733:ex:explain":"The key point here is the counter 「〜度」 (times) combined with 「目」 to form the ordinal 「何度目」 (which time). 「目」 follows a quantity to mean the …-th one. In 「ここに来るのは」, 「の」 nominalizes coming here and makes it the topic. The whole sentence means how many times have you been here? 「〜目」 is very handy, as in 「二回目」 (the second time) and 「三人目」 (the third person); both mark a position in a sequence.","grammar:733:ex:words:0:zh":"here","grammar:733:ex:words:0:pos":"pronoun","grammar:733:ex:words:1:zh":"(destination)","grammar:733:ex:words:1:pos":"particle","grammar:733:ex:words:2:zh":"come","grammar:733:ex:words:2:note":"くる","grammar:733:ex:words:2:pos":"verb","grammar:733:ex:words:3:zh":"(nominalizer)","grammar:733:ex:words:3:pos":"particle","grammar:733:ex:words:4:zh":"(topic)","grammar:733:ex:words:4:pos":"particle","grammar:733:ex:words:5:zh":"which time (how many-th time)","grammar:733:ex:words:5:note":"なんどめ","grammar:733:ex:words:5:pos":"question word","grammar:733:ex:words:6:zh":"is","grammar:733:ex:words:6:pos":"copula","grammar:733:ex:words:7:zh":"(question)","grammar:733:ex:words:7:pos":"particle","grammar:733:ex:points:0":"❗〜度 (ど): times (how many occurrences); 何度目 = which time (＋目 makes it an ordinal).","grammar:733:ex:points:1":"ここに来る: to come here.","grammar:733:ex2:trans":"No matter how many times you buy this item, the quality is the same.","grammar:733:ex2:structure":"〜は、何度〜ても、〜が同じです","grammar:733:ex2:explain":"「この品は」 brings this item up as the topic of the whole sentence, and 「品」 is read 「しな」 here. 「何度買っても」 pairs the counter word 「何度」 with 「ても」 to mean no matter how many times you buy it. 「品質が」 marks the specific item being described, and 「同じです」 states that the quality is the same. 「同じ」 is usually treated like a na-adjective, but it normally takes no 「な」 when modifying an ordinary noun, as in 「同じ品質」.","grammar:733:ex2:words:0:zh":"this","grammar:733:ex2:words:0:pos":"pre-noun adjectival","grammar:733:ex2:words:1:zh":"product","grammar:733:ex2:words:1:note":"しな","grammar:733:ex2:words:1:pos":"noun","grammar:733:ex2:words:2:zh":"(topic)","grammar:733:ex2:words:2:pos":"particle","grammar:733:ex2:words:3:zh":"how many (indefinite number of times)","grammar:733:ex2:words:3:note":"なん","grammar:733:ex2:words:3:pos":"numeral","grammar:733:ex2:words:4:zh":"times (counter for occurrences)","grammar:733:ex2:words:4:note":"ど","grammar:733:ex2:words:4:pos":"suffix","grammar:733:ex2:words:5:zh":"buy","grammar:733:ex2:words:5:note":"かっ","grammar:733:ex2:words:5:pos":"verb","grammar:733:ex2:words:6:zh":"(combines with も to form a concessive condition)","grammar:733:ex2:words:6:pos":"particle","grammar:733:ex2:words:7:zh":"no matter …","grammar:733:ex2:words:7:pos":"particle","grammar:733:ex2:words:8:zh":"quality","grammar:733:ex2:words:8:note":"ひんしつ","grammar:733:ex2:words:8:pos":"noun","grammar:733:ex2:words:9:zh":"(nominative)","grammar:733:ex2:words:9:pos":"particle","grammar:733:ex2:words:10:zh":"the same","grammar:733:ex2:words:10:note":"おなじ","grammar:733:ex2:words:10:pos":"na-adjective","grammar:733:ex2:words:11:zh":"(polite sentence-final ending)","grammar:733:ex2:words:11:pos":"auxiliary verb","grammar:733:ex2:points:0":"「何度」 is read 「なんど」 and here means an unlimited number of purchases.","grammar:733:ex2:points:1":"「何度〜ても」 means that no matter how many times you do it, the result that follows doesn't change.","grammar:733:ex2:points:2":"「同じです」 means the same; when modifying a noun, you usually say 同じ＋noun.","grammar:733:ex3:trans":"This summer's temperature is two degrees higher than last year's.","grammar:733:ex3:structure":"AはBよりも、〜が quantity＋高い","grammar:733:ex3:explain":"「今年の夏は」 makes this summer the topic. 「去年よりも」 gives the standard of comparison, understood from context as last summer's temperature, and 「も」 strengthens the comparative tone. 「気温が」 marks what is high or low. 「二度」 comes before 「高い」 to show that the margin above the comparison point is two degrees — not that the temperature is only two degrees.","grammar:733:ex3:words:0:zh":"this year","grammar:733:ex3:words:0:note":"ことし","grammar:733:ex3:words:0:pos":"noun","grammar:733:ex3:words:1:zh":"(connects a time word to a noun)","grammar:733:ex3:words:1:pos":"particle","grammar:733:ex3:words:2:zh":"summer","grammar:733:ex3:words:2:note":"なつ","grammar:733:ex3:words:2:pos":"noun","grammar:733:ex3:words:3:zh":"(topic)","grammar:733:ex3:words:3:pos":"particle","grammar:733:ex3:words:4:zh":"last year","grammar:733:ex3:words:4:note":"きょねん","grammar:733:ex3:words:4:pos":"noun","grammar:733:ex3:words:5:zh":"(standard of comparison)","grammar:733:ex3:words:5:pos":"particle","grammar:733:ex3:words:6:zh":"(strengthens the comparison)","grammar:733:ex3:words:6:pos":"particle","grammar:733:ex3:words:7:zh":"temperature","grammar:733:ex3:words:7:note":"きおん","grammar:733:ex3:words:7:pos":"noun","grammar:733:ex3:words:8:zh":"(nominative)","grammar:733:ex3:words:8:pos":"particle","grammar:733:ex3:words:9:zh":"two","grammar:733:ex3:words:9:note":"に","grammar:733:ex3:words:9:pos":"numeral","grammar:733:ex3:words:10:zh":"degree (temperature unit)","grammar:733:ex3:words:10:note":"ど","grammar:733:ex3:words:10:pos":"suffix","grammar:733:ex3:words:11:zh":"tall","grammar:733:ex3:words:11:note":"たかい","grammar:733:ex3:words:11:pos":"i-adjective","grammar:733:ex3:points:0":"「より」 marks the standard of comparison, and 「よりも」 can strengthen the comparative tone.","grammar:733:ex3:points:1":"In 「二度高い」, the number shows the size of the difference, not the actual temperature.","grammar:733:ex3:points:2":"Here 「度」 is a temperature unit, but in other sentences it can also mean times (occurrences).","grammar:733:ex4:trans":"She has studied English over and over.","grammar:733:ex4:structure":"何度も〜しています","grammar:733:ex4:words:0:zh":"she","grammar:733:ex4:words:0:note":"かのじょ","grammar:733:ex4:words:0:pos":"pronoun","grammar:733:ex4:words:1:zh":"(topic)","grammar:733:ex4:words:1:pos":"particle","grammar:733:ex4:words:2:zh":"English","grammar:733:ex4:words:2:note":"えいご","grammar:733:ex4:words:2:pos":"noun","grammar:733:ex4:words:3:zh":"(object marker)","grammar:733:ex4:words:3:pos":"particle","grammar:733:ex4:words:4:zh":"many times","grammar:733:ex4:words:4:note":"なんども","grammar:733:ex4:words:4:pos":"adverb","grammar:733:ex4:words:5:zh":"has been studying","grammar:733:ex4:words:5:note":"べんきょうしています","grammar:733:ex4:words:5:pos":"verb","grammar:733:ex4:points:0":"❗何度も: many times, over and over.","grammar:733:ex4:points:1":"英語を勉強する: to study English.","grammar:733:ex5:trans":"No matter how many times you eat this dish, it's delicious.","grammar:733:ex5:structure":"〜は、何度食べてもおいしい","grammar:733:ex5:explain":"「この料理は」 brings this dish up as the topic. 「何度」 means how many times, but in 「何度食べても」 it doesn't ask for a number of times — it expresses no matter how many times you eat it. 「食べて」 plus 「も」 forms a concessive condition: even if you eat it repeatedly, the evaluation that follows still holds. 「おいしい」 is an i-adjective that can stand at the end of the sentence as a plain affirmative.","grammar:733:ex5:words:0:zh":"this","grammar:733:ex5:words:0:pos":"pre-noun adjectival","grammar:733:ex5:words:1:zh":"dish, cooking","grammar:733:ex5:words:1:note":"りょうり","grammar:733:ex5:words:1:pos":"noun","grammar:733:ex5:words:2:zh":"(topic)","grammar:733:ex5:words:2:pos":"particle","grammar:733:ex5:words:3:zh":"how many (indefinite number of times)","grammar:733:ex5:words:3:note":"なん","grammar:733:ex5:words:3:pos":"numeral","grammar:733:ex5:words:4:zh":"times (counter for occurrences)","grammar:733:ex5:words:4:note":"ど","grammar:733:ex5:words:4:pos":"suffix","grammar:733:ex5:words:5:zh":"eat","grammar:733:ex5:words:5:note":"たべ","grammar:733:ex5:words:5:pos":"verb","grammar:733:ex5:words:6:zh":"(combines with も to form a concessive condition)","grammar:733:ex5:words:6:pos":"particle","grammar:733:ex5:words:7:zh":"no matter …","grammar:733:ex5:words:7:pos":"particle","grammar:733:ex5:words:8:zh":"delicious","grammar:733:ex5:words:8:pos":"i-adjective","grammar:733:ex5:points:0":"「何度〜ても」 means that no matter how many times something is repeated, the result stays the same.","grammar:733:ex5:points:1":"The te-form of 「食べる」 is made by dropping 「る」 and adding 「て」, giving 「食べて」."},"734":{"example:734:exzh":"I want new shoes.","example:734:exzh2":"He said he wants a toy.","example:734:exzh3":"This is the book I want.","example:734:exzh4":"What do you want?","example:734:exzh5":"The child said he wanted ice cream.","grammar:734:ex:trans":"I want a new pair of shoes.","grammar:734:ex:structure":"〜は〜が欲しいです","grammar:734:ex:explain":"This is the wanting pattern 「〜が欲しい」 (to want …). The thing you want is marked with 「が」: 「靴が欲しい」 = I want shoes. 「欲しい」 is an i-adjective that, like 「好き」, takes its object with 「が」. 「新しい」 modifies 「靴」. The whole sentence means I want a new pair of shoes. Note that 「〜が欲しい」 is for wanting a thing; to say you want to do something, use 「〜たい」. Don't mix the two up.","grammar:734:ex:words:0:zh":"I","grammar:734:ex:words:0:note":"わたし","grammar:734:ex:words:0:pos":"pronoun","grammar:734:ex:words:1:zh":"(topic)","grammar:734:ex:words:1:pos":"particle","grammar:734:ex:words:2:zh":"new","grammar:734:ex:words:2:note":"あたらしい","grammar:734:ex:words:2:pos":"adjective","grammar:734:ex:words:3:zh":"shoes","grammar:734:ex:words:3:note":"くつ","grammar:734:ex:words:3:pos":"noun","grammar:734:ex:words:4:zh":"(object)","grammar:734:ex:words:4:pos":"particle","grammar:734:ex:words:5:zh":"to want to","grammar:734:ex:words:5:note":"ほしい","grammar:734:ex:words:5:pos":"adjective","grammar:734:ex:words:6:zh":"(polite form)","grammar:734:ex:words:6:pos":"copula","grammar:734:ex:points:0":"❗〜が欲しい: to want … (the object of 欲しい takes が).","grammar:734:ex:points:1":"新しい靴: new shoes.","grammar:734:ex2:trans":"He said he wanted a toy.","grammar:734:ex2:structure":"〜が欲しいと言っていました","grammar:734:ex2:words:0:zh":"he","grammar:734:ex2:words:0:note":"かれ","grammar:734:ex2:words:0:pos":"pronoun","grammar:734:ex2:words:1:zh":"(topic)","grammar:734:ex2:words:1:pos":"particle","grammar:734:ex2:words:2:zh":"toy","grammar:734:ex2:words:2:pos":"noun","grammar:734:ex2:words:3:zh":"(object)","grammar:734:ex2:words:3:pos":"particle","grammar:734:ex2:words:4:zh":"to want to","grammar:734:ex2:words:4:note":"ほしい","grammar:734:ex2:words:4:pos":"adjective","grammar:734:ex2:words:5:zh":"(quotation)","grammar:734:ex2:words:5:pos":"particle","grammar:734:ex2:words:6:zh":"was saying","grammar:734:ex2:words:6:note":"いっていました","grammar:734:ex2:words:6:pos":"verb","grammar:734:ex2:points:0":"❗For a third person's wanting, add 〜と言っていた／〜がっている (欲しがる).","grammar:734:ex2:points:1":"おもちゃが欲しい: to want a toy.","grammar:734:ex3:trans":"This is the book I want.","grammar:734:ex3:structure":"〜が〜欲しい〜です","grammar:734:ex3:words:0:zh":"this","grammar:734:ex3:words:0:pos":"pronoun","grammar:734:ex3:words:1:zh":"(nominative)","grammar:734:ex3:words:1:pos":"particle","grammar:734:ex3:words:2:zh":"I","grammar:734:ex3:words:2:note":"わたし","grammar:734:ex3:words:2:pos":"pronoun","grammar:734:ex3:words:3:zh":"'s","grammar:734:ex3:words:3:pos":"particle","grammar:734:ex3:words:4:zh":"to want to","grammar:734:ex3:words:4:note":"ほしい","grammar:734:ex3:words:4:pos":"adjective","grammar:734:ex3:words:5:zh":"book","grammar:734:ex3:words:5:note":"ほん","grammar:734:ex3:words:5:pos":"noun","grammar:734:ex3:words:6:zh":"is","grammar:734:ex3:words:6:pos":"copula","grammar:734:ex3:points:0":"私の欲しい本: the book I want (欲しい modifying a noun attributively).","grammar:734:ex3:points:1":"❓が: (emphasis) this very one.","grammar:734:ex4:trans":"What do you want?","grammar:734:ex4:structure":"何が欲しいですか","grammar:734:ex4:words:0:zh":"you","grammar:734:ex4:words:0:pos":"pronoun","grammar:734:ex4:words:1:zh":"(topic)","grammar:734:ex4:words:1:pos":"particle","grammar:734:ex4:words:2:zh":"what","grammar:734:ex4:words:2:note":"なに","grammar:734:ex4:words:2:pos":"question word","grammar:734:ex4:words:3:zh":"(object)","grammar:734:ex4:words:3:pos":"particle","grammar:734:ex4:words:4:zh":"to want to","grammar:734:ex4:words:4:note":"ほしい","grammar:734:ex4:words:4:pos":"adjective","grammar:734:ex4:words:5:zh":"(polite form)","grammar:734:ex4:words:5:pos":"copula","grammar:734:ex4:words:6:zh":"(question)","grammar:734:ex4:words:6:pos":"particle","grammar:734:ex4:points:0":"何が欲しい: to want what (the object takes が).","grammar:734:ex4:points:1":"欲しい: to want.","grammar:734:ex5:trans":"The child said he wanted ice cream.","grammar:734:ex5:structure":"〜が欲しいと言いました","grammar:734:ex5:words:0:zh":"child","grammar:734:ex5:words:0:note":"こども","grammar:734:ex5:words:0:pos":"noun","grammar:734:ex5:words:1:zh":"(topic)","grammar:734:ex5:words:1:pos":"particle","grammar:734:ex5:words:2:zh":"ice cream","grammar:734:ex5:words:2:note":"loanword","grammar:734:ex5:words:2:pos":"noun","grammar:734:ex5:words:3:zh":"(object)","grammar:734:ex5:words:3:pos":"particle","grammar:734:ex5:words:4:zh":"to want to","grammar:734:ex5:words:4:note":"ほしい","grammar:734:ex5:words:4:pos":"adjective","grammar:734:ex5:words:5:zh":"(quotation)","grammar:734:ex5:words:5:pos":"particle","grammar:734:ex5:words:6:zh":"said","grammar:734:ex5:words:6:note":"いいました","grammar:734:ex5:words:6:pos":"verb","grammar:734:ex5:points:0":"アイスクリームが欲しい: to want ice cream.","grammar:734:ex5:points:1":"〜と言いました: to say that … (quotation).","exam:734:zh":"I want a new bicycle, so I'm saving money.","exam:734:why":"「欲しい」 means wanting something, which fits the goal of saving money to buy it. 「重い」 means heavy, and it can't explain the motivation to buy here."},"735":{"example:735:exzh":"We go to the same school.","example:735:exzh2":"He and I have the same hobbies.","example:735:exzh3":"That problem is the same for us.","example:735:exzh4":"We live in the same town.","example:735:exzh5":"This is a photo of the same friend of mine.","grammar:735:ex:trans":"We go to the same school.","grammar:735:ex:structure":"同じ〜に通っています","grammar:735:ex:explain":"The key point here is the unusual part of speech of 「同じ」 (same). In meaning, 「同じ」 behaves like a na-adjective, but it takes no 「な」 before a noun — you simply say 「同じ学校」 (the same school). That's where it's the exception. 「〜に通う」 means to go back and forth regularly (to school, to work), with 「に」 marking the place you go to. The whole sentence means we go to the same school. The fact that 「同じ」 takes no 「な」 before a noun is a common exam point.","grammar:735:ex:words:0:zh":"we","grammar:735:ex:words:0:note":"わたしたち","grammar:735:ex:words:0:pos":"pronoun","grammar:735:ex:words:1:zh":"(topic)","grammar:735:ex:words:1:pos":"particle","grammar:735:ex:words:2:zh":"the same","grammar:735:ex:words:2:note":"おなじ","grammar:735:ex:words:2:pos":"pre-noun adjectival","grammar:735:ex:words:3:zh":"school","grammar:735:ex:words:3:note":"がっこう","grammar:735:ex:words:3:pos":"noun","grammar:735:ex:words:4:zh":"(place you go to regularly)","grammar:735:ex:words:4:pos":"particle","grammar:735:ex:words:5:zh":"attend","grammar:735:ex:words:5:note":"かよっています","grammar:735:ex:words:5:pos":"verb","grammar:735:ex:points:0":"❗同じ: same (a pre-noun adjectival that attaches directly to a noun, without な).","grammar:735:ex:points:1":"〜に通う: to attend (school).","grammar:735:ex2:trans":"He and I have the same hobby.","grammar:735:ex2:structure":"〜は同じ〜を持っています","grammar:735:ex2:words:0:zh":"he","grammar:735:ex2:words:0:note":"かれ","grammar:735:ex2:words:0:pos":"pronoun","grammar:735:ex2:words:1:zh":"with","grammar:735:ex2:words:1:pos":"particle","grammar:735:ex2:words:2:zh":"I","grammar:735:ex2:words:2:note":"わたし","grammar:735:ex2:words:2:pos":"pronoun","grammar:735:ex2:words:3:zh":"(topic)","grammar:735:ex2:words:3:pos":"particle","grammar:735:ex2:words:4:zh":"the same","grammar:735:ex2:words:4:note":"おなじ","grammar:735:ex2:words:4:pos":"pre-noun adjectival","grammar:735:ex2:words:5:zh":"interest","grammar:735:ex2:words:5:note":"しゅみ","grammar:735:ex2:words:5:pos":"noun","grammar:735:ex2:words:6:zh":"(object marker)","grammar:735:ex2:words:6:pos":"particle","grammar:735:ex2:words:7:zh":"there is / are","grammar:735:ex2:words:7:note":"もっています","grammar:735:ex2:words:7:pos":"verb","grammar:735:ex2:points:0":"同じ趣味: the same hobby.","grammar:735:ex2:points:1":"趣味を持つ: to have a hobby.","grammar:735:ex3:trans":"That problem is the same for us.","grammar:735:ex3:structure":"〜にとっては同じです","grammar:735:ex3:words:0:zh":"that","grammar:735:ex3:words:0:pos":"pre-noun adjectival","grammar:735:ex3:words:1:zh":"problem","grammar:735:ex3:words:1:note":"もんだい","grammar:735:ex3:words:1:pos":"noun","grammar:735:ex3:words:2:zh":"(topic)","grammar:735:ex3:words:2:pos":"particle","grammar:735:ex3:words:3:zh":"we","grammar:735:ex3:words:3:note":"わたしたち","grammar:735:ex3:words:3:pos":"pronoun","grammar:735:ex3:words:4:zh":"for …","grammar:735:ex3:words:4:pos":"set phrase","grammar:735:ex3:words:5:zh":"the same","grammar:735:ex3:words:5:note":"おなじ","grammar:735:ex3:words:5:pos":"na-adjective","grammar:735:ex3:words:6:zh":"(polite form)","grammar:735:ex3:words:6:pos":"copula","grammar:735:ex3:points:0":"❗〜にとっては: for … / from …'s point of view.","grammar:735:ex3:points:1":"同じです: is the same.","grammar:735:ex4:trans":"We live in the same town.","grammar:735:ex4:structure":"同じ〜に住んでいます","grammar:735:ex4:words:0:zh":"we","grammar:735:ex4:words:0:note":"わたしたち","grammar:735:ex4:words:0:pos":"pronoun","grammar:735:ex4:words:1:zh":"(topic)","grammar:735:ex4:words:1:pos":"particle","grammar:735:ex4:words:2:zh":"the same","grammar:735:ex4:words:2:note":"おなじ","grammar:735:ex4:words:2:pos":"pre-noun adjectival","grammar:735:ex4:words:3:zh":"town","grammar:735:ex4:words:3:note":"まち","grammar:735:ex4:words:3:pos":"noun","grammar:735:ex4:words:4:zh":"(location of existence)","grammar:735:ex4:words:4:pos":"particle","grammar:735:ex4:words:5:zh":"live (there)","grammar:735:ex4:words:5:note":"すんでいます","grammar:735:ex4:words:5:pos":"verb","grammar:735:ex4:points:0":"同じ町: the same town.","grammar:735:ex4:points:1":"〜に住む: to live in/at …","grammar:735:ex5:trans":"This is a photo of the same friend of mine.","grammar:735:ex5:structure":"〜の写真です","grammar:735:ex5:words:0:zh":"this","grammar:735:ex5:words:0:pos":"pronoun","grammar:735:ex5:words:1:zh":"(topic)","grammar:735:ex5:words:1:pos":"particle","grammar:735:ex5:words:2:zh":"I","grammar:735:ex5:words:2:note":"わたし","grammar:735:ex5:words:2:pos":"pronoun","grammar:735:ex5:words:3:zh":"'s","grammar:735:ex5:words:3:pos":"particle","grammar:735:ex5:words:4:zh":"the same","grammar:735:ex5:words:4:note":"おなじ","grammar:735:ex5:words:4:pos":"pre-noun adjectival","grammar:735:ex5:words:5:zh":"friend","grammar:735:ex5:words:5:note":"ともだち","grammar:735:ex5:words:5:pos":"noun","grammar:735:ex5:words:6:zh":"'s","grammar:735:ex5:words:6:pos":"particle","grammar:735:ex5:words:7:zh":"photo","grammar:735:ex5:words:7:note":"しゃしん","grammar:735:ex5:words:7:pos":"noun","grammar:735:ex5:words:8:zh":"is","grammar:735:ex5:words:8:pos":"copula","grammar:735:ex5:points:0":"同じ友達: the same friend.","grammar:735:ex5:points:1":"※ The original sentence is a bit stiff (the position of 「同じ」 isn't very natural).","exam:735:zh":"My bag and my little sister's bag are both red, so the two are the same color.","exam:735:why":"Both bags are red, so 「同じ」 is used. 「違う」 means different, the opposite of the earlier information."},"736":{"example:736:exzh":"Is this gold?","example:736:exzh2":"I want to buy a gold ring.","example:736:exzh3":"I don't have enough money to buy gold.","example:736:exzh4":"The price of gold is rising.","example:736:exzh5":"My father bought a little gold.","grammar:736:ex:trans":"Is this gold?","grammar:736:ex:structure":"これは + 金ですか","grammar:736:ex:explain":"On this card, 「金」 is read 「きん」, not 「かね」 meaning money. The sentence asks whether this is gold, directly showing the gold meaning. To talk about money in general, Japanese usually says 「お金」.","grammar:736:ex:words:0:zh":"this","grammar:736:ex:words:0:pos":"pronoun","grammar:736:ex:words:1:zh":"topic","grammar:736:ex:words:1:pos":"particle","grammar:736:ex:words:2:zh":"gold","grammar:736:ex:words:2:note":"きん","grammar:736:ex:words:2:pos":"noun","grammar:736:ex:words:3:zh":"is","grammar:736:ex:words:3:pos":"copula","grammar:736:ex:words:4:zh":"question","grammar:736:ex:words:4:pos":"particle","grammar:736:ex:points:0":"When 「金」 is read 「きん」, it means gold.","grammar:736:ex:points:1":"The 「か」 at the end turns the sentence into a question.","grammar:736:ex2:trans":"I want to buy a gold ring.","grammar:736:ex2:structure":"〜を買いたい","grammar:736:ex2:words:0:zh":"gold","grammar:736:ex2:words:0:note":"きん","grammar:736:ex2:words:0:pos":"noun","grammar:736:ex2:words:1:zh":"'s","grammar:736:ex2:words:1:pos":"particle","grammar:736:ex2:words:2:zh":"ring","grammar:736:ex2:words:2:note":"ゆびわ","grammar:736:ex2:words:2:pos":"noun","grammar:736:ex2:words:3:zh":"(object marker)","grammar:736:ex2:words:3:pos":"particle","grammar:736:ex2:words:4:zh":"want to buy","grammar:736:ex2:words:4:note":"かいたい","grammar:736:ex2:words:4:pos":"verb","grammar:736:ex2:points:0":"❗金 (きん): gold; 金の指輪 = a gold ring.","grammar:736:ex2:points:1":"〜たい: to want to ….","grammar:736:ex3:trans":"I don't have enough money to buy gold.","grammar:736:ex3:structure":"［〜を買う］お金が足りないです","grammar:736:ex3:explain":"In 「金を買うお金」, the part 「金を買う」 explains what the money is for — the money needed to buy gold. 「お金が足りない」 means there isn't enough money, and 「足りない」 is the negative form of 「足りる」. Adding 「です」 at the end makes it polite; you can also say 「足りません」. The two 「金」 s differ in reading and meaning, so judge each by the words it appears with.","grammar:736:ex3:words:0:zh":"gold","grammar:736:ex3:words:0:note":"きん","grammar:736:ex3:words:0:pos":"noun","grammar:736:ex3:words:1:zh":"(marks the object being bought)","grammar:736:ex3:words:1:pos":"particle","grammar:736:ex3:words:2:zh":"buy","grammar:736:ex3:words:2:note":"かう","grammar:736:ex3:words:2:pos":"verb","grammar:736:ex3:words:3:zh":"(polite, beautifying prefix)","grammar:736:ex3:words:3:pos":"prefix","grammar:736:ex3:words:4:zh":"money","grammar:736:ex3:words:4:note":"かね","grammar:736:ex3:words:4:pos":"noun","grammar:736:ex3:words:5:zh":"(nominative)","grammar:736:ex3:words:5:pos":"particle","grammar:736:ex3:words:6:zh":"enough","grammar:736:ex3:words:6:note":"たり","grammar:736:ex3:words:6:pos":"verb","grammar:736:ex3:words:7:zh":"(negative)","grammar:736:ex3:words:7:pos":"auxiliary verb","grammar:736:ex3:words:8:zh":"(polite tone)","grammar:736:ex3:words:8:pos":"auxiliary verb","grammar:736:ex3:points:0":"In this sentence the first 「金」 is read 「きん」 and means gold; 「お金」 is read 「おかね」 and means money.","grammar:736:ex3:points:1":"「金を買う」 modifies 「お金」, meaning the money used to buy gold.","grammar:736:ex3:points:2":"「足りる」 is an intransitive verb, so the thing that is insufficient is marked with 「が」.","grammar:736:ex4:trans":"The price of gold is rising.","grammar:736:ex4:structure":"〜が高くなっています","grammar:736:ex4:words:0:zh":"gold","grammar:736:ex4:words:0:note":"きん","grammar:736:ex4:words:0:pos":"noun","grammar:736:ex4:words:1:zh":"'s","grammar:736:ex4:words:1:pos":"particle","grammar:736:ex4:words:2:zh":"price","grammar:736:ex4:words:2:note":"かかく","grammar:736:ex4:words:2:pos":"noun","grammar:736:ex4:words:3:zh":"(topic)","grammar:736:ex4:words:3:pos":"particle","grammar:736:ex4:words:4:zh":"is getting higher","grammar:736:ex4:words:4:note":"たかくなっています","grammar:736:ex4:words:4:pos":"verb","grammar:736:ex4:points:0":"金 (きん) の価格: the price of gold.","grammar:736:ex4:points:1":"高くなる: to become expensive (adjective く＋なる).","grammar:736:ex5:trans":"My father bought a little gold.","grammar:736:ex5:structure":"父は + 金を少し + 買いました","grammar:736:ex5:words:0:zh":"dad","grammar:736:ex5:words:0:note":"ちち","grammar:736:ex5:words:0:pos":"noun","grammar:736:ex5:words:1:zh":"topic","grammar:736:ex5:words:1:pos":"particle","grammar:736:ex5:words:2:zh":"gold","grammar:736:ex5:words:2:note":"きん","grammar:736:ex5:words:2:pos":"noun","grammar:736:ex5:words:3:zh":"object marker","grammar:736:ex5:words:3:pos":"particle","grammar:736:ex5:words:4:zh":"just a little bit","grammar:736:ex5:words:4:note":"すこし","grammar:736:ex5:words:4:pos":"adverb","grammar:736:ex5:words:5:zh":"bought","grammar:736:ex5:words:5:note":"かいました; past masu-form","grammar:736:ex5:words:5:pos":"verb","grammar:736:ex5:points:0":"Here 「金」 is read 「きん」 and means gold, the metal.","grammar:736:ex5:points:1":"「少し」 comes before the verb and means a small amount.","exam:736:zh":"This ring isn't made of silver; it's made of gold that shines yellow.","exam:736:why":"「金」 means gold, which matches the description of the ring's material and its yellow shine. 「銀」 is also a common ring material, but the sentence's 「銀ではなく」 already rules it out."},"737":{"example:737:exzh":"It's difficult to solve this problem.","example:737:exzh2":"The problem isn't solved.","example:737:exzh3":"A new problem has come up.","example:737:exzh4":"I'll think it over so I can solve the problem.","example:737:exzh5":"I'll deal with that problem right away.","grammar:737:ex:trans":"Solving this problem is difficult.","grammar:737:ex:structure":"〜のは難しいです","grammar:737:ex:explain":"This sentence uses 「〜のは難しい」 (it's hard to …) to judge difficulty. 「問題を解く」 (to solve a problem) is nominalized with 「の」 and made the topic, then 「難しい」 is added. Note that solving takes the transitive verb 「解く」, with the object marked by 「を」. The whole sentence means solving this problem is difficult. 「〜のは難しい／簡単だ」 is a common frame for commenting on how hard or easy an action is.","grammar:737:ex:words:0:zh":"this","grammar:737:ex:words:0:pos":"pre-noun adjectival","grammar:737:ex:words:1:zh":"problem","grammar:737:ex:words:1:note":"もんだい","grammar:737:ex:words:1:pos":"noun","grammar:737:ex:words:2:zh":"(object marker)","grammar:737:ex:words:2:pos":"particle","grammar:737:ex:words:3:zh":"solve","grammar:737:ex:words:3:note":"とく","grammar:737:ex:words:3:pos":"verb","grammar:737:ex:words:4:zh":"(nominalizer)","grammar:737:ex:words:4:pos":"particle","grammar:737:ex:words:5:zh":"(topic)","grammar:737:ex:words:5:pos":"particle","grammar:737:ex:words:6:zh":"difficult","grammar:737:ex:words:6:note":"むずかしい","grammar:737:ex:words:6:pos":"adjective","grammar:737:ex:words:7:zh":"(polite form)","grammar:737:ex:words:7:pos":"copula","grammar:737:ex:points:0":"❗問題を解く: to solve a problem (using 解く).","grammar:737:ex:points:1":"〜のは難しい: it is hard to…","grammar:737:ex2:trans":"The problem isn't getting resolved.","grammar:737:ex2:structure":"〜が解決しない","grammar:737:ex2:words:0:zh":"problem","grammar:737:ex2:words:0:note":"もんだい","grammar:737:ex2:words:0:pos":"noun","grammar:737:ex2:words:1:zh":"(nominative)","grammar:737:ex2:words:1:pos":"particle","grammar:737:ex2:words:2:zh":"doesn't get resolved","grammar:737:ex2:words:2:note":"かいけつしない","grammar:737:ex2:words:2:pos":"verb","grammar:737:ex2:points:0":"問題が解決する: the problem resolves (itself) — intransitive usage.","grammar:737:ex2:points:1":"解決しない: isn't resolved.","grammar:737:ex3:trans":"A new problem came up.","grammar:737:ex3:structure":"〜が発生しました","grammar:737:ex3:words:0:zh":"new","grammar:737:ex3:words:0:note":"あたらしい","grammar:737:ex3:words:0:pos":"adjective","grammar:737:ex3:words:1:zh":"problem","grammar:737:ex3:words:1:note":"もんだい","grammar:737:ex3:words:1:pos":"noun","grammar:737:ex3:words:2:zh":"(nominative)","grammar:737:ex3:words:2:pos":"particle","grammar:737:ex3:words:3:zh":"occurred","grammar:737:ex3:words:3:note":"はっせいしました","grammar:737:ex3:words:3:pos":"verb","grammar:737:ex3:points:0":"発生する: to occur (intransitive verb; the subject takes が).","grammar:737:ex3:points:1":"新しい問題: a new problem.","grammar:737:ex4:trans":"I'll think about it in order to solve the problem.","grammar:737:ex4:structure":"〜ために〜ます","grammar:737:ex4:words:0:zh":"problem","grammar:737:ex4:words:0:note":"もんだい","grammar:737:ex4:words:0:pos":"noun","grammar:737:ex4:words:1:zh":"(object marker)","grammar:737:ex4:words:1:pos":"particle","grammar:737:ex4:words:2:zh":"solve","grammar:737:ex4:words:2:note":"かいけつする","grammar:737:ex4:words:2:pos":"verb","grammar:737:ex4:words:3:zh":"for the sake of","grammar:737:ex4:words:3:pos":"particle","grammar:737:ex4:words:4:zh":"think","grammar:737:ex4:words:4:note":"かんがえます","grammar:737:ex4:words:4:pos":"verb","grammar:737:ex4:points:0":"問題を解決する: to solve a problem.","grammar:737:ex4:points:1":"〜ために: in order to….","grammar:737:ex5:trans":"I'll deal with that problem right away.","grammar:737:ex5:structure":"〜はすぐに〜します","grammar:737:ex5:words:0:zh":"that","grammar:737:ex5:words:0:pos":"pre-noun adjectival","grammar:737:ex5:words:1:zh":"problem","grammar:737:ex5:words:1:note":"もんだい","grammar:737:ex5:words:1:pos":"noun","grammar:737:ex5:words:2:zh":"(topic)","grammar:737:ex5:words:2:pos":"particle","grammar:737:ex5:words:3:zh":"immediately","grammar:737:ex5:words:3:pos":"adverb","grammar:737:ex5:words:4:zh":"deal with","grammar:737:ex5:words:4:note":"たいしょします","grammar:737:ex5:words:4:pos":"verb","grammar:737:ex5:points:0":"すぐに: immediately, right away.","grammar:737:ex5:points:1":"対処する: to deal with, to handle."},"738":{"example:738:exzh":"Can you see such a beautiful view?","example:738:exzh2":"This is the first time I've experienced anything like this.","example:738:exzh3":"I've never seen a dog this big.","example:738:exzh4":"It's rude to talk like this.","example:738:exzh5":"I won't go out wearing clothes like this.","grammar:738:ex:trans":"Can you see such beautiful scenery?","grammar:738:ex:structure":"こんな〜が見えますか","grammar:738:ex:explain":"The key points here are the pre-noun adjectival 「こんな」 and the intransitive verb 「見える」. こんな＋noun means this kind of, such a …, part of the こそあど series. 「見える」 is an intransitive verb meaning to be visible, to come into view; its subject is marked with 「が」, emphasizing that something enters your sight naturally — different from 「見る」, which is actively looking. The whole sentence means can you see such beautiful scenery? The fact that the object of 「見える」 takes 「が」 is the main point.","grammar:738:ex:words:0:zh":"so; this much","grammar:738:ex:words:0:pos":"pre-noun adjectival","grammar:738:ex:words:1:zh":"beautiful","grammar:738:ex:words:1:note":"うつくしい","grammar:738:ex:words:1:pos":"adjective","grammar:738:ex:words:2:zh":"scenery","grammar:738:ex:words:2:note":"けしき","grammar:738:ex:words:2:pos":"noun","grammar:738:ex:words:3:zh":"(nominative)","grammar:738:ex:words:3:pos":"particle","grammar:738:ex:words:4:zh":"can see (is visible)","grammar:738:ex:words:4:note":"みえます","grammar:738:ex:words:4:pos":"verb","grammar:738:ex:words:5:zh":"(question)","grammar:738:ex:words:5:pos":"particle","grammar:738:ex:points:0":"❗こんな＋noun: this kind of, such a … (part of the こそあど series).","grammar:738:ex:points:1":"見える: to be visible (intransitive verb; the subject takes が).","grammar:738:ex2:trans":"This is the first time I've had something like this happen.","grammar:738:ex2:structure":"こんな〜は初めてです","grammar:738:ex2:words:0:zh":"such a","grammar:738:ex2:words:0:pos":"pre-noun adjectival","grammar:738:ex2:words:1:zh":"thing / matter","grammar:738:ex2:words:1:pos":"noun","grammar:738:ex2:words:2:zh":"(topic)","grammar:738:ex2:words:2:pos":"particle","grammar:738:ex2:words:3:zh":"the first time","grammar:738:ex2:words:3:note":"はじめて","grammar:738:ex2:words:3:pos":"noun","grammar:738:ex2:words:4:zh":"is","grammar:738:ex2:words:4:pos":"copula","grammar:738:ex2:points:0":"こんなこと: this kind of thing.","grammar:738:ex2:points:1":"初めて: for the first time.","grammar:738:ex3:trans":"I've never seen such a big dog.","grammar:738:ex3:structure":"こんなに〜たことがありません","grammar:738:ex3:words:0:zh":"so; this much","grammar:738:ex3:words:0:pos":"adverb","grammar:738:ex3:words:1:zh":"big","grammar:738:ex3:words:1:note":"おおきな","grammar:738:ex3:words:1:pos":"pre-noun adjectival","grammar:738:ex3:words:2:zh":"dog","grammar:738:ex3:words:2:note":"いぬ","grammar:738:ex3:words:2:pos":"noun","grammar:738:ex3:words:3:zh":"(topic)","grammar:738:ex3:words:3:pos":"particle","grammar:738:ex3:words:4:zh":"have seen","grammar:738:ex3:words:4:note":"みた","grammar:738:ex3:words:4:pos":"verb","grammar:738:ex3:words:5:zh":"(experience)","grammar:738:ex3:words:5:pos":"noun","grammar:738:ex3:words:6:zh":"(nominative)","grammar:738:ex3:words:6:pos":"particle","grammar:738:ex3:words:7:zh":"don't have","grammar:738:ex3:words:7:pos":"verb","grammar:738:ex3:points:0":"❗こんなに: so … (＋degree).","grammar:738:ex3:points:1":"〜たことがありません: have never …","grammar:738:ex4:trans":"Talking like this is rude.","grammar:738:ex4:structure":"こんな風に〜のは失礼です","grammar:738:ex4:words:0:zh":"like this","grammar:738:ex4:words:0:pos":"pre-noun adjectival","grammar:738:ex4:words:1:zh":"way / method","grammar:738:ex4:words:1:note":"ふう","grammar:738:ex4:words:1:pos":"noun","grammar:738:ex4:words:2:zh":"(manner)","grammar:738:ex4:words:2:pos":"particle","grammar:738:ex4:words:3:zh":"tell","grammar:738:ex4:words:3:note":"はなす","grammar:738:ex4:words:3:pos":"verb","grammar:738:ex4:words:4:zh":"(nominalizer)","grammar:738:ex4:words:4:pos":"particle","grammar:738:ex4:words:5:zh":"(topic)","grammar:738:ex4:words:5:pos":"particle","grammar:738:ex4:words:6:zh":"rude","grammar:738:ex4:words:6:note":"しつれい","grammar:738:ex4:words:6:pos":"na-adjective","grammar:738:ex4:words:7:zh":"(polite form)","grammar:738:ex4:words:7:pos":"copula","grammar:738:ex4:points:0":"❗こんな風に: like this (風 = way, manner).","grammar:738:ex4:points:1":"失礼: rude, impolite.","grammar:738:ex5:trans":"I won't go out wearing clothes like this.","grammar:738:ex5:structure":"こんな〜を着て〜ません","grammar:738:ex5:words:0:zh":"such a","grammar:738:ex5:words:0:pos":"pre-noun adjectival","grammar:738:ex5:words:1:zh":"clothes","grammar:738:ex5:words:1:note":"ふく","grammar:738:ex5:words:1:pos":"noun","grammar:738:ex5:words:2:zh":"(object marker)","grammar:738:ex5:words:2:pos":"particle","grammar:738:ex5:words:3:zh":"wear","grammar:738:ex5:words:3:note":"きて","grammar:738:ex5:words:3:pos":"verb","grammar:738:ex5:words:4:zh":"not going out","grammar:738:ex5:words:4:note":"でかけません","grammar:738:ex5:words:4:pos":"verb","grammar:738:ex5:points:0":"こんな服: clothes like this.","grammar:738:ex5:points:1":"〜て: te-form connection (wear + go out)."},"739":{"example:739:exzh":"This dish is really delicious.","example:739:exzh2":"There's lots of delicious food.","example:739:exzh3":"This is a delicious sweet.","example:739:exzh4":"I want to drink some good alcohol.","example:739:exzh5":"His cooking is always delicious.","grammar:739:ex:trans":"This dish is really delicious.","grammar:739:ex:structure":"〜は本当に〜","grammar:739:ex:explain":"This sentence uses the adverb 「本当に」 (really) to strengthen the adjective. 「本当に＋おいしい」 = really delicious, and 「本当に」 emphasizes degree or authenticity. 「は」 marks the topic 「この料理」, and 「おいしい（美味しい）」 is an i-adjective acting as the predicate, here in plain form. The whole sentence means \"This dish is really delicious.\" 「本当に」 is a very common emphatic adverb that can modify adjectives or verbs.","grammar:739:ex:words:0:zh":"this","grammar:739:ex:words:0:pos":"pre-noun adjectival","grammar:739:ex:words:1:zh":"dish","grammar:739:ex:words:1:note":"りょうり","grammar:739:ex:words:1:pos":"noun","grammar:739:ex:words:2:zh":"(topic)","grammar:739:ex:words:2:pos":"particle","grammar:739:ex:words:3:zh":"really","grammar:739:ex:words:3:note":"ほんとうに","grammar:739:ex:words:3:pos":"adverb","grammar:739:ex:words:4:zh":"delicious","grammar:739:ex:words:4:pos":"adjective","grammar:739:ex:points:0":"おいしい（美味しい）: delicious, tasty.","grammar:739:ex:points:1":"本当に: really.","grammar:739:ex2:trans":"There's lots of delicious food.","grammar:739:ex2:structure":"〜がたくさんあります","grammar:739:ex2:words:0:zh":"delicious","grammar:739:ex2:words:0:pos":"adjective","grammar:739:ex2:words:1:zh":"food","grammar:739:ex2:words:1:note":"たべもの","grammar:739:ex2:words:1:pos":"noun","grammar:739:ex2:words:2:zh":"(nominative)","grammar:739:ex2:words:2:pos":"particle","grammar:739:ex2:words:3:zh":"a lot","grammar:739:ex2:words:3:pos":"adverb","grammar:739:ex2:words:4:zh":"there is / are","grammar:739:ex2:words:4:pos":"verb","grammar:739:ex2:points:0":"おいしい食べ物: delicious food.","grammar:739:ex2:points:1":"〜がたくさんあります: there are many ….","grammar:739:ex3:trans":"This is a delicious dessert.","grammar:739:ex3:structure":"これは〜です","grammar:739:ex3:words:0:zh":"this","grammar:739:ex3:words:0:pos":"pronoun","grammar:739:ex3:words:1:zh":"(topic)","grammar:739:ex3:words:1:pos":"particle","grammar:739:ex3:words:2:zh":"delicious","grammar:739:ex3:words:2:pos":"adjective","grammar:739:ex3:words:3:zh":"dessert","grammar:739:ex3:words:3:note":"loanword","grammar:739:ex3:words:3:pos":"noun","grammar:739:ex3:words:4:zh":"is","grammar:739:ex3:words:4:pos":"copula","grammar:739:ex3:points:0":"スイーツ: dessert.","grammar:739:ex3:points:1":"おいしいスイーツ: a delicious dessert.","grammar:739:ex4:trans":"I want to drink some good alcohol.","grammar:739:ex4:structure":"〜を飲みたいです","grammar:739:ex4:words:0:zh":"delicious","grammar:739:ex4:words:0:pos":"adjective","grammar:739:ex4:words:1:zh":"alcohol, sake","grammar:739:ex4:words:1:note":"おさけ","grammar:739:ex4:words:1:pos":"noun","grammar:739:ex4:words:2:zh":"(object marker)","grammar:739:ex4:words:2:pos":"particle","grammar:739:ex4:words:3:zh":"want to drink","grammar:739:ex4:words:3:note":"のみたい","grammar:739:ex4:words:3:pos":"verb","grammar:739:ex4:words:4:zh":"(polite form)","grammar:739:ex4:words:4:pos":"copula","grammar:739:ex4:points:0":"お酒を飲む: to drink alcohol.","grammar:739:ex4:points:1":"〜たい: to want to ….","grammar:739:ex5:trans":"His cooking is always delicious.","grammar:739:ex5:structure":"〜はいつも〜です","grammar:739:ex5:words:0:zh":"he","grammar:739:ex5:words:0:note":"かれ","grammar:739:ex5:words:0:pos":"pronoun","grammar:739:ex5:words:1:zh":"'s","grammar:739:ex5:words:1:pos":"particle","grammar:739:ex5:words:2:zh":"dish / cuisine","grammar:739:ex5:words:2:note":"りょうり","grammar:739:ex5:words:2:pos":"noun","grammar:739:ex5:words:3:zh":"(topic)","grammar:739:ex5:words:3:pos":"particle","grammar:739:ex5:words:4:zh":"always","grammar:739:ex5:words:4:pos":"adverb","grammar:739:ex5:words:5:zh":"delicious","grammar:739:ex5:words:5:pos":"adjective","grammar:739:ex5:words:6:zh":"(polite form)","grammar:739:ex5:words:6:pos":"copula","grammar:739:ex5:points:0":"彼の料理: his cooking.","grammar:739:ex5:points:1":"いつもおいしい: always delicious.","exam:739:zh":"This soup is really good, so I want another bowl.","exam:739:why":"「美味しい」 means food or drink tastes good, which fits the reason for wanting another bowl. 「まずい」 means it tastes bad, the opposite."},"740":{"example:740:exzh":"My daughter is very cute.","example:740:exzh2":"She has two daughters.","example:740:exzh3":"I'm going out to have fun with my daughter.","example:740:exzh4":"My daughter went off to school full of energy.","example:740:exzh5":"My daughter likes music.","grammar:740:ex:trans":"My daughter is very cute.","grammar:740:ex:structure":"〜は〜です","grammar:740:ex:explain":"The key point here is the humble family term 「娘（むすめ）」, which refers to your own daughter; for someone else's daughter you use 「娘さん／お嬢さん」. 「私の娘は〜です」 = my daughter is … . In 「とても可愛い」, 「とても」 modifies 「可愛い」. The whole sentence means \"My daughter is very cute.\" Learn Japanese family terms in pairs — humble for your own family, respectful for other people's — because using the wrong one is rude.","grammar:740:ex:words:0:zh":"I","grammar:740:ex:words:0:note":"わたし","grammar:740:ex:words:0:pos":"pronoun","grammar:740:ex:words:1:zh":"'s","grammar:740:ex:words:1:pos":"particle","grammar:740:ex:words:2:zh":"daughter","grammar:740:ex:words:2:note":"むすめ","grammar:740:ex:words:2:pos":"noun","grammar:740:ex:words:3:zh":"(topic)","grammar:740:ex:words:3:pos":"particle","grammar:740:ex:words:4:zh":"extremely","grammar:740:ex:words:4:pos":"adverb","grammar:740:ex:words:5:zh":"cute","grammar:740:ex:words:5:note":"かわいい","grammar:740:ex:words:5:pos":"adjective","grammar:740:ex:words:6:zh":"(polite form)","grammar:740:ex:words:6:pos":"copula","grammar:740:ex:points:0":"❗娘（むすめ）: (humble) one's own daughter; for someone else's daughter use 娘さん／お嬢さん.","grammar:740:ex:points:1":"可愛い: cute.","grammar:740:ex2:trans":"She has two daughters.","grammar:740:ex2:structure":"〜には〜がいます","grammar:740:ex2:words:0:zh":"she","grammar:740:ex2:words:0:note":"かのじょ","grammar:740:ex2:words:0:pos":"pronoun","grammar:740:ex2:words:1:zh":"(object)","grammar:740:ex2:words:1:pos":"particle","grammar:740:ex2:words:2:zh":"(contrast)","grammar:740:ex2:words:2:pos":"particle","grammar:740:ex2:words:3:zh":"daughter","grammar:740:ex2:words:3:note":"むすめ","grammar:740:ex2:words:3:pos":"noun","grammar:740:ex2:words:4:zh":"(nominative)","grammar:740:ex2:words:4:pos":"particle","grammar:740:ex2:words:5:zh":"two people","grammar:740:ex2:words:5:note":"ふたり","grammar:740:ex2:words:5:pos":"noun","grammar:740:ex2:words:6:zh":"there is / are","grammar:740:ex2:words:6:pos":"verb","grammar:740:ex2:points:0":"〜には〜がいる: (someone) has … (a person).","grammar:740:ex2:points:1":"二人: two people.","grammar:740:ex3:trans":"I'm going out to have some fun with my daughter.","grammar:740:ex3:structure":"〜と遊びに行きます","grammar:740:ex3:words:0:zh":"daughter","grammar:740:ex3:words:0:note":"むすめ","grammar:740:ex3:words:0:pos":"noun","grammar:740:ex3:words:1:zh":"with","grammar:740:ex3:words:1:pos":"particle","grammar:740:ex3:words:2:zh":"hang out","grammar:740:ex3:words:2:note":"あそび","grammar:740:ex3:words:2:pos":"noun","grammar:740:ex3:words:3:zh":"(purpose)","grammar:740:ex3:words:3:pos":"particle","grammar:740:ex3:words:4:zh":"go","grammar:740:ex3:words:4:pos":"verb","grammar:740:ex3:points:0":"娘と: with my daughter.","grammar:740:ex3:points:1":"遊びに行く: to go out and have fun.","grammar:740:ex4:trans":"My daughter went off to school in good spirits.","grammar:740:ex4:structure":"〜に行った","grammar:740:ex4:words:0:zh":"daughter","grammar:740:ex4:words:0:note":"むすめ","grammar:740:ex4:words:0:pos":"noun","grammar:740:ex4:words:1:zh":"(topic)","grammar:740:ex4:words:1:pos":"particle","grammar:740:ex4:words:2:zh":"in good spirits","grammar:740:ex4:words:2:note":"げんきに","grammar:740:ex4:words:2:pos":"adverb","grammar:740:ex4:words:3:zh":"school","grammar:740:ex4:words:3:note":"がっこう","grammar:740:ex4:words:3:pos":"noun","grammar:740:ex4:words:4:zh":"(destination)","grammar:740:ex4:words:4:pos":"particle","grammar:740:ex4:words:5:zh":"went","grammar:740:ex4:words:5:note":"いった","grammar:740:ex4:words:5:pos":"verb","grammar:740:ex4:points:0":"元気に: in good spirits (元気 + に, turned into an adverb).","grammar:740:ex4:points:1":"「学校に行く」: to go to school.","grammar:740:ex5:trans":"My daughter likes music.","grammar:740:ex5:structure":"〜は〜が好きです","grammar:740:ex5:words:0:zh":"I","grammar:740:ex5:words:0:note":"わたし","grammar:740:ex5:words:0:pos":"pronoun","grammar:740:ex5:words:1:zh":"'s","grammar:740:ex5:words:1:pos":"particle","grammar:740:ex5:words:2:zh":"daughter","grammar:740:ex5:words:2:note":"むすめ","grammar:740:ex5:words:2:pos":"noun","grammar:740:ex5:words:3:zh":"(topic)","grammar:740:ex5:words:3:pos":"particle","grammar:740:ex5:words:4:zh":"music","grammar:740:ex5:words:4:note":"おんがく","grammar:740:ex5:words:4:pos":"noun","grammar:740:ex5:words:5:zh":"(object)","grammar:740:ex5:words:5:pos":"particle","grammar:740:ex5:words:6:zh":"to like","grammar:740:ex5:words:6:note":"すき","grammar:740:ex5:words:6:pos":"na-adjective","grammar:740:ex5:words:7:zh":"(polite form)","grammar:740:ex5:words:7:pos":"copula","grammar:740:ex5:points:0":"音楽が好き: to like music.","grammar:740:ex5:points:1":"私の娘: my daughter."},"741":{"example:741:exzh":"My son loves soccer.","example:741:exzh2":"My son often studies hard.","example:741:exzh3":"His son is a high school student.","example:741:exzh4":"I bought a present for my son.","example:741:exzh5":"The son plays with friends every day.","grammar:741:ex:trans":"My son loves soccer.","grammar:741:ex:structure":"〜は〜が大好きです","grammar:741:ex:explain":"This sentence also involves the humble family term 「息子（むすこ）」, one's own son; for someone else's son you use 「息子さん」. In the preference pattern 「〜が大好きです」, the object 「サッカー」 is marked with 「が」, and 「大好き」 means to love something, a stronger degree than 「好き」. The whole sentence means \"My son loves soccer.\" The object of 「大好き」 and 「大嫌い」 likewise takes 「が」.","grammar:741:ex:words:0:zh":"son","grammar:741:ex:words:0:note":"むすこ","grammar:741:ex:words:0:pos":"noun","grammar:741:ex:words:1:zh":"(topic)","grammar:741:ex:words:1:pos":"particle","grammar:741:ex:words:2:zh":"soccer","grammar:741:ex:words:2:note":"loanword","grammar:741:ex:words:2:pos":"noun","grammar:741:ex:words:3:zh":"(object)","grammar:741:ex:words:3:pos":"particle","grammar:741:ex:words:4:zh":"love","grammar:741:ex:words:4:note":"だいすき","grammar:741:ex:words:4:pos":"na-adjective","grammar:741:ex:words:5:zh":"(polite form)","grammar:741:ex:words:5:pos":"copula","grammar:741:ex:points:0":"❗息子（むすこ）: (humble) one's own son; for someone else's son use 息子さん.","grammar:741:ex:points:1":"大好き: to love, to like very much.","grammar:741:ex2:trans":"My son often studies hard.","grammar:741:ex2:structure":"〜はよく〜します","grammar:741:ex2:words:0:zh":"I","grammar:741:ex2:words:0:note":"わたし","grammar:741:ex2:words:0:pos":"pronoun","grammar:741:ex2:words:1:zh":"'s","grammar:741:ex2:words:1:pos":"particle","grammar:741:ex2:words:2:zh":"son","grammar:741:ex2:words:2:note":"むすこ","grammar:741:ex2:words:2:pos":"noun","grammar:741:ex2:words:3:zh":"(topic)","grammar:741:ex2:words:3:pos":"particle","grammar:741:ex2:words:4:zh":"often","grammar:741:ex2:words:4:pos":"adverb","grammar:741:ex2:words:5:zh":"study","grammar:741:ex2:words:5:note":"べんきょうします","grammar:741:ex2:words:5:pos":"verb","grammar:741:ex2:points:0":"よく: often; it can also mean properly, doing something thoroughly.","grammar:741:ex2:points:1":"勉強する: to study.","grammar:741:ex3:trans":"His son is a high school student.","grammar:741:ex3:structure":"〜は〜です","grammar:741:ex3:words:0:zh":"he","grammar:741:ex3:words:0:note":"かれ","grammar:741:ex3:words:0:pos":"pronoun","grammar:741:ex3:words:1:zh":"'s","grammar:741:ex3:words:1:pos":"particle","grammar:741:ex3:words:2:zh":"son","grammar:741:ex3:words:2:note":"むすこ","grammar:741:ex3:words:2:pos":"noun","grammar:741:ex3:words:3:zh":"(topic)","grammar:741:ex3:words:3:pos":"particle","grammar:741:ex3:words:4:zh":"high school student","grammar:741:ex3:words:4:note":"こうこうせい","grammar:741:ex3:words:4:pos":"noun","grammar:741:ex3:words:5:zh":"is","grammar:741:ex3:words:5:pos":"copula","grammar:741:ex3:points:0":"高校生: high school student.","grammar:741:ex3:points:1":"彼の息子: his son.","grammar:741:ex4:trans":"I bought a present for my son.","grammar:741:ex4:structure":"〜に〜を買いました","grammar:741:ex4:words:0:zh":"son","grammar:741:ex4:words:0:note":"むすこ","grammar:741:ex4:words:0:pos":"noun","grammar:741:ex4:words:1:zh":"(object)","grammar:741:ex4:words:1:pos":"particle","grammar:741:ex4:words:2:zh":"present","grammar:741:ex4:words:2:note":"loanword","grammar:741:ex4:words:2:pos":"noun","grammar:741:ex4:words:3:zh":"(object marker)","grammar:741:ex4:words:3:pos":"particle","grammar:741:ex4:words:4:zh":"bought","grammar:741:ex4:words:4:note":"かいました","grammar:741:ex4:words:4:pos":"verb","grammar:741:ex4:points:0":"❗〜に〜を買う: to buy … for … (the recipient takes に).","grammar:741:ex4:points:1":"プレゼント: present, gift.","grammar:741:ex5:trans":"My son plays with his friends every day.","grammar:741:ex5:structure":"〜と遊びます","grammar:741:ex5:words:0:zh":"son","grammar:741:ex5:words:0:note":"むすこ","grammar:741:ex5:words:0:pos":"noun","grammar:741:ex5:words:1:zh":"(topic)","grammar:741:ex5:words:1:pos":"particle","grammar:741:ex5:words:2:zh":"every day","grammar:741:ex5:words:2:note":"まいにち","grammar:741:ex5:words:2:pos":"adverb","grammar:741:ex5:words:3:zh":"friend","grammar:741:ex5:words:3:note":"ともだち","grammar:741:ex5:words:3:pos":"noun","grammar:741:ex5:words:4:zh":"with","grammar:741:ex5:words:4:pos":"particle","grammar:741:ex5:words:5:zh":"hang out","grammar:741:ex5:words:5:note":"あそびます","grammar:741:ex5:words:5:pos":"verb","grammar:741:ex5:points:0":"友達と遊ぶ: to hang out with a friend","grammar:741:ex5:points:1":"毎日: every day."},"742":{"example:742:exzh":"Let's get off at the next station.","example:742:exzh2":"It's your turn next.","example:742:exzh3":"I'm looking forward to the next story.","example:742:exzh4":"Let's meet next Sunday.","example:742:exzh5":"Let's solve the next problem.","grammar:742:ex:trans":"Let's get off at the next station.","grammar:742:ex:structure":"〜で降りましょう","grammar:742:ex:explain":"The key point here is 「〜で降りる」 (to get off at …); the place where you get off is marked with 「で」, because getting off is an action. In 「次の駅で降りましょう」, 「〜ましょう」 is an invitation meaning let's …. The whole sentence means \"Let's get off at the next station.\" Keep the particles straight with travel verbs: to board is 「電車に乗る（に）」, to get off the train is 「電車を降りる（を）」, and to get off at a station is 「駅で降りる（で）」.","grammar:742:ex:words:0:zh":"next","grammar:742:ex:words:0:note":"つぎ","grammar:742:ex:words:0:pos":"noun","grammar:742:ex:words:1:zh":"'s","grammar:742:ex:words:1:pos":"particle","grammar:742:ex:words:2:zh":"station","grammar:742:ex:words:2:note":"えき","grammar:742:ex:words:2:pos":"noun","grammar:742:ex:words:3:zh":"(place of the action)","grammar:742:ex:words:3:pos":"particle","grammar:742:ex:words:4:zh":"let's get off","grammar:742:ex:words:4:note":"おりましょう","grammar:742:ex:words:4:pos":"verb","grammar:742:ex:points:0":"次の駅: the next station.","grammar:742:ex:points:1":"❗〜で降りる: to get off at … (で for place).","grammar:742:ex2:trans":"Next up is your turn.","grammar:742:ex2:structure":"〜は〜の番です","grammar:742:ex2:words:0:zh":"next","grammar:742:ex2:words:0:note":"つぎ","grammar:742:ex2:words:0:pos":"noun","grammar:742:ex2:words:1:zh":"(topic)","grammar:742:ex2:words:1:pos":"particle","grammar:742:ex2:words:2:zh":"you","grammar:742:ex2:words:2:pos":"pronoun","grammar:742:ex2:words:3:zh":"'s","grammar:742:ex2:words:3:pos":"particle","grammar:742:ex2:words:4:zh":"one's turn","grammar:742:ex2:words:4:note":"ばん","grammar:742:ex2:words:4:pos":"noun","grammar:742:ex2:words:5:zh":"is","grammar:742:ex2:words:5:pos":"copula","grammar:742:ex2:points:0":"❗〜の番: it's …'s turn (番 = order, turn).","grammar:742:ex2:points:1":"次は: next.","grammar:742:ex3:trans":"I'm looking forward to the next story.","grammar:742:ex3:structure":"〜を楽しみにしています","grammar:742:ex3:words:0:zh":"next","grammar:742:ex3:words:0:note":"つぎ","grammar:742:ex3:words:0:pos":"noun","grammar:742:ex3:words:1:zh":"'s","grammar:742:ex3:words:1:pos":"particle","grammar:742:ex3:words:2:zh":"story","grammar:742:ex3:words:2:note":"はなし","grammar:742:ex3:words:2:pos":"noun","grammar:742:ex3:words:3:zh":"(object marker)","grammar:742:ex3:words:3:pos":"particle","grammar:742:ex3:words:4:zh":"looking forward to","grammar:742:ex3:words:4:note":"たのしみにしています","grammar:742:ex3:words:4:pos":"verb","grammar:742:ex3:points:0":"❗〜を楽しみにする: to look forward to ….","grammar:742:ex3:points:1":"次の話: the next story.","grammar:742:ex4:trans":"Let's meet next Sunday.","grammar:742:ex4:structure":"〜に会いましょう","grammar:742:ex4:words:0:zh":"next","grammar:742:ex4:words:0:note":"つぎ","grammar:742:ex4:words:0:pos":"noun","grammar:742:ex4:words:1:zh":"'s","grammar:742:ex4:words:1:pos":"particle","grammar:742:ex4:words:2:zh":"Sunday","grammar:742:ex4:words:2:note":"にちようび","grammar:742:ex4:words:2:pos":"noun","grammar:742:ex4:words:3:zh":"(point in time)","grammar:742:ex4:words:3:pos":"particle","grammar:742:ex4:words:4:zh":"let's meet","grammar:742:ex4:words:4:note":"あいましょう","grammar:742:ex4:words:4:pos":"verb","grammar:742:ex4:points:0":"次の日曜日: next Sunday.","grammar:742:ex4:points:1":"〜に会いましょう: let's meet (at …).","grammar:742:ex5:trans":"Let's solve the next problem.","grammar:742:ex5:structure":"〜を解きましょう","grammar:742:ex5:words:0:zh":"next","grammar:742:ex5:words:0:note":"つぎ","grammar:742:ex5:words:0:pos":"noun","grammar:742:ex5:words:1:zh":"'s","grammar:742:ex5:words:1:pos":"particle","grammar:742:ex5:words:2:zh":"problem","grammar:742:ex5:words:2:note":"もんだい","grammar:742:ex5:words:2:pos":"noun","grammar:742:ex5:words:3:zh":"(object marker)","grammar:742:ex5:words:3:pos":"particle","grammar:742:ex5:words:4:zh":"let's solve it","grammar:742:ex5:words:4:note":"ときましょう","grammar:742:ex5:words:4:pos":"verb","grammar:742:ex5:points:0":"問題を解く: to solve a problem.","grammar:742:ex5:points:1":"〜ましょう: a suggestion.","exam:742:zh":"I couldn't get on the train that just came, so I'll wait for the next one.","exam:742:why":"「次の電車」 means the next train. 「前」 means before, and you can't wait for a train that has already left."},"743":{"example:743:exzh":"I'm worried about his health.","example:743:exzh2":"I'm worried about the exam results.","example:743:exzh3":"Please don't worry.","example:743:exzh4":"Don't worry about small things.","example:743:exzh5":"She's worried about the future.","grammar:743:ex:trans":"I'm worried about his health.","grammar:743:ex:structure":"〜が心配です","grammar:743:ex:explain":"This is a sentence of worry using 「〜が心配です」. The thing you are worried about is marked with 「が」, so 「健康が心配」 = worried about health. 「心配」 is a na-adjective, made polite with 「です」. 「の」 links 「彼」 to 「健康」. The whole sentence means \"I'm worried about his health.\" As with 「好き」, the object of 「心配」 takes 「が」 — a general rule for adjectives of emotion.","grammar:743:ex:words:0:zh":"he","grammar:743:ex:words:0:note":"かれ","grammar:743:ex:words:0:pos":"pronoun","grammar:743:ex:words:1:zh":"'s","grammar:743:ex:words:1:pos":"particle","grammar:743:ex:words:2:zh":"health","grammar:743:ex:words:2:note":"けんこう","grammar:743:ex:words:2:pos":"noun","grammar:743:ex:words:3:zh":"(nominative)","grammar:743:ex:words:3:pos":"particle","grammar:743:ex:words:4:zh":"worry","grammar:743:ex:words:4:note":"しんぱい","grammar:743:ex:words:4:pos":"na-adjective","grammar:743:ex:words:5:zh":"(polite form)","grammar:743:ex:words:5:pos":"copula","grammar:743:ex:points:0":"❗〜が心配: to worry about … (the object takes が).","grammar:743:ex:points:1":"彼の健康: his health.","grammar:743:ex2:trans":"I'm worried about the exam results.","grammar:743:ex2:structure":"〜が心配だ","grammar:743:ex2:words:0:zh":"test","grammar:743:ex2:words:0:note":"しけん","grammar:743:ex2:words:0:pos":"noun","grammar:743:ex2:words:1:zh":"'s","grammar:743:ex2:words:1:pos":"particle","grammar:743:ex2:words:2:zh":"result","grammar:743:ex2:words:2:note":"けっか","grammar:743:ex2:words:2:pos":"noun","grammar:743:ex2:words:3:zh":"(nominative)","grammar:743:ex2:words:3:pos":"particle","grammar:743:ex2:words:4:zh":"worry","grammar:743:ex2:words:4:note":"しんぱい","grammar:743:ex2:words:4:pos":"na-adjective","grammar:743:ex2:words:5:zh":"is","grammar:743:ex2:words:5:pos":"copula","grammar:743:ex2:points:0":"試験の結果: exam results.","grammar:743:ex2:points:1":"心配だ: worried.","grammar:743:ex3:trans":"Please don't worry.","grammar:743:ex3:structure":"〜ないでください","grammar:743:ex3:words:0:zh":"don't worry","grammar:743:ex3:words:0:note":"しんぱいしないで","grammar:743:ex3:words:0:pos":"verb","grammar:743:ex3:words:1:zh":"please","grammar:743:ex3:words:1:pos":"auxiliary verb","grammar:743:ex3:points:0":"心配する: to worry.","grammar:743:ex3:points:1":"「〜ないでください」: please don't …","grammar:743:ex4:trans":"Don't worry about small things.","grammar:743:ex4:structure":"〜を〜するな","grammar:743:ex4:words:0:zh":"small","grammar:743:ex4:words:0:note":"ちいさな","grammar:743:ex4:words:0:pos":"pre-noun adjectival","grammar:743:ex4:words:1:zh":"thing / matter","grammar:743:ex4:words:1:pos":"noun","grammar:743:ex4:words:2:zh":"(object marker)","grammar:743:ex4:words:2:pos":"particle","grammar:743:ex4:words:3:zh":"worry","grammar:743:ex4:words:3:note":"しんぱいする","grammar:743:ex4:words:3:pos":"verb","grammar:743:ex4:words:4:zh":"(prohibition)","grammar:743:ex4:words:4:pos":"particle","grammar:743:ex4:points:0":"❗〜な: don't … (dictionary form of a verb + な, a strong prohibition).","grammar:743:ex4:points:1":"小さなこと: small things, little things.","grammar:743:ex5:trans":"She is worried about things in the future.","grammar:743:ex5:structure":"〜が心配です","grammar:743:ex5:words:0:zh":"she","grammar:743:ex5:words:0:note":"かのじょ","grammar:743:ex5:words:0:pos":"pronoun","grammar:743:ex5:words:1:zh":"(topic)","grammar:743:ex5:words:1:pos":"particle","grammar:743:ex5:words:2:zh":"the future","grammar:743:ex5:words:2:note":"みらい","grammar:743:ex5:words:2:pos":"noun","grammar:743:ex5:words:3:zh":"'s","grammar:743:ex5:words:3:pos":"particle","grammar:743:ex5:words:4:zh":"thing / matter","grammar:743:ex5:words:4:pos":"noun","grammar:743:ex5:words:5:zh":"(nominative)","grammar:743:ex5:words:5:pos":"particle","grammar:743:ex5:words:6:zh":"worry","grammar:743:ex5:words:6:note":"しんぱい","grammar:743:ex5:words:6:pos":"na-adjective","grammar:743:ex5:words:7:zh":"(polite form)","grammar:743:ex5:words:7:pos":"copula","grammar:743:ex5:points:0":"未来のこと: things about the future.","grammar:743:ex5:points:1":"〜が心配: to worry about …."},"744":{"example:744:exzh":"I like taking photos.","example:744:exzh2":"May I take this fruit?","example:744:exzh3":"I like taking photos.","example:744:exzh4":"Could you get me that book?","example:744:exzh5":"He had his money stolen.","grammar:744:ex:trans":"I like taking photos.","grammar:744:ex:structure":"〜を撮るのが好きです","grammar:744:ex:explain":"This sentence requires telling homophones apart. 「写真を撮る」 uses 「撮る」 (take a photo), which is read 「とる」, the same as the card's 「取る」 (take, grab), but the kanji and meaning differ; for photos you must use 「撮る」. 「〜のが好き」 uses 「の」 to nominalize the phrase, and 「を」 marks 「写真」 as the object of 「撮る」. The whole sentence means I like taking photos. Japanese has many homophones written with different kanji, so you have to tell them apart by kanji and context.","grammar:744:ex:words:0:zh":"photo","grammar:744:ex:words:0:note":"しゃしん","grammar:744:ex:words:0:pos":"noun","grammar:744:ex:words:1:zh":"(object marker)","grammar:744:ex:words:1:pos":"particle","grammar:744:ex:words:2:zh":"take (a photo)","grammar:744:ex:words:2:note":"とる","grammar:744:ex:words:2:pos":"verb","grammar:744:ex:words:3:zh":"(nominalizer)","grammar:744:ex:words:3:pos":"particle","grammar:744:ex:words:4:zh":"(object)","grammar:744:ex:words:4:pos":"particle","grammar:744:ex:words:5:zh":"to like","grammar:744:ex:words:5:note":"すき","grammar:744:ex:words:5:pos":"na-adjective","grammar:744:ex:words:6:zh":"(polite form)","grammar:744:ex:words:6:pos":"copula","grammar:744:ex:points:0":"❗写真を撮る: to take a photo (撮る); same sound as 「取る」 but a different kanji.","grammar:744:ex:points:1":"〜のが好き: to like doing…","grammar:744:ex2:trans":"May I take this fruit?","grammar:744:ex2:structure":"〜を取ってもいいですか","grammar:744:ex2:words:0:zh":"this","grammar:744:ex2:words:0:pos":"pre-noun adjectival","grammar:744:ex2:words:1:zh":"fruit","grammar:744:ex2:words:1:note":"くだもの","grammar:744:ex2:words:1:pos":"noun","grammar:744:ex2:words:2:zh":"(object marker)","grammar:744:ex2:words:2:pos":"particle","grammar:744:ex2:words:3:zh":"pick up","grammar:744:ex2:words:3:note":"とって","grammar:744:ex2:words:3:pos":"verb","grammar:744:ex2:words:4:zh":"(also)","grammar:744:ex2:words:4:pos":"particle","grammar:744:ex2:words:5:zh":"good","grammar:744:ex2:words:5:pos":"adjective","grammar:744:ex2:words:6:zh":"(polite form)","grammar:744:ex2:words:6:pos":"copula","grammar:744:ex2:words:7:zh":"(question)","grammar:744:ex2:words:7:pos":"particle","grammar:744:ex2:points:0":"❗〜てもいいですか: may I …? (permission).","grammar:744:ex2:points:1":"果物を取る: take a piece of fruit.","grammar:744:ex3:trans":"I like taking photos.","grammar:744:ex3:structure":"(should be 写真を撮る)","grammar:744:ex3:words:0:zh":"photo","grammar:744:ex3:words:0:note":"しゃしん","grammar:744:ex3:words:0:pos":"noun","grammar:744:ex3:words:1:zh":"(object marker)","grammar:744:ex3:words:1:pos":"particle","grammar:744:ex3:words:2:zh":"(incorrect)","grammar:744:ex3:words:2:note":"とる","grammar:744:ex3:words:2:pos":"verb","grammar:744:ex3:words:3:zh":"(nominalizer)","grammar:744:ex3:words:3:pos":"particle","grammar:744:ex3:words:4:zh":"(object)","grammar:744:ex3:words:4:pos":"particle","grammar:744:ex3:words:5:zh":"to like","grammar:744:ex3:words:5:note":"すき","grammar:744:ex3:words:5:pos":"na-adjective","grammar:744:ex3:words:6:zh":"(polite form)","grammar:744:ex3:words:6:pos":"copula","grammar:744:ex3:points:0":"❗「写真を取る」 is a misspelling: for taking photos you should use 「撮る（とる）」.","grammar:744:ex3:points:1":"取る = take (grab); 撮る = take (a photo).","grammar:744:ex4:trans":"Could you hand me that book?","grammar:744:ex4:structure":"〜を取ってくれませんか","grammar:744:ex4:words:0:zh":"that","grammar:744:ex4:words:0:pos":"pre-noun adjectival","grammar:744:ex4:words:1:zh":"book","grammar:744:ex4:words:1:note":"ほん","grammar:744:ex4:words:1:pos":"noun","grammar:744:ex4:words:2:zh":"(object marker)","grammar:744:ex4:words:2:pos":"particle","grammar:744:ex4:words:3:zh":"pick up","grammar:744:ex4:words:3:note":"とって","grammar:744:ex4:words:3:pos":"verb","grammar:744:ex4:words:4:zh":"Can you ... for me?","grammar:744:ex4:words:4:pos":"auxiliary verb","grammar:744:ex4:points:0":"❗〜てくれませんか: can you ... (for me)? (polite request).","grammar:744:ex4:points:1":"本を取る: take a book.","grammar:744:ex5:trans":"He had his money stolen.","grammar:744:ex5:structure":"〜を取られた","grammar:744:ex5:words:0:zh":"he","grammar:744:ex5:words:0:note":"かれ","grammar:744:ex5:words:0:pos":"pronoun","grammar:744:ex5:words:1:zh":"(topic)","grammar:744:ex5:words:1:pos":"particle","grammar:744:ex5:words:2:zh":"money","grammar:744:ex5:words:2:note":"おかね","grammar:744:ex5:words:2:pos":"noun","grammar:744:ex5:words:3:zh":"(object marker)","grammar:744:ex5:words:3:pos":"particle","grammar:744:ex5:words:4:zh":"was taken away","grammar:744:ex5:words:4:note":"とられた","grammar:744:ex5:words:4:pos":"verb","grammar:744:ex5:points:0":"❗取られた: was taken / was stolen (the passive form of 取る).","grammar:744:ex5:points:1":"お金を取られる: to have money taken or stolen.","exam:744:zh":"May I take this fruit?","exam:744:why":"「果物を取って」 means taking the fruit; the other options can't take fruit as their object."},"745":{"example:745:exzh":"Hey, listen!","example:745:exzh2":"Hey, do you know this?","example:745:exzh3":"Hey, let's go hang out!","example:745:exzh4":"Hey, wait a second!","example:745:exzh5":"Hey, what are you doing?","grammar:745:ex:trans":"Hey, listen!","grammar:745:ex:structure":"ねえ、〜て！","grammar:745:ex:explain":"The core of this sentence is the attention-getting interjection 「ねえ」, used to catch the other person's attention. Its tone is intimate, like hey or listen up in English. The following 「聞いて」 is the te-form of 「聞く」, expressing the request to listen to me (with ください omitted). The whole sentence means \"Hey, listen!\" 「ねえ」 is mostly used between people who are close and is out of place in formal situations. Drawn out as 「ねえ」, it sounds affectionate or cajoling.","grammar:745:ex:words:0:zh":"hey","grammar:745:ex:words:0:pos":"interjection","grammar:745:ex:words:1:zh":"listen","grammar:745:ex:words:1:note":"きいて","grammar:745:ex:words:1:pos":"verb","grammar:745:ex:points:0":"❗ねえ: hey (an attention-getting call, intimate).","grammar:745:ex:points:1":"聞いて: listen (to me).","grammar:745:ex2:trans":"Hey, do you know this one?","grammar:745:ex2:structure":"ねえ、〜知ってる？","grammar:745:ex2:words:0:zh":"hey","grammar:745:ex2:words:0:pos":"interjection","grammar:745:ex2:words:1:zh":"this","grammar:745:ex2:words:1:pos":"pronoun","grammar:745:ex2:words:2:zh":"know","grammar:745:ex2:words:2:note":"しってる","grammar:745:ex2:words:2:pos":"verb","grammar:745:ex2:points:0":"ねえ: hey.","grammar:745:ex2:points:1":"知ってる？: do you know? (casual speech, with い dropped).","grammar:745:ex3:trans":"Hey, let's go out and have some fun!","grammar:745:ex3:structure":"ねえ、〜行こう！","grammar:745:ex3:words:0:zh":"hey","grammar:745:ex3:words:0:pos":"interjection","grammar:745:ex3:words:1:zh":"hang out","grammar:745:ex3:words:1:note":"あそび","grammar:745:ex3:words:1:pos":"noun","grammar:745:ex3:words:2:zh":"(purpose)","grammar:745:ex3:words:2:pos":"particle","grammar:745:ex3:words:3:zh":"let's go","grammar:745:ex3:words:3:note":"いこう","grammar:745:ex3:words:3:pos":"verb","grammar:745:ex3:points:0":"遊びに行こう: let's go and have fun (volitional form).","grammar:745:ex3:points:1":"ねえ: hey.","grammar:745:ex4:trans":"Hey, wait a second!","grammar:745:ex4:structure":"ねえ、ちょっと〜て！","grammar:745:ex4:words:0:zh":"hey","grammar:745:ex4:words:0:pos":"interjection","grammar:745:ex4:words:1:zh":"a quick look","grammar:745:ex4:words:1:pos":"adverb","grammar:745:ex4:words:2:zh":"wait","grammar:745:ex4:words:2:note":"まって","grammar:745:ex4:words:2:pos":"verb","grammar:745:ex4:points:0":"ちょっと待って: wait a second.","grammar:745:ex4:points:1":"ねえ: hey.","grammar:745:ex5:trans":"Hey, what are you doing?","grammar:745:ex5:structure":"ねえ、何してるの？","grammar:745:ex5:words:0:zh":"hey","grammar:745:ex5:words:0:pos":"interjection","grammar:745:ex5:words:1:zh":"what","grammar:745:ex5:words:1:note":"なに","grammar:745:ex5:words:1:pos":"question word","grammar:745:ex5:words:2:zh":"is doing","grammar:745:ex5:words:2:pos":"verb","grammar:745:ex5:words:3:zh":"(question)","grammar:745:ex5:words:3:pos":"particle","grammar:745:ex5:points:0":"何してるの？: what are you doing? (casual speech).","grammar:745:ex5:points:1":"ねえ: hey."},"746":{"example:746:exzh":"I waited for two hours.","example:746:exzh2":"There was a misunderstanding between him and me.","example:746:exzh3":"He's always busy during work.","example:746:exzh4":"The distance between school and home is short.","example:746:exzh5":"There is trust between us.","grammar:746:ex:trans":"I waited for two hours.","grammar:746:ex:structure":"〜の間、〜ていました","grammar:746:ex:explain":"The core of this sentence is 「〜の間」 (during …). 「二時間の間」 = the two-hour period, with 「の」 linking the length of time to 「間」. The following 「待っていました」 is the past progressive, meaning I was waiting the whole time; 「〜ていました」 expresses an action that continued over a stretch of time in the past. The whole sentence means \"I waited for two hours.\" 「間」 refers to a span of time and emphasizes that the action runs through the whole span.","grammar:746:ex:words:0:zh":"I","grammar:746:ex:words:0:note":"わたし","grammar:746:ex:words:0:pos":"pronoun","grammar:746:ex:words:1:zh":"(topic)","grammar:746:ex:words:1:pos":"particle","grammar:746:ex:words:2:zh":"two hours","grammar:746:ex:words:2:note":"にじかん","grammar:746:ex:words:2:pos":"noun","grammar:746:ex:words:3:zh":"'s","grammar:746:ex:words:3:pos":"particle","grammar:746:ex:words:4:zh":"period, duration","grammar:746:ex:words:4:note":"あいだ","grammar:746:ex:words:4:pos":"noun","grammar:746:ex:words:5:zh":"waiting","grammar:746:ex:words:5:note":"まっていました","grammar:746:ex:words:5:pos":"verb","grammar:746:ex:points:0":"❗〜の間: during … (二時間の間 = during the two hours).","grammar:746:ex:points:1":"〜ていました: (past continuous) was …-ing at the time.","grammar:746:ex2:trans":"There was a misunderstanding between him and me.","grammar:746:ex2:structure":"〜との間に〜があった","grammar:746:ex2:words:0:zh":"he","grammar:746:ex2:words:0:note":"かれ","grammar:746:ex2:words:0:pos":"pronoun","grammar:746:ex2:words:1:zh":"with","grammar:746:ex2:words:1:pos":"particle","grammar:746:ex2:words:2:zh":"'s","grammar:746:ex2:words:2:pos":"particle","grammar:746:ex2:words:3:zh":"between","grammar:746:ex2:words:3:note":"あいだ","grammar:746:ex2:words:3:pos":"noun","grammar:746:ex2:words:4:zh":"(location of existence)","grammar:746:ex2:words:4:pos":"particle","grammar:746:ex2:words:5:zh":"misunderstanding","grammar:746:ex2:words:5:note":"ごかい","grammar:746:ex2:words:5:pos":"noun","grammar:746:ex2:words:6:zh":"(nominative)","grammar:746:ex2:words:6:pos":"particle","grammar:746:ex2:words:7:zh":"had (past)","grammar:746:ex2:words:7:pos":"verb","grammar:746:ex2:points:0":"❗〜との間に: between … (in relationships).","grammar:746:ex2:points:1":"誤解がある: there is a misunderstanding.","grammar:746:ex3:trans":"He's always busy during work.","grammar:746:ex3:structure":"〜の間、〜","grammar:746:ex3:words:0:zh":"work","grammar:746:ex3:words:0:note":"しごと","grammar:746:ex3:words:0:pos":"noun","grammar:746:ex3:words:1:zh":"'s","grammar:746:ex3:words:1:pos":"particle","grammar:746:ex3:words:2:zh":"period, duration","grammar:746:ex3:words:2:note":"あいだ","grammar:746:ex3:words:2:pos":"noun","grammar:746:ex3:words:3:zh":"he","grammar:746:ex3:words:3:note":"かれ","grammar:746:ex3:words:3:pos":"pronoun","grammar:746:ex3:words:4:zh":"(topic)","grammar:746:ex3:words:4:pos":"particle","grammar:746:ex3:words:5:zh":"always","grammar:746:ex3:words:5:pos":"adverb","grammar:746:ex3:words:6:zh":"busy","grammar:746:ex3:words:6:note":"いそがしい","grammar:746:ex3:words:6:pos":"adjective","grammar:746:ex3:points:0":"仕事の間: during work.","grammar:746:ex3:points:1":"いつも忙しい: always busy.","grammar:746:ex4:trans":"The distance between school and home is short.","grammar:746:ex4:structure":"AとBの間の距離は短いです","grammar:746:ex4:explain":"「学校と家」 uses 「と」 to join two places, and the first 「の」 links those two places to 「間」, forming the space between school and home. The second 「の」 then links that to 「距離」, expressing the distance between those two places. The whole long noun phrase is presented as the topic by 「は」. 「短いです」 says the distance is short, and 「です」 only adds politeness.","grammar:746:ex4:words:0:zh":"school","grammar:746:ex4:words:0:note":"がっこう","grammar:746:ex4:words:0:pos":"noun","grammar:746:ex4:words:1:zh":"and (listing)","grammar:746:ex4:words:1:pos":"particle","grammar:746:ex4:words:2:zh":"house","grammar:746:ex4:words:2:note":"いえ","grammar:746:ex4:words:2:pos":"noun","grammar:746:ex4:words:3:zh":"(links the two places to 間)","grammar:746:ex4:words:3:pos":"particle","grammar:746:ex4:words:4:zh":"between","grammar:746:ex4:words:4:note":"あいだ","grammar:746:ex4:words:4:pos":"noun","grammar:746:ex4:words:5:zh":"(links the range to a noun)","grammar:746:ex4:words:5:pos":"particle","grammar:746:ex4:words:6:zh":"distance","grammar:746:ex4:words:6:note":"きょり","grammar:746:ex4:words:6:pos":"noun","grammar:746:ex4:words:7:zh":"(topic)","grammar:746:ex4:words:7:pos":"particle","grammar:746:ex4:words:8:zh":"short","grammar:746:ex4:words:8:note":"みじかい","grammar:746:ex4:words:8:pos":"i-adjective","grammar:746:ex4:words:9:zh":"(polite ending)","grammar:746:ex4:words:9:pos":"auxiliary verb","grammar:746:ex4:points:0":"「AとBの間」 means the space between A and B, and 「間」 is read 「あいだ」.","grammar:746:ex4:points:1":"「距離が短い」 means the distance is short; to describe two nearby places you can also use 「近い」.","grammar:746:ex4:points:2":"An i-adjective followed by 「です」 forms a polite affirmative sentence; don't add 「だ」.","grammar:746:ex5:trans":"There is trust between us.","grammar:746:ex5:structure":"〜の間には〜があります","grammar:746:ex5:words:0:zh":"we","grammar:746:ex5:words:0:note":"わたしたち","grammar:746:ex5:words:0:pos":"pronoun","grammar:746:ex5:words:1:zh":"'s","grammar:746:ex5:words:1:pos":"particle","grammar:746:ex5:words:2:zh":"between","grammar:746:ex5:words:2:note":"あいだ","grammar:746:ex5:words:2:pos":"noun","grammar:746:ex5:words:3:zh":"(location of existence)","grammar:746:ex5:words:3:pos":"particle","grammar:746:ex5:words:4:zh":"(contrast)","grammar:746:ex5:words:4:pos":"particle","grammar:746:ex5:words:5:zh":"trust","grammar:746:ex5:words:5:note":"しんらい","grammar:746:ex5:words:5:pos":"noun","grammar:746:ex5:words:6:zh":"(nominative)","grammar:746:ex5:words:6:pos":"particle","grammar:746:ex5:words:7:zh":"there is / are","grammar:746:ex5:words:7:pos":"verb","grammar:746:ex5:points:0":"私たちの間: between us.","grammar:746:ex5:points:1":"信頼がある: there is trust."},"747":{"example:747:exzh":"Class is over.","example:747:exzh2":"Let's go hang out once work is done.","example:747:exzh3":"The movie is already over.","example:747:exzh4":"I'll go home around the time the party ends.","example:747:exzh5":"The exam ended and I felt relieved.","grammar:747:ex:trans":"Class is over.","grammar:747:ex:structure":"〜が終わりました","grammar:747:ex:explain":"This sentence uses the intransitive 「終わる」 (to end), with the subject marked by 「が」. 「授業が終わりました」 = the class ended; 「終わる」 means something ends on its own, with no doer, so it is an intransitive verb that takes 「が」. The whole sentence means the class ended. Its transitive counterpart is 「終える／終わらせる」 (to finish something). Understand transitive/intransitive pairs as sets (授業を終える / 授業が終わる).","grammar:747:ex:words:0:zh":"class","grammar:747:ex:words:0:note":"じゅぎょう","grammar:747:ex:words:0:pos":"noun","grammar:747:ex:words:1:zh":"(nominative)","grammar:747:ex:words:1:pos":"particle","grammar:747:ex:words:2:zh":"finished","grammar:747:ex:words:2:note":"おわりました","grammar:747:ex:words:2:pos":"verb","grammar:747:ex:points:0":"❗終わる (intransitive verb, to end); the subject takes が.","grammar:747:ex:points:1":"授業が終わる: class ends (class is dismissed).","grammar:747:ex2:trans":"Let's go hang out after work is over.","grammar:747:ex2:structure":"〜が終わったら〜行こう","grammar:747:ex2:words:0:zh":"work","grammar:747:ex2:words:0:note":"しごと","grammar:747:ex2:words:0:pos":"noun","grammar:747:ex2:words:1:zh":"(nominative)","grammar:747:ex2:words:1:pos":"particle","grammar:747:ex2:words:2:zh":"when it's over","grammar:747:ex2:words:2:note":"おわったら","grammar:747:ex2:words:2:pos":"verb","grammar:747:ex2:words:3:zh":"hang out","grammar:747:ex2:words:3:note":"あそび","grammar:747:ex2:words:3:pos":"noun","grammar:747:ex2:words:4:zh":"(purpose)","grammar:747:ex2:words:4:pos":"particle","grammar:747:ex2:words:5:zh":"let's go","grammar:747:ex2:words:5:note":"いこう","grammar:747:ex2:words:5:pos":"verb","grammar:747:ex2:points:0":"❗〜たら: after … (then).","grammar:747:ex2:points:1":"遊びに行く: to go out and have fun.","grammar:747:ex3:trans":"The movie is already over.","grammar:747:ex3:structure":"もう終わった","grammar:747:ex3:words:0:zh":"movie","grammar:747:ex3:words:0:note":"えいが","grammar:747:ex3:words:0:pos":"noun","grammar:747:ex3:words:1:zh":"(topic)","grammar:747:ex3:words:1:pos":"particle","grammar:747:ex3:words:2:zh":"already","grammar:747:ex3:words:2:pos":"adverb","grammar:747:ex3:words:3:zh":"finished","grammar:747:ex3:words:3:note":"おわった","grammar:747:ex3:words:3:pos":"verb","grammar:747:ex3:points:0":"❗もう終わった: it's already over.","grammar:747:ex3:points:1":"映画が終わる: the movie ends.","grammar:747:ex4:trans":"When the party ends, I'll go home.","grammar:747:ex4:structure":"〜が終わる頃、〜ます","grammar:747:ex4:words:0:zh":"party","grammar:747:ex4:words:0:note":"loanword","grammar:747:ex4:words:0:pos":"noun","grammar:747:ex4:words:1:zh":"(nominative)","grammar:747:ex4:words:1:pos":"particle","grammar:747:ex4:words:2:zh":"ends","grammar:747:ex4:words:2:note":"おわる","grammar:747:ex4:words:2:pos":"verb","grammar:747:ex4:words:3:zh":"time","grammar:747:ex4:words:3:note":"ころ","grammar:747:ex4:words:3:pos":"noun","grammar:747:ex4:words:4:zh":"coming home","grammar:747:ex4:words:4:note":"かえります","grammar:747:ex4:words:4:pos":"verb","grammar:747:ex4:points:0":"❗〜頃: around the time of … (approximate point in time).","grammar:747:ex4:points:1":"終わる頃: about when it's ending (just before the end).","grammar:747:ex5:trans":"The exam was over, and I felt relieved.","grammar:747:ex5:structure":"〜が終わって、〜した","grammar:747:ex5:words:0:zh":"test","grammar:747:ex5:words:0:note":"しけん","grammar:747:ex5:words:0:pos":"noun","grammar:747:ex5:words:1:zh":"(nominative)","grammar:747:ex5:words:1:pos":"particle","grammar:747:ex5:words:2:zh":"ends","grammar:747:ex5:words:2:note":"おわって","grammar:747:ex5:words:2:pos":"verb","grammar:747:ex5:words:3:zh":"felt relieved","grammar:747:ex5:words:3:note":"あんしんした","grammar:747:ex5:words:3:pos":"verb","grammar:747:ex5:points:0":"❗〜て、〜: … (and then) … (te-form linking / cause and effect).","grammar:747:ex5:points:1":"安心する: to feel relieved.","exam:747:zh":"This class starts at ten and ends at eleven.","exam:747:why":"「終わる」 means to end, which matches the starting time given earlier. 「始まる」 would mean the same class starts again at eleven, which doesn't fit the schedule here."},"748":{"example:748:exzh":"This movie is about murder.","example:748:exzh2":"Murder is a crime.","example:748:exzh3":"The police are investigating a murder case.","example:748:exzh4":"He was arrested as a murderer.","example:748:exzh5":"This book is a murder mystery."},"749":{"example:749:exzh":"I'm looking into the problem.","example:749:exzh2":"Please check the data.","example:749:exzh3":"He investigated that case.","example:749:exzh4":"I'm looking up new information.","example:749:exzh5":"I plan to look into it.","grammar:749:ex:trans":"I'm looking into the problem.","grammar:749:ex:structure":"〜を調べています","grammar:749:ex:explain":"This sentence uses 「〜を調べている」 to show an action in progress. 「調べる」 (to investigate, to look up) is a transitive verb, its object 「問題」 is marked with 「を」, and the progressive form 「調べています」 shows that the looking into is happening now. The whole sentence means “I'm looking into the problem.” 「調べる」 has a wide range of uses — you can check data, investigate a case, or look a word up in a dictionary — so it's a very handy verb. Here 「〜ている」 expresses an action in progress.","grammar:749:ex:words:0:zh":"problem","grammar:749:ex:words:0:note":"もんだい","grammar:749:ex:words:0:pos":"noun","grammar:749:ex:words:1:zh":"(object marker)","grammar:749:ex:words:1:pos":"particle","grammar:749:ex:words:2:zh":"is investigating","grammar:749:ex:words:2:note":"しらべています","grammar:749:ex:words:2:pos":"verb","grammar:749:ex:points:0":"❗調べる（しらべる）: to investigate, to look up (transitive verb).","grammar:749:ex:points:1":"問題を調べる: to look into a problem.","grammar:749:ex2:trans":"Please check the data.","grammar:749:ex2:structure":"〜を調べてください","grammar:749:ex2:words:0:zh":"data","grammar:749:ex2:words:0:note":"loanword","grammar:749:ex2:words:0:pos":"noun","grammar:749:ex2:words:1:zh":"(object marker)","grammar:749:ex2:words:1:pos":"particle","grammar:749:ex2:words:2:zh":"Look up","grammar:749:ex2:words:2:note":"しらべて","grammar:749:ex2:words:2:pos":"verb","grammar:749:ex2:words:3:zh":"please","grammar:749:ex2:words:3:pos":"auxiliary verb","grammar:749:ex2:points:0":"データを調べる: to check the data.","grammar:749:ex2:points:1":"調べる→調べて＋ください。","grammar:749:ex3:trans":"He investigated that case.","grammar:749:ex3:structure":"〜を調べました","grammar:749:ex3:words:0:zh":"he","grammar:749:ex3:words:0:note":"かれ","grammar:749:ex3:words:0:pos":"pronoun","grammar:749:ex3:words:1:zh":"(topic)","grammar:749:ex3:words:1:pos":"particle","grammar:749:ex3:words:2:zh":"that","grammar:749:ex3:words:2:pos":"pre-noun adjectival","grammar:749:ex3:words:3:zh":"incident","grammar:749:ex3:words:3:note":"じけん","grammar:749:ex3:words:3:pos":"noun","grammar:749:ex3:words:4:zh":"(object marker)","grammar:749:ex3:words:4:pos":"particle","grammar:749:ex3:words:5:zh":"investigated","grammar:749:ex3:words:5:note":"しらべました","grammar:749:ex3:words:5:pos":"verb","grammar:749:ex3:points:0":"事件を調べる: to investigate a case.","grammar:749:ex3:points:1":"調べる→調べました。","grammar:749:ex4:trans":"I'm looking up new information.","grammar:749:ex4:structure":"〜を調べています","grammar:749:ex4:words:0:zh":"new","grammar:749:ex4:words:0:note":"あたらしい","grammar:749:ex4:words:0:pos":"adjective","grammar:749:ex4:words:1:zh":"information","grammar:749:ex4:words:1:note":"じょうほう","grammar:749:ex4:words:1:pos":"noun","grammar:749:ex4:words:2:zh":"(object marker)","grammar:749:ex4:words:2:pos":"particle","grammar:749:ex4:words:3:zh":"looking up (in progress)","grammar:749:ex4:words:3:note":"しらべています","grammar:749:ex4:words:3:pos":"verb","grammar:749:ex4:points:0":"情報を調べる: to look up information.","grammar:749:ex4:points:1":"〜ている: ongoing action.","grammar:749:ex5:trans":"I plan to look into it.","grammar:749:ex5:structure":"verb dictionary form＋予定です","grammar:749:ex5:explain":"「調べる」 means to investigate, look up, or search for information; the exact sense depends on the context. In dictionary form it directly modifies the noun 「予定」 and spells out what the plan is. 「です」 makes the sentence polite. This sentence omits both the subject and the thing being looked into; following the given translation, it means the speaker plans to carry out an investigation. It does not yet say that the investigation has started.","grammar:749:ex5:words:0:zh":"to investigate, to look up","grammar:749:ex5:words:0:note":"しらべる","grammar:749:ex5:words:0:pos":"verb","grammar:749:ex5:words:1:zh":"plan, schedule","grammar:749:ex5:words:1:note":"よてい","grammar:749:ex5:words:1:pos":"noun","grammar:749:ex5:words:2:zh":"(polite sentence-final ending)","grammar:749:ex5:words:2:pos":"auxiliary verb","grammar:749:ex5:points:0":"「verb dictionary form＋予定です」 expresses that something is planned or scheduled.","grammar:749:ex5:points:1":"A verb can modify 「予定」 directly, with no 「の」 in between."},"750":{"example:750:exzh":"You only live once.","example:750:exzh2":"He's living a wonderful life.","example:750:exzh3":"It's important to think about the purpose of life.","example:750:exzh4":"Life has all kinds of experiences.","example:750:exzh5":"We should enjoy life."},"751":{"example:751:exzh":"This place is dangerous.","example:751:exzh2":"Please be careful so you can avoid danger.","example:751:exzh3":"You should avoid dangerous activities.","example:751:exzh4":"He felt danger.","example:751:exzh5":"That action could be dangerous.","grammar:751:ex:trans":"This place is dangerous.","grammar:751:ex:structure":"〜は危険です","grammar:751:ex:explain":"This sentence uses the na-adjective 「危険」 (dangerous) as the predicate. In 「この場所は危険です」, 「は」 marks the topic, and 「危険」 plus 「です」 forms the predicate. The whole sentence means \"This place is dangerous.\" 「危険」 is read 「きけん」, and it takes 「な」 before a noun (危険な場所). This is a very basic na-adjective predicate sentence, the same shape as 「静かです」 and 「便利です」.","grammar:751:ex:words:0:zh":"this","grammar:751:ex:words:0:pos":"pre-noun adjectival","grammar:751:ex:words:1:zh":"place","grammar:751:ex:words:1:note":"ばしょ","grammar:751:ex:words:1:pos":"noun","grammar:751:ex:words:2:zh":"(topic)","grammar:751:ex:words:2:pos":"particle","grammar:751:ex:words:3:zh":"dangerous","grammar:751:ex:words:3:note":"きけん","grammar:751:ex:words:3:pos":"na-adjective","grammar:751:ex:words:4:zh":"(polite form)","grammar:751:ex:words:4:pos":"copula","grammar:751:ex:points:0":"危険（きけん）: dangerous (na-adjective).","grammar:751:ex:points:1":"この場所: this place.","grammar:751:ex2:trans":"Please be careful so you can avoid danger.","grammar:751:ex2:structure":"〜ために〜てください","grammar:751:ex2:words:0:zh":"dangerous","grammar:751:ex2:words:0:note":"きけん","grammar:751:ex2:words:0:pos":"noun","grammar:751:ex2:words:1:zh":"(object marker)","grammar:751:ex2:words:1:pos":"particle","grammar:751:ex2:words:2:zh":"avoid","grammar:751:ex2:words:2:note":"さける","grammar:751:ex2:words:2:pos":"verb","grammar:751:ex2:words:3:zh":"for the sake of","grammar:751:ex2:words:3:pos":"particle","grammar:751:ex2:words:4:zh":"be careful","grammar:751:ex2:words:4:note":"ちゅういして","grammar:751:ex2:words:4:pos":"verb","grammar:751:ex2:words:5:zh":"please","grammar:751:ex2:words:5:pos":"auxiliary verb","grammar:751:ex2:points:0":"危険を避ける: to avoid danger.","grammar:751:ex2:points:1":"〜ために: in order to….","grammar:751:ex3:trans":"You should avoid dangerous activities.","grammar:751:ex3:structure":"〜べきです","grammar:751:ex3:words:0:zh":"dangerous","grammar:751:ex3:words:0:note":"きけん","grammar:751:ex3:words:0:pos":"na-adjective","grammar:751:ex3:words:1:zh":"(attributive form)","grammar:751:ex3:words:1:pos":"auxiliary verb","grammar:751:ex3:words:2:zh":"event","grammar:751:ex3:words:2:note":"かつどう","grammar:751:ex3:words:2:pos":"noun","grammar:751:ex3:words:3:zh":"(topic)","grammar:751:ex3:words:3:pos":"particle","grammar:751:ex3:words:4:zh":"avoid","grammar:751:ex3:words:4:note":"さける","grammar:751:ex3:words:4:pos":"verb","grammar:751:ex3:words:5:zh":"should","grammar:751:ex3:words:5:pos":"auxiliary verb","grammar:751:ex3:words:6:zh":"(polite form)","grammar:751:ex3:words:6:pos":"copula","grammar:751:ex3:points:0":"危険な活動: dangerous activities (な + noun).","grammar:751:ex3:points:1":"〜べきです: should ….","grammar:751:ex4:trans":"He felt danger.","grammar:751:ex4:structure":"〜を感じていました","grammar:751:ex4:words:0:zh":"he","grammar:751:ex4:words:0:note":"かれ","grammar:751:ex4:words:0:pos":"pronoun","grammar:751:ex4:words:1:zh":"(topic)","grammar:751:ex4:words:1:pos":"particle","grammar:751:ex4:words:2:zh":"dangerous","grammar:751:ex4:words:2:note":"きけん","grammar:751:ex4:words:2:pos":"noun","grammar:751:ex4:words:3:zh":"(object marker)","grammar:751:ex4:words:3:pos":"particle","grammar:751:ex4:words:4:zh":"is feeling","grammar:751:ex4:words:4:note":"かんじていました","grammar:751:ex4:words:4:pos":"verb","grammar:751:ex4:points:0":"危険を感じる: to feel danger.","grammar:751:ex4:points:1":"〜ていました: (at the time) kept feeling ….","grammar:751:ex5:trans":"That behavior could be dangerous.","grammar:751:ex5:structure":"〜である可能性があります","grammar:751:ex5:words:0:zh":"that","grammar:751:ex5:words:0:pos":"pre-noun adjectival","grammar:751:ex5:words:1:zh":"actions","grammar:751:ex5:words:1:note":"こうどう","grammar:751:ex5:words:1:pos":"noun","grammar:751:ex5:words:2:zh":"(topic)","grammar:751:ex5:words:2:pos":"particle","grammar:751:ex5:words:3:zh":"dangerous","grammar:751:ex5:words:3:note":"きけん","grammar:751:ex5:words:3:pos":"na-adjective","grammar:751:ex5:words:4:zh":"is","grammar:751:ex5:words:4:pos":"copula","grammar:751:ex5:words:5:zh":"possibility","grammar:751:ex5:words:5:note":"かのうせい","grammar:751:ex5:words:5:pos":"noun","grammar:751:ex5:words:6:zh":"(nominative)","grammar:751:ex5:words:6:pos":"particle","grammar:751:ex5:words:7:zh":"there is / are","grammar:751:ex5:words:7:pos":"verb","grammar:751:ex5:points:0":"❗〜である: to be … (the written / attributive form of だ).","grammar:751:ex5:points:1":"〜可能性があります: there's a possibility that …"},"752":{"example:752:exzh":"It's important to keep studying.","example:752:exzh2":"She's continuing her work.","example:752:exzh3":"Continuing to exercise is good for your health.","example:752:exzh4":"Please continue this story.","example:752:exzh5":"He intends to continue the project.","grammar:752:ex:trans":"It's important to keep studying.","grammar:752:ex:structure":"〜ことが大切です","grammar:752:ex:explain":"This sentence asks you to keep the transitive verb 「続ける」 and the intransitive verb 「続く」 apart: 「続ける」 means someone actively keeps something going (there is a doer, and it takes を), while 「続く」 means the thing continues on its own. Here 「勉強を続ける」 marks the object with 「を」 and means “to keep studying.” It is followed by 「〜ことが大切です」, which says that this is important. The whole sentence means “It's important to keep studying.” Learn transitive–intransitive pairs as a set.","grammar:752:ex:words:0:zh":"study","grammar:752:ex:words:0:note":"べんきょう","grammar:752:ex:words:0:pos":"noun","grammar:752:ex:words:1:zh":"(object marker)","grammar:752:ex:words:1:pos":"particle","grammar:752:ex:words:2:zh":"continue","grammar:752:ex:words:2:note":"つづける","grammar:752:ex:words:2:pos":"verb","grammar:752:ex:words:3:zh":"(nominalizer)","grammar:752:ex:words:3:pos":"noun","grammar:752:ex:words:4:zh":"(nominative)","grammar:752:ex:words:4:pos":"particle","grammar:752:ex:words:5:zh":"important","grammar:752:ex:words:5:note":"たいせつ","grammar:752:ex:words:5:pos":"na-adjective","grammar:752:ex:words:6:zh":"(polite form)","grammar:752:ex:words:6:pos":"copula","grammar:752:ex:points:0":"❗続ける (transitive verb, to continue …); vs 続く (intransitive verb).","grammar:752:ex:points:1":"勉強を続ける: to keep studying.","grammar:752:ex2:trans":"She is continuing her job.","grammar:752:ex2:structure":"〜を続けています","grammar:752:ex2:words:0:zh":"she","grammar:752:ex2:words:0:note":"かのじょ","grammar:752:ex2:words:0:pos":"pronoun","grammar:752:ex2:words:1:zh":"(topic)","grammar:752:ex2:words:1:pos":"particle","grammar:752:ex2:words:2:zh":"work","grammar:752:ex2:words:2:note":"しごと","grammar:752:ex2:words:2:pos":"noun","grammar:752:ex2:words:3:zh":"(object marker)","grammar:752:ex2:words:3:pos":"particle","grammar:752:ex2:words:4:zh":"continues","grammar:752:ex2:words:4:note":"つづけています","grammar:752:ex2:words:4:pos":"verb","grammar:752:ex2:points:0":"仕事を続ける: to continue working.","grammar:752:ex2:points:1":"〜ている: (ongoing) progress.","grammar:752:ex3:trans":"Keeping up exercise is good for your health.","grammar:752:ex3:structure":"〜ことが〜に良い","grammar:752:ex3:words:0:zh":"exercise","grammar:752:ex3:words:0:note":"うんどう","grammar:752:ex3:words:0:pos":"noun","grammar:752:ex3:words:1:zh":"(object marker)","grammar:752:ex3:words:1:pos":"particle","grammar:752:ex3:words:2:zh":"continue","grammar:752:ex3:words:2:note":"つづける","grammar:752:ex3:words:2:pos":"verb","grammar:752:ex3:words:3:zh":"(nominalizer)","grammar:752:ex3:words:3:pos":"noun","grammar:752:ex3:words:4:zh":"(nominative)","grammar:752:ex3:words:4:pos":"particle","grammar:752:ex3:words:5:zh":"health","grammar:752:ex3:words:5:note":"けんこう","grammar:752:ex3:words:5:pos":"noun","grammar:752:ex3:words:6:zh":"(object)","grammar:752:ex3:words:6:pos":"particle","grammar:752:ex3:words:7:zh":"good","grammar:752:ex3:words:7:note":"いい","grammar:752:ex3:words:7:pos":"adjective","grammar:752:ex3:points:0":"❗〜に良い: good for …","grammar:752:ex3:points:1":"運動を続ける: to keep exercising.","grammar:752:ex4:trans":"Please go on with the story.","grammar:752:ex4:structure":"〜を続けてください","grammar:752:ex4:words:0:zh":"this","grammar:752:ex4:words:0:pos":"pre-noun adjectival","grammar:752:ex4:words:1:zh":"story","grammar:752:ex4:words:1:note":"はなし","grammar:752:ex4:words:1:pos":"noun","grammar:752:ex4:words:2:zh":"(object marker)","grammar:752:ex4:words:2:pos":"particle","grammar:752:ex4:words:3:zh":"continue","grammar:752:ex4:words:3:note":"つづけて","grammar:752:ex4:words:3:pos":"verb","grammar:752:ex4:words:4:zh":"please","grammar:752:ex4:words:4:pos":"auxiliary verb","grammar:752:ex4:points:0":"話を続ける: to keep talking (continue the story).","grammar:752:ex4:points:1":"続ける→続けて＋ください。","grammar:752:ex5:trans":"He intends to continue the project.","grammar:752:ex5:structure":"〜を続けるつもりです","grammar:752:ex5:words:0:zh":"he","grammar:752:ex5:words:0:note":"かれ","grammar:752:ex5:words:0:pos":"pronoun","grammar:752:ex5:words:1:zh":"(topic)","grammar:752:ex5:words:1:pos":"particle","grammar:752:ex5:words:2:zh":"project","grammar:752:ex5:words:2:note":"loanword","grammar:752:ex5:words:2:pos":"noun","grammar:752:ex5:words:3:zh":"(object marker)","grammar:752:ex5:words:3:pos":"particle","grammar:752:ex5:words:4:zh":"continue","grammar:752:ex5:words:4:note":"つづける","grammar:752:ex5:words:4:pos":"verb","grammar:752:ex5:words:5:zh":"intend to","grammar:752:ex5:words:5:pos":"noun","grammar:752:ex5:words:6:zh":"(polite form)","grammar:752:ex5:words:6:pos":"copula","grammar:752:ex5:points:0":"❗〜つもりです: intend to …","grammar:752:ex5:points:1":"プロジェクトを続ける: to continue the project."},"753":{"example:753:exzh":"Learning a new language is difficult.","example:753:exzh2":"He remembered the name right away.","example:753:exzh3":"I try to memorize a little each day.","example:753:exzh4":"Have you memorized this song?","example:753:exzh5":"I write new words in a notebook to memorize them.","grammar:753:ex:trans":"Learning a new language is hard.","grammar:753:ex:structure":"〜のは難しいです","grammar:753:ex:explain":"This sentence uses 「〜のは難しい」 to rate how difficult something is: the verb 「覚える」 (to memorize, to learn) takes 「の」 to become a noun phrase and serves as the topic. Watch out — 「覚える」 means to memorize, to get something into your head, which looks similar to 「教える」 (to teach) but means something different. The whole sentence means “Learning a new language is hard.” 「覚える」 is read 「おぼえる」 and is a very common verb for memorizing vocabulary and remembering things.","grammar:753:ex:words:0:zh":"new","grammar:753:ex:words:0:note":"あたらしい","grammar:753:ex:words:0:pos":"adjective","grammar:753:ex:words:1:zh":"languages","grammar:753:ex:words:1:note":"げんご","grammar:753:ex:words:1:pos":"noun","grammar:753:ex:words:2:zh":"(object marker)","grammar:753:ex:words:2:pos":"particle","grammar:753:ex:words:3:zh":"to memorize","grammar:753:ex:words:3:note":"おぼえる","grammar:753:ex:words:3:pos":"verb","grammar:753:ex:words:4:zh":"(nominalizer)","grammar:753:ex:words:4:pos":"particle","grammar:753:ex:words:5:zh":"(topic)","grammar:753:ex:words:5:pos":"particle","grammar:753:ex:words:6:zh":"difficult","grammar:753:ex:words:6:note":"むずかしい","grammar:753:ex:words:6:pos":"adjective","grammar:753:ex:words:7:zh":"(polite form)","grammar:753:ex:words:7:pos":"copula","grammar:753:ex:points:0":"❗覚える（おぼえる）: to memorize, to learn.","grammar:753:ex:points:1":"〜のは難しい: it is hard to…","grammar:753:ex2:trans":"He remembered the name right away.","grammar:753:ex2:structure":"〜をすぐに覚えました","grammar:753:ex2:words:0:zh":"he","grammar:753:ex2:words:0:note":"かれ","grammar:753:ex2:words:0:pos":"pronoun","grammar:753:ex2:words:1:zh":"(topic)","grammar:753:ex2:words:1:pos":"particle","grammar:753:ex2:words:2:zh":"name","grammar:753:ex2:words:2:note":"なまえ","grammar:753:ex2:words:2:pos":"noun","grammar:753:ex2:words:3:zh":"(object marker)","grammar:753:ex2:words:3:pos":"particle","grammar:753:ex2:words:4:zh":"right away","grammar:753:ex2:words:4:pos":"adverb","grammar:753:ex2:words:5:zh":"Memorized","grammar:753:ex2:words:5:note":"おぼえました","grammar:753:ex2:words:5:pos":"verb","grammar:753:ex2:points:0":"名前を覚える: to remember a name.","grammar:753:ex2:points:1":"すぐに覚える: to memorize quickly.","grammar:753:ex3:trans":"I try to memorize a little bit every day.","grammar:753:ex3:structure":"verb dictionary form＋ようにしています","grammar:753:ex3:words:0:zh":"every day","grammar:753:ex3:words:0:note":"まいにち","grammar:753:ex3:words:0:pos":"noun","grammar:753:ex3:words:1:zh":"just a little bit","grammar:753:ex3:words:1:note":"すこし","grammar:753:ex3:words:1:pos":"adverb","grammar:753:ex3:words:2:zh":"(each time) each","grammar:753:ex3:words:2:pos":"particle","grammar:753:ex3:words:3:zh":"to memorize","grammar:753:ex3:words:3:note":"おぼえる","grammar:753:ex3:words:3:pos":"verb","grammar:753:ex3:words:4:zh":"(the direction of the effort)","grammar:753:ex3:words:4:pos":"formal noun","grammar:753:ex3:words:5:zh":"(goal)","grammar:753:ex3:words:5:pos":"particle","grammar:753:ex3:words:6:zh":"do","grammar:753:ex3:words:6:note":"the te-form of する","grammar:753:ex3:words:6:pos":"verb","grammar:753:ex3:words:7:zh":"(ongoing)","grammar:753:ex3:words:7:pos":"auxiliary verb","grammar:753:ex3:points:0":"「覚えるようにしています」 = making an effort to memorize: 「verb dictionary form＋ようにしている」 expresses ongoing effort to build a habit.","grammar:753:ex3:points:1":"「少しずつ」 = little by little; 「ずつ」 comes after a quantity word and shows the amount distributed each time.","grammar:753:ex4:trans":"Did you memorize this song?","grammar:753:ex4:structure":"〜を覚えましたか","grammar:753:ex4:words:0:zh":"this","grammar:753:ex4:words:0:pos":"pre-noun adjectival","grammar:753:ex4:words:1:zh":"song","grammar:753:ex4:words:1:note":"うた","grammar:753:ex4:words:1:pos":"noun","grammar:753:ex4:words:2:zh":"(object marker)","grammar:753:ex4:words:2:pos":"particle","grammar:753:ex4:words:3:zh":"Memorized","grammar:753:ex4:words:3:note":"おぼえました","grammar:753:ex4:words:3:pos":"verb","grammar:753:ex4:words:4:zh":"(question)","grammar:753:ex4:words:4:pos":"particle","grammar:753:ex4:points:0":"歌を覚える: to learn a song by heart.","grammar:753:ex4:points:1":"覚えましたか: did you memorize it?","grammar:753:ex5:trans":"I write new words in my notebook to memorize them.","grammar:753:ex5:structure":"〜に書いて覚えます","grammar:753:ex5:words:0:zh":"new","grammar:753:ex5:words:0:note":"あたらしい","grammar:753:ex5:words:0:pos":"adjective","grammar:753:ex5:words:1:zh":"vocabulary word","grammar:753:ex5:words:1:note":"たんご","grammar:753:ex5:words:1:pos":"noun","grammar:753:ex5:words:2:zh":"(topic)","grammar:753:ex5:words:2:pos":"particle","grammar:753:ex5:words:3:zh":"notebook","grammar:753:ex5:words:3:pos":"noun","grammar:753:ex5:words:4:zh":"(place: written on / in …)","grammar:753:ex5:words:4:pos":"particle","grammar:753:ex5:words:5:zh":"write","grammar:753:ex5:words:5:note":"かいて；the te-form of 書く","grammar:753:ex5:words:5:pos":"verb","grammar:753:ex5:words:6:zh":"to memorize","grammar:753:ex5:words:6:note":"おぼえます；the masu-form of 覚える","grammar:753:ex5:words:6:pos":"verb","grammar:753:ex5:points:0":"「書いて覚えます」 = write it down to remember it: 「覚える」 means getting knowledge into your head, and the preceding 「書いて」 in te-form shows how you memorize it.","grammar:753:ex5:points:1":"「ノートに書く」: when you write something somewhere, the place is marked with 「に」."},"754":{"example:754:exzh":"She's a very kind woman.","example:754:exzh2":"Many women work.","example:754:exzh3":"Women's rights are important.","example:754:exzh4":"Awareness of women is increasing.","example:754:exzh5":"Women's sports are popular too.","grammar:754:ex:trans":"She is a very kind woman.","grammar:754:ex:structure":"〜はとても〜女性です","grammar:754:ex:explain":"This sentence uses a modifying phrase to describe a person. In 「優しい女性」, the i-adjective 「優しい」 (kind, gentle) modifies the noun 「女性」 directly, giving a kind woman. 「とても」 modifies the degree. 「は」 marks the topic 「彼女」. The whole sentence means \"She is a very kind woman.\" An i-adjective needs no linking particle before a noun — just put it in front — unlike a na-adjective, which needs 「な」.","grammar:754:ex:words:0:zh":"she","grammar:754:ex:words:0:note":"かのじょ","grammar:754:ex:words:0:pos":"pronoun","grammar:754:ex:words:1:zh":"(topic)","grammar:754:ex:words:1:pos":"particle","grammar:754:ex:words:2:zh":"extremely","grammar:754:ex:words:2:pos":"adverb","grammar:754:ex:words:3:zh":"kind-hearted","grammar:754:ex:words:3:note":"やさしい","grammar:754:ex:words:3:pos":"adjective","grammar:754:ex:words:4:zh":"female","grammar:754:ex:words:4:note":"じょせい","grammar:754:ex:words:4:pos":"noun","grammar:754:ex:words:5:zh":"is","grammar:754:ex:words:5:pos":"copula","grammar:754:ex:points:0":"女性（じょせい）: woman.","grammar:754:ex:points:1":"優しい女性: a kind woman.","grammar:754:ex2:trans":"Many women are working.","grammar:754:ex2:structure":"〜が働いています","grammar:754:ex2:words:0:zh":"a lot","grammar:754:ex2:words:0:note":"おおく","grammar:754:ex2:words:0:pos":"noun","grammar:754:ex2:words:1:zh":"'s","grammar:754:ex2:words:1:pos":"particle","grammar:754:ex2:words:2:zh":"female","grammar:754:ex2:words:2:note":"じょせい","grammar:754:ex2:words:2:pos":"noun","grammar:754:ex2:words:3:zh":"(nominative)","grammar:754:ex2:words:3:pos":"particle","grammar:754:ex2:words:4:zh":"is working","grammar:754:ex2:words:4:note":"はたらいています","grammar:754:ex2:words:4:pos":"verb","grammar:754:ex2:points:0":"多くの女性: many women.","grammar:754:ex2:points:1":"〜ている: (the ongoing state of) working.","grammar:754:ex3:trans":"Women's rights are important.","grammar:754:ex3:structure":"〜は重要です","grammar:754:ex3:words:0:zh":"female","grammar:754:ex3:words:0:note":"じょせい","grammar:754:ex3:words:0:pos":"noun","grammar:754:ex3:words:1:zh":"'s","grammar:754:ex3:words:1:pos":"particle","grammar:754:ex3:words:2:zh":"rights","grammar:754:ex3:words:2:note":"けんり","grammar:754:ex3:words:2:pos":"noun","grammar:754:ex3:words:3:zh":"(topic)","grammar:754:ex3:words:3:pos":"particle","grammar:754:ex3:words:4:zh":"important","grammar:754:ex3:words:4:note":"じゅうよう","grammar:754:ex3:words:4:pos":"na-adjective","grammar:754:ex3:words:5:zh":"(polite form)","grammar:754:ex3:words:5:pos":"copula","grammar:754:ex3:points:0":"女性の権利: women's rights.","grammar:754:ex3:points:1":"権利: rights.","grammar:754:ex4:trans":"Awareness of women is rising.","grammar:754:ex4:structure":"〜に対する〜が高まっています","grammar:754:ex4:words:0:zh":"female","grammar:754:ex4:words:0:note":"じょせい","grammar:754:ex4:words:0:pos":"noun","grammar:754:ex4:words:1:zh":"toward","grammar:754:ex4:words:1:note":"にたいする","grammar:754:ex4:words:1:pos":"set phrase","grammar:754:ex4:words:2:zh":"awareness","grammar:754:ex4:words:2:note":"いしき","grammar:754:ex4:words:2:pos":"noun","grammar:754:ex4:words:3:zh":"(nominative)","grammar:754:ex4:words:3:pos":"particle","grammar:754:ex4:words:4:zh":"is rising","grammar:754:ex4:words:4:note":"たかまっています","grammar:754:ex4:words:4:pos":"verb","grammar:754:ex4:points:0":"❗〜に対する: toward … (attributive).","grammar:754:ex4:points:1":"高まる: to rise, to increase (intransitive verb).","grammar:754:ex5:trans":"Women's sports are popular too.","grammar:754:ex5:structure":"〜も人気があります","grammar:754:ex5:words:0:zh":"female","grammar:754:ex5:words:0:note":"じょせい","grammar:754:ex5:words:0:pos":"noun","grammar:754:ex5:words:1:zh":"'s","grammar:754:ex5:words:1:pos":"particle","grammar:754:ex5:words:2:zh":"exercise","grammar:754:ex5:words:2:note":"loanword","grammar:754:ex5:words:2:pos":"noun","grammar:754:ex5:words:3:zh":"also, too","grammar:754:ex5:words:3:pos":"particle","grammar:754:ex5:words:4:zh":"popularity","grammar:754:ex5:words:4:note":"にんき","grammar:754:ex5:words:4:pos":"noun","grammar:754:ex5:words:5:zh":"(nominative)","grammar:754:ex5:words:5:pos":"particle","grammar:754:ex5:words:6:zh":"there is / are","grammar:754:ex5:words:6:pos":"verb","grammar:754:ex5:points:0":"女性のスポーツ: women's sports.","grammar:754:ex5:points:1":"人気がある: to be popular."},"755":{"example:755:exzh":"Where do you live?","example:755:exzh2":"I want to hear your opinion.","example:755:exzh3":"Is this job right for you?","example:755:exzh4":"Do you like traveling?","example:755:exzh5":"What's your name?","grammar:755:ex:trans":"Where do you live?","grammar:755:ex:structure":"貴方は〜か","grammar:755:ex:explain":"The key point here is the kanji spelling 「貴方」 for 「あなた」, which is more formal and literary than the kana 「あなた」. The pattern 「貴方は〜か」 asks about the other person, and 「どこに住む」 marks the place you live with 「に」. The whole sentence means \"Where do you live?\" In real speech 「あなた」 is usually written in kana, while the kanji 「貴方」 leans toward letters and formal documents. In Japanese, addressing someone as you is still usually done by leaving it out or using their name plus さん.","grammar:755:ex:words:0:zh":"you","grammar:755:ex:words:0:note":"あなた","grammar:755:ex:words:0:pos":"pronoun","grammar:755:ex:words:1:zh":"(topic)","grammar:755:ex:words:1:pos":"particle","grammar:755:ex:words:2:zh":"where","grammar:755:ex:words:2:pos":"question word","grammar:755:ex:words:3:zh":"(location of existence)","grammar:755:ex:words:3:pos":"particle","grammar:755:ex:words:4:zh":"live (there)","grammar:755:ex:words:4:note":"すんでいます","grammar:755:ex:words:4:pos":"verb","grammar:755:ex:words:5:zh":"(question)","grammar:755:ex:words:5:pos":"particle","grammar:755:ex:points:0":"❗貴方（あなた）: you (kanji spelling, rather formal).","grammar:755:ex:points:1":"どこに住む: where one lives.","grammar:755:ex2:trans":"I'd like to hear your opinion.","grammar:755:ex2:structure":"貴方の〜を聞きたいです","grammar:755:ex2:words:0:zh":"you","grammar:755:ex2:words:0:note":"あなた","grammar:755:ex2:words:0:pos":"pronoun","grammar:755:ex2:words:1:zh":"'s","grammar:755:ex2:words:1:pos":"particle","grammar:755:ex2:words:2:zh":"opinion","grammar:755:ex2:words:2:note":"いけん","grammar:755:ex2:words:2:pos":"noun","grammar:755:ex2:words:3:zh":"(object marker)","grammar:755:ex2:words:3:pos":"particle","grammar:755:ex2:words:4:zh":"want to hear","grammar:755:ex2:words:4:note":"ききたい","grammar:755:ex2:words:4:pos":"verb","grammar:755:ex2:words:5:zh":"(polite form)","grammar:755:ex2:words:5:pos":"copula","grammar:755:ex2:points:0":"貴方の意見: your opinion.","grammar:755:ex2:points:1":"〜たい: to want to ….","grammar:755:ex3:trans":"Does this job suit you?","grammar:755:ex3:structure":"〜は〜に合っていますか","grammar:755:ex3:words:0:zh":"this","grammar:755:ex3:words:0:pos":"pre-noun adjectival","grammar:755:ex3:words:1:zh":"work","grammar:755:ex3:words:1:note":"しごと","grammar:755:ex3:words:1:pos":"noun","grammar:755:ex3:words:2:zh":"(topic)","grammar:755:ex3:words:2:pos":"particle","grammar:755:ex3:words:3:zh":"you","grammar:755:ex3:words:3:note":"あなた","grammar:755:ex3:words:3:pos":"pronoun","grammar:755:ex3:words:4:zh":"(object)","grammar:755:ex3:words:4:pos":"particle","grammar:755:ex3:words:5:zh":"to suit","grammar:755:ex3:words:5:note":"あっています","grammar:755:ex3:words:5:pos":"verb","grammar:755:ex3:words:6:zh":"(question)","grammar:755:ex3:words:6:pos":"particle","grammar:755:ex3:points:0":"❗〜に合う: to suit … (the object takes に).","grammar:755:ex3:points:1":"仕事が合う: the job suits.","grammar:755:ex4:trans":"Do you like traveling?","grammar:755:ex4:structure":"貴方は〜が好きですか","grammar:755:ex4:words:0:zh":"you","grammar:755:ex4:words:0:note":"あなた","grammar:755:ex4:words:0:pos":"pronoun","grammar:755:ex4:words:1:zh":"(topic)","grammar:755:ex4:words:1:pos":"particle","grammar:755:ex4:words:2:zh":"travel / trip","grammar:755:ex4:words:2:note":"りょこう","grammar:755:ex4:words:2:pos":"noun","grammar:755:ex4:words:3:zh":"(object)","grammar:755:ex4:words:3:pos":"particle","grammar:755:ex4:words:4:zh":"to like","grammar:755:ex4:words:4:note":"すき","grammar:755:ex4:words:4:pos":"na-adjective","grammar:755:ex4:words:5:zh":"(polite form)","grammar:755:ex4:words:5:pos":"copula","grammar:755:ex4:words:6:zh":"(question)","grammar:755:ex4:words:6:pos":"particle","grammar:755:ex4:points:0":"旅行が好き: to like traveling.","grammar:755:ex4:points:1":"貴方は: you (topic).","grammar:755:ex5:trans":"What is your name?","grammar:755:ex5:structure":"貴方の〜は何ですか","grammar:755:ex5:words:0:zh":"you","grammar:755:ex5:words:0:note":"あなた","grammar:755:ex5:words:0:pos":"pronoun","grammar:755:ex5:words:1:zh":"'s","grammar:755:ex5:words:1:pos":"particle","grammar:755:ex5:words:2:zh":"name","grammar:755:ex5:words:2:note":"なまえ","grammar:755:ex5:words:2:pos":"noun","grammar:755:ex5:words:3:zh":"(topic)","grammar:755:ex5:words:3:pos":"particle","grammar:755:ex5:words:4:zh":"what","grammar:755:ex5:words:4:note":"なん","grammar:755:ex5:words:4:pos":"question word","grammar:755:ex5:words:5:zh":"is","grammar:755:ex5:words:5:pos":"copula","grammar:755:ex5:words:6:zh":"(question)","grammar:755:ex5:words:6:pos":"particle","grammar:755:ex5:points:0":"貴方の名前: your name.","grammar:755:ex5:points:1":"何ですか: what is it.","exam:755:zh":"When you ask the name of the person in front of you, you say, 「What is your name?」","exam:755:why":"「あなた」 refers to the person you're talking to. 「彼」 refers to a man in the third person, so you can't use it to ask the other person their own name."},"756":{"example:756:exzh":"What's the reason?","example:756:exzh2":"I understand the reason.","example:756:exzh3":"There's a reason for his behavior.","example:756:exzh4":"There's a good reason for this choice.","example:756:exzh5":"Could you tell me the reason?","grammar:756:ex:trans":"What is that reason?","grammar:756:ex:structure":"〜は何ですか","grammar:756:ex:explain":"This is a question asking for a reason, using 「〜は何ですか」. 「理由（りゆう）」 (reason, cause) is modified by 「その」, 「は」 marks the topic, and the question word 「何」 asks about the content. The whole sentence means \"What is that reason?\" 「理由」 is a very useful word, often used in 「〜の理由」 (the reason for …) and 「理由は〜だ」 (the reason is …). This kind of 「AはBですか」 question is a basic skill.","grammar:756:ex:words:0:zh":"that","grammar:756:ex:words:0:pos":"pre-noun adjectival","grammar:756:ex:words:1:zh":"reason","grammar:756:ex:words:1:note":"りゆう","grammar:756:ex:words:1:pos":"noun","grammar:756:ex:words:2:zh":"(topic)","grammar:756:ex:words:2:pos":"particle","grammar:756:ex:words:3:zh":"what","grammar:756:ex:words:3:note":"なん","grammar:756:ex:words:3:pos":"question word","grammar:756:ex:words:4:zh":"is","grammar:756:ex:words:4:pos":"copula","grammar:756:ex:words:5:zh":"(question)","grammar:756:ex:words:5:pos":"particle","grammar:756:ex:points:0":"理由（りゆう）: reason, cause.","grammar:756:ex:points:1":"その理由: that reason.","grammar:756:ex2:trans":"I understand that reason.","grammar:756:ex2:structure":"〜を理解しています","grammar:756:ex2:words:0:zh":"I","grammar:756:ex2:words:0:note":"わたし","grammar:756:ex2:words:0:pos":"pronoun","grammar:756:ex2:words:1:zh":"(topic)","grammar:756:ex2:words:1:pos":"particle","grammar:756:ex2:words:2:zh":"that","grammar:756:ex2:words:2:pos":"pre-noun adjectival","grammar:756:ex2:words:3:zh":"reason","grammar:756:ex2:words:3:note":"りゆう","grammar:756:ex2:words:3:pos":"noun","grammar:756:ex2:words:4:zh":"(object marker)","grammar:756:ex2:words:4:pos":"particle","grammar:756:ex2:words:5:zh":"understands","grammar:756:ex2:words:5:note":"りかいしています","grammar:756:ex2:words:5:pos":"verb","grammar:756:ex2:points:0":"理由を理解する: to understand the reason.","grammar:756:ex2:points:1":"〜ている: (the state of) understanding.","grammar:756:ex3:trans":"There's a reason for his behavior.","grammar:756:ex3:structure":"〜には〜がある (〜 has 〜)","grammar:756:ex3:words:0:zh":"he","grammar:756:ex3:words:0:note":"かれ","grammar:756:ex3:words:0:pos":"pronoun","grammar:756:ex3:words:1:zh":"'s","grammar:756:ex3:words:1:pos":"particle","grammar:756:ex3:words:2:zh":"actions","grammar:756:ex3:words:2:note":"こうどう","grammar:756:ex3:words:2:pos":"noun","grammar:756:ex3:words:3:zh":"(object)","grammar:756:ex3:words:3:pos":"particle","grammar:756:ex3:words:4:zh":"(contrast)","grammar:756:ex3:words:4:pos":"particle","grammar:756:ex3:words:5:zh":"reason","grammar:756:ex3:words:5:note":"りゆう","grammar:756:ex3:words:5:pos":"noun","grammar:756:ex3:words:6:zh":"(nominative)","grammar:756:ex3:words:6:pos":"particle","grammar:756:ex3:words:7:zh":"there is / are","grammar:756:ex3:words:7:pos":"verb","grammar:756:ex3:points:0":"〜には理由がある: there is a reason for ….","grammar:756:ex3:points:1":"彼の行動: his behavior.","grammar:756:ex4:trans":"There's a good reason for this choice.","grammar:756:ex4:structure":"〜には〜がある (〜 has 〜)","grammar:756:ex4:words:0:zh":"this","grammar:756:ex4:words:0:pos":"pre-noun adjectival","grammar:756:ex4:words:1:zh":"choice","grammar:756:ex4:words:1:note":"せんたく","grammar:756:ex4:words:1:pos":"noun","grammar:756:ex4:words:2:zh":"(object)","grammar:756:ex4:words:2:pos":"particle","grammar:756:ex4:words:3:zh":"(contrast)","grammar:756:ex4:words:3:pos":"particle","grammar:756:ex4:words:4:zh":"good","grammar:756:ex4:words:4:note":"いい","grammar:756:ex4:words:4:pos":"adjective","grammar:756:ex4:words:5:zh":"reason","grammar:756:ex4:words:5:note":"りゆう","grammar:756:ex4:words:5:pos":"noun","grammar:756:ex4:words:6:zh":"(nominative)","grammar:756:ex4:words:6:pos":"particle","grammar:756:ex4:words:7:zh":"there is / are","grammar:756:ex4:words:7:pos":"verb","grammar:756:ex4:points:0":"良い理由: a good reason.","grammar:756:ex4:points:1":"この選択には: for this choice.","grammar:756:ex5:trans":"Could you tell me the reason?","grammar:756:ex5:structure":"〜を教えてくれませんか","grammar:756:ex5:words:0:zh":"reason","grammar:756:ex5:words:0:note":"りゆう","grammar:756:ex5:words:0:pos":"noun","grammar:756:ex5:words:1:zh":"(object marker)","grammar:756:ex5:words:1:pos":"particle","grammar:756:ex5:words:2:zh":"tell","grammar:756:ex5:words:2:note":"おしえて","grammar:756:ex5:words:2:pos":"verb","grammar:756:ex5:words:3:zh":"Can you ... for me?","grammar:756:ex5:words:3:pos":"auxiliary verb","grammar:756:ex5:points:0":"❗〜てくれませんか: can you ... (for me)? (polite request).","grammar:756:ex5:points:1":"理由を教える: to tell someone the reason."},"757":{"example:757:exzh":"I'm getting ready for a trip.","example:757:exzh2":"Are you ready?","example:757:exzh3":"Preparing the documents took time.","example:757:exzh4":"We're getting things ready for the event.","example:757:exzh5":"I have to prepare for the exam.","grammar:757:ex:trans":"I'm preparing for a trip.","grammar:757:ex:structure":"〜の準備をしています","grammar:757:ex:explain":"This sentence uses the idiomatic pattern 「〜の準備をする」 (to make preparations for ...). 「準備をする」 is the same as 「準備する」; 「を」 marks the object 「準備」, and 「の」 links 「旅行」 to 「準備」 to form 「旅行準備」. 「〜ています」 shows an ongoing action. The whole sentence means I'm preparing for a trip. Many verbs formed from a Sino-Japanese noun plus 「する」 can also be split into 「〜をする」, with almost the same nuance.","grammar:757:ex:words:0:zh":"travel / trip","grammar:757:ex:words:0:note":"りょこう","grammar:757:ex:words:0:pos":"noun","grammar:757:ex:words:1:zh":"'s","grammar:757:ex:words:1:pos":"particle","grammar:757:ex:words:2:zh":"prepare","grammar:757:ex:words:2:note":"じゅんび","grammar:757:ex:words:2:pos":"noun","grammar:757:ex:words:3:zh":"(object marker)","grammar:757:ex:words:3:pos":"particle","grammar:757:ex:words:4:zh":"is doing","grammar:757:ex:words:4:pos":"verb","grammar:757:ex:points:0":"準備をする: to make preparations (= 準備する).","grammar:757:ex:points:1":"旅行の準備: trip preparations.","grammar:757:ex2:trans":"Are you ready?","grammar:757:ex2:structure":"〜ができましたか","grammar:757:ex2:words:0:zh":"prepare","grammar:757:ex2:words:0:note":"じゅんび","grammar:757:ex2:words:0:pos":"noun","grammar:757:ex2:words:1:zh":"(nominative)","grammar:757:ex2:words:1:pos":"particle","grammar:757:ex2:words:2:zh":"done","grammar:757:ex2:words:2:pos":"verb","grammar:757:ex2:words:3:zh":"(question)","grammar:757:ex2:words:3:pos":"particle","grammar:757:ex2:points:0":"❗準備ができる: to be ready (できる here shows completion).","grammar:757:ex2:points:1":"〜ができる: ... is done / can be done.","grammar:757:ex3:trans":"Preparing the materials took a lot of time.","grammar:757:ex3:structure":"〜に時間がかかった","grammar:757:ex3:words:0:zh":"materials","grammar:757:ex3:words:0:note":"しりょう","grammar:757:ex3:words:0:pos":"noun","grammar:757:ex3:words:1:zh":"'s","grammar:757:ex3:words:1:pos":"particle","grammar:757:ex3:words:2:zh":"prepare","grammar:757:ex3:words:2:note":"じゅんび","grammar:757:ex3:words:2:pos":"noun","grammar:757:ex3:words:3:zh":"(object)","grammar:757:ex3:words:3:pos":"particle","grammar:757:ex3:words:4:zh":"time","grammar:757:ex3:words:4:note":"じかん","grammar:757:ex3:words:4:pos":"noun","grammar:757:ex3:words:5:zh":"(nominative)","grammar:757:ex3:words:5:pos":"particle","grammar:757:ex3:words:6:zh":"spent","grammar:757:ex3:words:6:pos":"verb","grammar:757:ex3:points:0":"〜に時間がかかる: to take time.","grammar:757:ex3:points:1":"資料の準備: preparing the materials.","grammar:757:ex4:trans":"We're making preparations for the event.","grammar:757:ex4:structure":"〜ために〜を進めています","grammar:757:ex4:words:0:zh":"event","grammar:757:ex4:words:0:note":"loanword","grammar:757:ex4:words:0:pos":"noun","grammar:757:ex4:words:1:zh":"'s","grammar:757:ex4:words:1:pos":"particle","grammar:757:ex4:words:2:zh":"for the sake of","grammar:757:ex4:words:2:pos":"particle","grammar:757:ex4:words:3:zh":"prepare","grammar:757:ex4:words:3:note":"じゅんび","grammar:757:ex4:words:3:pos":"noun","grammar:757:ex4:words:4:zh":"(object marker)","grammar:757:ex4:words:4:pos":"particle","grammar:757:ex4:words:5:zh":"pushing forward","grammar:757:ex4:words:5:note":"すすめています","grammar:757:ex4:words:5:pos":"verb","grammar:757:ex4:points:0":"準備を進める: to push the preparations forward.","grammar:757:ex4:points:1":"〜のために: for the sake of …","grammar:757:ex5:trans":"I have to prepare for the exam.","grammar:757:ex5:structure":"〜をしなければならない","grammar:757:ex5:words:0:zh":"test","grammar:757:ex5:words:0:note":"しけん","grammar:757:ex5:words:0:pos":"noun","grammar:757:ex5:words:1:zh":"'s","grammar:757:ex5:words:1:pos":"particle","grammar:757:ex5:words:2:zh":"prepare","grammar:757:ex5:words:2:note":"じゅんび","grammar:757:ex5:words:2:pos":"noun","grammar:757:ex5:words:3:zh":"(object marker)","grammar:757:ex5:words:3:pos":"particle","grammar:757:ex5:words:4:zh":"must do","grammar:757:ex5:words:4:pos":"verb","grammar:757:ex5:points:0":"❗〜なければならない: must ...","grammar:757:ex5:points:1":"試験の準備: exam preparation."},"758":{"example:758:exzh":"Thank you for your help.","example:758:exzh2":"You gave me this book.","example:758:exzh3":"You explained it in detail.","example:758:exzh4":"I'm grateful to the person who gave me advice.","example:758:exzh5":"It would help if you could give me the information.","grammar:758:ex:trans":"Thank you for your help.","grammar:758:ex:structure":"〜てくださってありがとうございます","grammar:758:ex:explain":"This sentence uses the kanji spelling 「下さる」 of 「くださる」; the meaning is the same — both are the sonkeigo (respectful) form of 「くれる」. 「〜てくださって」 means that someone (respectfully) did something for me, carries a tone of gratitude, and is followed by words of thanks. The whole sentence means 'Thank you for your help.' 「〜てくださってありがとうございます」 is a very polite way of thanking someone, more polite than 「〜てくれてありがとう」.","grammar:758:ex:words:0:zh":"help","grammar:758:ex:words:0:note":"てつだって","grammar:758:ex:words:0:pos":"verb","grammar:758:ex:words:1:zh":"does something for me (respectful)","grammar:758:ex:words:1:note":"くださって","grammar:758:ex:words:1:pos":"verb","grammar:758:ex:words:2:zh":"thank you very much","grammar:758:ex:words:2:pos":"set phrase","grammar:758:ex:points:0":"❗下さる＝くださる (kanji spelling); 〜てくださって＝(respectful) does something for me… (expresses gratitude).","grammar:758:ex:points:1":"下さる: (respectful) does something for me.","grammar:758:ex2:trans":"You gave me this book.","grammar:758:ex2:structure":"〜を私にくださった","grammar:758:ex2:words:0:zh":"this","grammar:758:ex2:words:0:pos":"pre-noun adjectival","grammar:758:ex2:words:1:zh":"book","grammar:758:ex2:words:1:note":"ほん","grammar:758:ex2:words:1:pos":"noun","grammar:758:ex2:words:2:zh":"(object marker)","grammar:758:ex2:words:2:pos":"particle","grammar:758:ex2:words:3:zh":"I","grammar:758:ex2:words:3:note":"わたし","grammar:758:ex2:words:3:pos":"pronoun","grammar:758:ex2:words:4:zh":"(object)","grammar:758:ex2:words:4:pos":"particle","grammar:758:ex2:words:5:zh":"gave (respectful)","grammar:758:ex2:words:5:note":"くださった","grammar:758:ex2:words:5:pos":"verb","grammar:758:ex2:points:0":"❗〜をくださった: (respectful) gave me… (the subject is the other person, e.g. a senior or a boss).","grammar:758:ex2:points:1":"くださった: (respectful) gave me.","grammar:758:ex3:trans":"You explained it in detail.","grammar:758:ex3:structure":"詳しく説明してくださった","grammar:758:ex3:words:0:zh":"in detail","grammar:758:ex3:words:0:note":"くわしく","grammar:758:ex3:words:0:pos":"adjective","grammar:758:ex3:words:1:zh":"explanation","grammar:758:ex3:words:1:note":"せつめいして","grammar:758:ex3:words:1:pos":"verb","grammar:758:ex3:words:2:zh":"does something for me (respectful)","grammar:758:ex3:words:2:note":"くださった","grammar:758:ex3:words:2:pos":"verb","grammar:758:ex3:points:0":"❗説明してくださった: (kindly) explained it for me (respectful); 詳しく＝in detail.","grammar:758:ex3:points:1":"説明してくださる: (respectful) explains it for me.","grammar:758:ex4:trans":"I am grateful to the person who gave me advice.","grammar:758:ex4:structure":"〜をくださった方に感謝します","grammar:758:ex4:words:0:zh":"advice","grammar:758:ex4:words:0:note":"loanword","grammar:758:ex4:words:0:pos":"noun","grammar:758:ex4:words:1:zh":"(object marker)","grammar:758:ex4:words:1:pos":"particle","grammar:758:ex4:words:2:zh":"gave (respectful)","grammar:758:ex4:words:2:note":"くださった","grammar:758:ex4:words:2:pos":"verb","grammar:758:ex4:words:3:zh":"person (respectful)","grammar:758:ex4:words:3:note":"かた","grammar:758:ex4:words:3:pos":"noun","grammar:758:ex4:words:4:zh":"(object)","grammar:758:ex4:words:4:pos":"particle","grammar:758:ex4:words:5:zh":"gratitude","grammar:758:ex4:words:5:note":"かんしゃします","grammar:758:ex4:words:5:pos":"verb","grammar:758:ex4:points:0":"❗くださった方: (respectful) the person who gave it to me; 方（かた）＝the respectful word for a person.","grammar:758:ex4:points:1":"くださった方: the person who kindly gave it.","grammar:758:ex5:trans":"It would be great if you could give me the information.","grammar:758:ex5:structure":"〜をくださると助かります","grammar:758:ex5:words:0:zh":"information","grammar:758:ex5:words:0:note":"じょうほう","grammar:758:ex5:words:0:pos":"noun","grammar:758:ex5:words:1:zh":"(object marker)","grammar:758:ex5:words:1:pos":"particle","grammar:758:ex5:words:2:zh":"gave (respectful)","grammar:758:ex5:words:2:note":"くださる","grammar:758:ex5:words:2:pos":"verb","grammar:758:ex5:words:3:zh":"(condition)","grammar:758:ex5:words:3:pos":"particle","grammar:758:ex5:words:4:zh":"grateful","grammar:758:ex5:words:4:note":"たすかります","grammar:758:ex5:words:4:pos":"verb","grammar:758:ex5:points:0":"❗〜をくださると助かります: it would really help if you could give me… (polite request).","grammar:758:ex5:points:1":"くださると助かる: it helps if you give it to me."},"759":{"example:759:exzh":"It's important to follow the rules.","example:759:exzh2":"I fought to protect him.","example:759:exzh3":"Keeping a promise is proof of trust.","example:759:exzh4":"You should stand by your own opinion.","example:759:exzh5":"Following the law is a citizen's duty."},"760":{"example:760:exzh":"I'll show you my work.","example:760:exzh2":"Please show me this photo.","example:760:exzh3":"He showed me his new shoes.","example:760:exzh4":"The school's results were shown.","example:760:exzh5":"I'll show you the movie trailer.","grammar:760:ex:trans":"I'll show you my work.","grammar:760:ex:structure":"〜を見せてあげる","grammar:760:ex:explain":"The core of this sentence is the auxiliary giving-and-receiving verb 「〜てあげる」, which means “(I) do something for (someone else)” and carries a sense of doing someone a favor. 「見せてあげる」 = (I) show you. 「見せる」 itself is a transitive verb meaning “to let someone see, to show,” and 「を」 marks its object 「作品」. The whole sentence means “I'll show you my work.” Be careful about who you use 「〜てあげる」 with — using it toward a senior can sound condescending.","grammar:760:ex:words:0:zh":"I","grammar:760:ex:words:0:note":"わたし","grammar:760:ex:words:0:pos":"pronoun","grammar:760:ex:words:1:zh":"'s","grammar:760:ex:words:1:pos":"particle","grammar:760:ex:words:2:zh":"work (of art)","grammar:760:ex:words:2:note":"さくひん","grammar:760:ex:words:2:pos":"noun","grammar:760:ex:words:3:zh":"(object marker)","grammar:760:ex:words:3:pos":"particle","grammar:760:ex:words:4:zh":"show (someone)","grammar:760:ex:words:4:note":"みせて","grammar:760:ex:words:4:pos":"verb","grammar:760:ex:words:5:zh":"(do for you)","grammar:760:ex:words:5:pos":"auxiliary verb","grammar:760:ex:points:0":"❗〜てあげる: (I) do … for (someone else) (見せてあげる = I'll show you).","grammar:760:ex:points:1":"作品を見せる: to show one's work.","grammar:760:ex2:trans":"Please show me this photo.","grammar:760:ex2:structure":"〜を見せてください","grammar:760:ex2:words:0:zh":"this","grammar:760:ex2:words:0:pos":"pre-noun adjectival","grammar:760:ex2:words:1:zh":"photo","grammar:760:ex2:words:1:note":"しゃしん","grammar:760:ex2:words:1:pos":"noun","grammar:760:ex2:words:2:zh":"(object marker)","grammar:760:ex2:words:2:pos":"particle","grammar:760:ex2:words:3:zh":"show (someone)","grammar:760:ex2:words:3:note":"みせて","grammar:760:ex2:words:3:pos":"verb","grammar:760:ex2:words:4:zh":"please","grammar:760:ex2:words:4:pos":"auxiliary verb","grammar:760:ex2:points:0":"写真を見せる: to show a photo.","grammar:760:ex2:points:1":"見せてください: please show me.","grammar:760:ex3:trans":"He showed me his new shoes.","grammar:760:ex3:structure":"〜を見せてくれた","grammar:760:ex3:words:0:zh":"he","grammar:760:ex3:words:0:note":"かれ","grammar:760:ex3:words:0:pos":"pronoun","grammar:760:ex3:words:1:zh":"(topic)","grammar:760:ex3:words:1:pos":"particle","grammar:760:ex3:words:2:zh":"new","grammar:760:ex3:words:2:note":"あたらしい","grammar:760:ex3:words:2:pos":"adjective","grammar:760:ex3:words:3:zh":"shoes","grammar:760:ex3:words:3:note":"くつ","grammar:760:ex3:words:3:pos":"noun","grammar:760:ex3:words:4:zh":"(object marker)","grammar:760:ex3:words:4:pos":"particle","grammar:760:ex3:words:5:zh":"show (someone)","grammar:760:ex3:words:5:note":"みせて","grammar:760:ex3:words:5:pos":"verb","grammar:760:ex3:words:6:zh":"did (for me)","grammar:760:ex3:words:6:pos":"auxiliary verb","grammar:760:ex3:points:0":"❗〜てくれた: (someone else) did ... for me.","grammar:760:ex3:points:1":"新しい靴: new shoes.","grammar:760:ex4:trans":"Showed the school's achievements.","grammar:760:ex4:structure":"〜を見せた","grammar:760:ex4:words:0:zh":"school","grammar:760:ex4:words:0:note":"がっこう","grammar:760:ex4:words:0:pos":"noun","grammar:760:ex4:words:1:zh":"'s","grammar:760:ex4:words:1:pos":"particle","grammar:760:ex4:words:2:zh":"results","grammar:760:ex4:words:2:note":"せいか","grammar:760:ex4:words:2:pos":"noun","grammar:760:ex4:words:3:zh":"(object marker)","grammar:760:ex4:words:3:pos":"particle","grammar:760:ex4:words:4:zh":"showed","grammar:760:ex4:words:4:note":"みせた","grammar:760:ex4:words:4:pos":"verb","grammar:760:ex4:points:0":"❗成果: results, achievements.","grammar:760:ex4:points:1":"成果を見せる: to show results.","grammar:760:ex5:trans":"I'll show you the movie trailer.","grammar:760:ex5:structure":"〜を見せてあげるよ","grammar:760:ex5:words:0:zh":"movie","grammar:760:ex5:words:0:note":"えいが","grammar:760:ex5:words:0:pos":"noun","grammar:760:ex5:words:1:zh":"'s","grammar:760:ex5:words:1:pos":"particle","grammar:760:ex5:words:2:zh":"trailer","grammar:760:ex5:words:2:note":"よこく","grammar:760:ex5:words:2:pos":"noun","grammar:760:ex5:words:3:zh":"(object marker)","grammar:760:ex5:words:3:pos":"particle","grammar:760:ex5:words:4:zh":"show (someone)","grammar:760:ex5:words:4:note":"みせて","grammar:760:ex5:words:4:pos":"verb","grammar:760:ex5:words:5:zh":"(do for you)","grammar:760:ex5:words:5:pos":"auxiliary verb","grammar:760:ex5:words:6:zh":"(informing)","grammar:760:ex5:words:6:pos":"particle","grammar:760:ex5:points:0":"❗予告: preview (trailer).","grammar:760:ex5:points:1":"〜てあげるよ: (I)'ll do … for you."},"761":{"example:761:exzh":"I started a new project.","example:761:exzh2":"It's time to start studying.","example:761:exzh3":"I'll start working from this summer vacation.","example:761:exzh4":"He just started piano.","example:761:exzh5":"What time does the movie start?","grammar:761:ex:trans":"I started a new project.","grammar:761:ex:structure":"〜を始めました","grammar:761:ex:explain":"This sentence asks you to keep the transitive verb 「始める」 and the intransitive verb 「始まる」 apart: 「始める」 means someone actively starts something (it takes を), while 「始まる」 means the thing starts on its own. Here 「プロジェクトを始める」 marks the object with 「を」 and means “to start a project.” 「始めました」 is the past tense. The whole sentence means “I started a new project.” Learn transitive–intransitive pairs (授業を始める / 授業が始まる) as a set.","grammar:761:ex:words:0:zh":"new","grammar:761:ex:words:0:note":"あたらしい","grammar:761:ex:words:0:pos":"adjective","grammar:761:ex:words:1:zh":"project","grammar:761:ex:words:1:note":"loanword","grammar:761:ex:words:1:pos":"noun","grammar:761:ex:words:2:zh":"(object marker)","grammar:761:ex:words:2:pos":"particle","grammar:761:ex:words:3:zh":"started","grammar:761:ex:words:3:note":"はじめました","grammar:761:ex:words:3:pos":"verb","grammar:761:ex:points:0":"❗始める (transitive verb, to start …)＋を; vs 始まる (intransitive verb).","grammar:761:ex:points:1":"プロジェクトを始める: to start a project.","grammar:761:ex2:trans":"It's time to start studying.","grammar:761:ex2:structure":"〜を始める時間です","grammar:761:ex2:words:0:zh":"study","grammar:761:ex2:words:0:note":"べんきょう","grammar:761:ex2:words:0:pos":"noun","grammar:761:ex2:words:1:zh":"(object marker)","grammar:761:ex2:words:1:pos":"particle","grammar:761:ex2:words:2:zh":"begins","grammar:761:ex2:words:2:note":"はじめる","grammar:761:ex2:words:2:pos":"verb","grammar:761:ex2:words:3:zh":"time","grammar:761:ex2:words:3:note":"じかん","grammar:761:ex2:words:3:pos":"noun","grammar:761:ex2:words:4:zh":"(polite form)","grammar:761:ex2:words:4:pos":"copula","grammar:761:ex2:points:0":"勉強を始める: to start studying.","grammar:761:ex2:points:1":"〜時間です: it's time to …","grammar:761:ex3:trans":"I'll start working from this summer vacation.","grammar:761:ex3:structure":"〜から〜始めます","grammar:761:ex3:words:0:zh":"this","grammar:761:ex3:words:0:pos":"pre-noun adjectival","grammar:761:ex3:words:1:zh":"summer vacation","grammar:761:ex3:words:1:note":"なつやすみ","grammar:761:ex3:words:1:pos":"noun","grammar:761:ex3:words:2:zh":"from","grammar:761:ex3:words:2:pos":"particle","grammar:761:ex3:words:3:zh":"to start working","grammar:761:ex3:words:3:note":"はたらきはじめます","grammar:761:ex3:words:3:pos":"verb","grammar:761:ex3:points:0":"❗〜始める: to start … (働く＋始める = to start working).","grammar:761:ex3:points:1":"夏休みから: starting from summer vacation.","grammar:761:ex4:trans":"He has just started learning the piano.","grammar:761:ex4:structure":"〜を始めたばかりです","grammar:761:ex4:words:0:zh":"he","grammar:761:ex4:words:0:note":"かれ","grammar:761:ex4:words:0:pos":"pronoun","grammar:761:ex4:words:1:zh":"(topic)","grammar:761:ex4:words:1:pos":"particle","grammar:761:ex4:words:2:zh":"piano","grammar:761:ex4:words:2:note":"loanword","grammar:761:ex4:words:2:pos":"noun","grammar:761:ex4:words:3:zh":"(object marker)","grammar:761:ex4:words:3:pos":"particle","grammar:761:ex4:words:4:zh":"started","grammar:761:ex4:words:4:note":"はじめた","grammar:761:ex4:words:4:pos":"verb","grammar:761:ex4:words:5:zh":"just","grammar:761:ex4:words:5:pos":"particle","grammar:761:ex4:words:6:zh":"(polite form)","grammar:761:ex4:words:6:pos":"copula","grammar:761:ex4:points:0":"❗〜たばかり: just … (not long ago).","grammar:761:ex4:points:1":"ピアノを始める: to start learning the piano.","grammar:761:ex5:trans":"What time does the movie start?","grammar:761:ex5:structure":"(should be 映画は何時に始まる)","grammar:761:ex5:words:0:zh":"movie","grammar:761:ex5:words:0:note":"えいが","grammar:761:ex5:words:0:pos":"noun","grammar:761:ex5:words:1:zh":"(topic)","grammar:761:ex5:words:1:pos":"particle","grammar:761:ex5:words:2:zh":"what time","grammar:761:ex5:words:2:note":"なんじ","grammar:761:ex5:words:2:pos":"question word","grammar:761:ex5:words:3:zh":"(point in time)","grammar:761:ex5:words:3:pos":"particle","grammar:761:ex5:words:4:zh":"(incorrect)","grammar:761:ex5:words:4:note":"はじめる","grammar:761:ex5:words:4:pos":"verb","grammar:761:ex5:words:5:zh":"(question)","grammar:761:ex5:words:5:pos":"particle","grammar:761:ex5:points:0":"❗「映画は何時に始める」 is wrong: for a movie starting on its own, use the intransitive 「始まる」 → 「何時に始まるの？」.","grammar:761:ex5:points:1":"始まる≠始める。"},"762":{"example:762:exzh":"A number is written here.","example:762:exzh2":"She's good at counting numbers.","example:762:exzh3":"This number is big.","example:762:exzh4":"The numbers are increasing.","example:762:exzh5":"How many numbers are there?","grammar:762:ex:trans":"The number is written here.","grammar:762:ex:structure":"〜が書いてあります","grammar:762:ex:explain":"The key here is 「〜てある」, which shows the state left behind after someone did something on purpose. 「書いてある」 means it has been written (by someone) and is there now, emphasizing the resulting state someone intentionally created. 「数」 (かず, number) is marked with 「が」. The whole sentence means the number is written here. Distinguish it from 「〜ている」: 「てある」 usually pairs with a transitive verb and implies someone did it, while 「ている」 often shows an action in progress or a natural state.","grammar:762:ex:words:0:zh":"here","grammar:762:ex:words:0:pos":"pronoun","grammar:762:ex:words:1:zh":"(location of existence)","grammar:762:ex:words:1:pos":"particle","grammar:762:ex:words:2:zh":"number","grammar:762:ex:words:2:note":"かず","grammar:762:ex:words:2:pos":"noun","grammar:762:ex:words:3:zh":"(nominative)","grammar:762:ex:words:3:pos":"particle","grammar:762:ex:words:4:zh":"is written","grammar:762:ex:words:4:note":"かいてあります","grammar:762:ex:words:4:pos":"verb","grammar:762:ex:points:0":"❗〜てある: the state left behind (on purpose) (書いてある = is written).","grammar:762:ex:points:1":"数（かず）: number, quantity.","grammar:762:ex2:trans":"She's good at counting numbers.","grammar:762:ex2:structure":"〜のが得意です","grammar:762:ex2:words:0:zh":"she","grammar:762:ex2:words:0:note":"かのじょ","grammar:762:ex2:words:0:pos":"pronoun","grammar:762:ex2:words:1:zh":"(topic)","grammar:762:ex2:words:1:pos":"particle","grammar:762:ex2:words:2:zh":"number","grammar:762:ex2:words:2:note":"かず","grammar:762:ex2:words:2:pos":"noun","grammar:762:ex2:words:3:zh":"(object marker)","grammar:762:ex2:words:3:pos":"particle","grammar:762:ex2:words:4:zh":"count","grammar:762:ex2:words:4:note":"かぞえる","grammar:762:ex2:words:4:pos":"verb","grammar:762:ex2:words:5:zh":"(nominalizer)","grammar:762:ex2:words:5:pos":"particle","grammar:762:ex2:words:6:zh":"(object)","grammar:762:ex2:words:6:pos":"particle","grammar:762:ex2:words:7:zh":"good at","grammar:762:ex2:words:7:note":"とくい","grammar:762:ex2:words:7:pos":"na-adjective","grammar:762:ex2:words:8:zh":"(polite form)","grammar:762:ex2:words:8:pos":"copula","grammar:762:ex2:points:0":"数を数える: to count numbers (数 is a noun / 数える is a verb).","grammar:762:ex2:points:1":"〜のが得意: to be good at doing ...","grammar:762:ex3:trans":"This number is big.","grammar:762:ex3:structure":"〜は大きいです","grammar:762:ex3:words:0:zh":"this","grammar:762:ex3:words:0:pos":"pre-noun adjectival","grammar:762:ex3:words:1:zh":"number","grammar:762:ex3:words:1:note":"かず","grammar:762:ex3:words:1:pos":"noun","grammar:762:ex3:words:2:zh":"(topic)","grammar:762:ex3:words:2:pos":"particle","grammar:762:ex3:words:3:zh":"big","grammar:762:ex3:words:3:note":"おおきい","grammar:762:ex3:words:3:pos":"adjective","grammar:762:ex3:words:4:zh":"(polite form)","grammar:762:ex3:words:4:pos":"copula","grammar:762:ex3:points:0":"この数: this number.","grammar:762:ex3:points:1":"大きい: big.","grammar:762:ex4:trans":"The number is increasing.","grammar:762:ex4:structure":"〜が増えてきています","grammar:762:ex4:words:0:zh":"quantity","grammar:762:ex4:words:0:note":"かず","grammar:762:ex4:words:0:pos":"noun","grammar:762:ex4:words:1:zh":"(nominative)","grammar:762:ex4:words:1:pos":"particle","grammar:762:ex4:words:2:zh":"gradually increasing","grammar:762:ex4:words:2:note":"ふえてきています","grammar:762:ex4:words:2:pos":"verb","grammar:762:ex4:points:0":"増える: to increase (intransitive verb).","grammar:762:ex4:points:1":"〜てくる: to start to ... (gradually).","grammar:762:ex5:trans":"How many numbers are there?","grammar:762:ex5:structure":"いくつの〜がありますか","grammar:762:ex5:words:0:zh":"a few","grammar:762:ex5:words:0:pos":"question word","grammar:762:ex5:words:1:zh":"'s","grammar:762:ex5:words:1:pos":"particle","grammar:762:ex5:words:2:zh":"number","grammar:762:ex5:words:2:note":"かず","grammar:762:ex5:words:2:pos":"noun","grammar:762:ex5:words:3:zh":"(nominative)","grammar:762:ex5:words:3:pos":"particle","grammar:762:ex5:words:4:zh":"there is / are","grammar:762:ex5:words:4:pos":"verb","grammar:762:ex5:words:5:zh":"(question)","grammar:762:ex5:words:5:pos":"particle","grammar:762:ex5:points:0":"いくつ: how many.","grammar:762:ex5:points:1":"〜がありますか: is there ...? / are there ...?"},"763":{"example:763:exzh":"I'm going.","example:763:exzh2":"My friend.","example:763:exzh3":"I like Japan.","example:763:exzh4":"It's me!","example:763:exzh5":"I'll do my best.","grammar:763:ex:trans":"I'm going.","grammar:763:ex:structure":"オレは〜よ","grammar:763:ex:words:0:zh":"I","grammar:763:ex:words:0:note":"おれ","grammar:763:ex:words:0:pos":"pronoun","grammar:763:ex:words:1:zh":"(topic)","grammar:763:ex:words:1:pos":"particle","grammar:763:ex:words:2:zh":"go","grammar:763:ex:words:2:note":"いく","grammar:763:ex:words:2:pos":"verb","grammar:763:ex:words:3:zh":"(tone)","grammar:763:ex:words:3:pos":"particle","grammar:763:ex:points:1":"よ: (informing) tone.","grammar:763:ex2:trans":"My friend.","grammar:763:ex2:structure":"オレの〜","grammar:763:ex2:words:0:zh":"I","grammar:763:ex2:words:0:note":"おれ","grammar:763:ex2:words:0:pos":"pronoun","grammar:763:ex2:words:1:zh":"'s","grammar:763:ex2:words:1:pos":"particle","grammar:763:ex2:words:2:zh":"friend","grammar:763:ex2:words:2:note":"ともだち","grammar:763:ex2:words:2:pos":"noun","grammar:763:ex2:points:0":"オレの友達: my friend.","grammar:763:ex2:points:1":"オレ: (masculine) I.","grammar:763:ex3:trans":"I like Japan.","grammar:763:ex3:structure":"オレは〜が好きだ","grammar:763:ex3:words:0:zh":"I","grammar:763:ex3:words:0:note":"おれ","grammar:763:ex3:words:0:pos":"pronoun","grammar:763:ex3:words:1:zh":"(topic)","grammar:763:ex3:words:1:pos":"particle","grammar:763:ex3:words:2:zh":"Japan","grammar:763:ex3:words:2:note":"にほん","grammar:763:ex3:words:2:pos":"noun","grammar:763:ex3:words:3:zh":"(object)","grammar:763:ex3:words:3:pos":"particle","grammar:763:ex3:words:4:zh":"to like","grammar:763:ex3:words:4:note":"すき","grammar:763:ex3:words:4:pos":"na-adjective","grammar:763:ex3:words:5:zh":"is","grammar:763:ex3:words:5:pos":"copula","grammar:763:ex3:points:0":"日本が好き: to like Japan.","grammar:763:ex3:points:1":"だ: (is) plain form.","grammar:763:ex4:trans":"It's me!","grammar:763:ex4:structure":"オレだよ！","grammar:763:ex4:words:0:zh":"I","grammar:763:ex4:words:0:note":"おれ","grammar:763:ex4:words:0:pos":"pronoun","grammar:763:ex4:words:1:zh":"is","grammar:763:ex4:words:1:pos":"copula","grammar:763:ex4:words:2:zh":"(tone)","grammar:763:ex4:words:2:pos":"particle","grammar:763:ex4:points:0":"オレだよ: it's me (announcing who you are).","grammar:763:ex4:points:1":"よ: informing tone.","grammar:763:ex5:trans":"I'll do my best.","grammar:763:ex5:structure":"オレは〜","grammar:763:ex5:words:0:zh":"I","grammar:763:ex5:words:0:note":"おれ","grammar:763:ex5:words:0:pos":"pronoun","grammar:763:ex5:words:1:zh":"(topic)","grammar:763:ex5:words:1:pos":"particle","grammar:763:ex5:words:2:zh":"effort","grammar:763:ex5:words:2:note":"がんばる","grammar:763:ex5:words:2:pos":"verb","grammar:763:ex5:points:0":"「頑張る」: to work hard, to do your best.","grammar:763:ex5:points:1":"オレは頑張る: I'll give it my all."},"764":{"example:764:exzh":"Enjoy the trip.","example:764:exzh2":"I'm enjoying hanging out with him.","example:764:exzh3":"I'm enjoying watching movies.","example:764:exzh4":"I'm enjoying the time I spend with friends.","example:764:exzh5":"Time to enjoy a hobby."},"765":{"example:765:exzh":"Please come this way.","example:765:exzh2":"This is my house.","example:765:exzh3":"This way, please.","example:765:exzh4":"This is my business card.","example:765:exzh5":"Please wait here.","grammar:765:ex:trans":"Please come this way.","grammar:765:ex:structure":"こちらに〜てください","grammar:765:ex:explain":"The point here is the polite demonstrative 「こちら」, which is more courteous than 「ここ」; it means this way / here, and can also politely mean this person. 「こちらに来てください」 means please come this way. 「に」 marks the destination, and 「来て」 is the te-form plus 「ください」 to make a request. The whole sentence means please come this way. 「こちら・そちら・あちら」 are the polite versions of 「ここ・そこ・あそこ」 and are common in customer service.","grammar:765:ex:words:0:zh":"this way","grammar:765:ex:words:0:pos":"pronoun","grammar:765:ex:words:1:zh":"(the destination point)","grammar:765:ex:words:1:pos":"particle","grammar:765:ex:words:2:zh":"come","grammar:765:ex:words:2:note":"きて","grammar:765:ex:words:2:pos":"verb","grammar:765:ex:words:3:zh":"please","grammar:765:ex:words:3:pos":"auxiliary verb","grammar:765:ex:points:0":"❗こちら: this way, this person (the polite form of here).","grammar:765:ex:points:1":"来る→来て＋ください.","grammar:765:ex2:trans":"This is my house.","grammar:765:ex2:structure":"こちらは〜です","grammar:765:ex2:words:0:zh":"here","grammar:765:ex2:words:0:pos":"pronoun","grammar:765:ex2:words:1:zh":"(topic)","grammar:765:ex2:words:1:pos":"particle","grammar:765:ex2:words:2:zh":"I","grammar:765:ex2:words:2:note":"わたし","grammar:765:ex2:words:2:pos":"pronoun","grammar:765:ex2:words:3:zh":"'s","grammar:765:ex2:words:3:pos":"particle","grammar:765:ex2:words:4:zh":"house","grammar:765:ex2:words:4:note":"いえ","grammar:765:ex2:words:4:pos":"noun","grammar:765:ex2:words:5:zh":"is","grammar:765:ex2:words:5:pos":"copula","grammar:765:ex2:points:0":"こちらは: this is (polite).","grammar:765:ex2:points:1":"「私の家」: my house.","grammar:765:ex3:trans":"We'll take care of it from our side.","grammar:765:ex3:structure":"こちらから〜","grammar:765:ex3:words:0:zh":"this way","grammar:765:ex3:words:0:pos":"pronoun","grammar:765:ex3:words:1:zh":"from","grammar:765:ex3:words:1:pos":"particle","grammar:765:ex3:words:2:zh":"please","grammar:765:ex3:words:2:note":"おねがいします","grammar:765:ex3:words:2:pos":"set phrase","grammar:765:ex3:points:0":"こちらから: from this side.","grammar:765:ex3:points:1":"お願いします: please; thanks in advance.","grammar:765:ex4:trans":"This is my business card.","grammar:765:ex4:structure":"こちらが〜です","grammar:765:ex4:words:0:zh":"this","grammar:765:ex4:words:0:pos":"pronoun","grammar:765:ex4:words:1:zh":"(nominative)","grammar:765:ex4:words:1:pos":"particle","grammar:765:ex4:words:2:zh":"I","grammar:765:ex4:words:2:note":"わたし","grammar:765:ex4:words:2:pos":"pronoun","grammar:765:ex4:words:3:zh":"'s","grammar:765:ex4:words:3:pos":"particle","grammar:765:ex4:words:4:zh":"business card","grammar:765:ex4:words:4:note":"めいし","grammar:765:ex4:words:4:pos":"noun","grammar:765:ex4:words:5:zh":"is","grammar:765:ex4:words:5:pos":"copula","grammar:765:ex4:points:0":"❗こちらが〜: this is ... (used for a formal introduction).","grammar:765:ex4:points:1":"名刺: business card.","grammar:765:ex5:trans":"Please wait here.","grammar:765:ex5:structure":"こちらでお待ちください","grammar:765:ex5:words:0:zh":"here","grammar:765:ex5:words:0:pos":"pronoun","grammar:765:ex5:words:1:zh":"(place)","grammar:765:ex5:words:1:pos":"particle","grammar:765:ex5:words:2:zh":"please wait","grammar:765:ex5:words:2:note":"おまちください","grammar:765:ex5:words:2:pos":"set phrase","grammar:765:ex5:points:0":"❗お待ちください: please wait (お + verb masu-form + ください, respectful).","grammar:765:ex5:points:1":"こちらで: here."},"766":{"example:766:exzh":"I'll read chapter 1.","example:766:exzh2":"This is the second question.","example:766:exzh3":"He came in third place.","example:766:exzh4":"My birthday is in the first week of May.","example:766:exzh5":"I answered the tenth question.","grammar:766:ex:trans":"I'll read chapter 1.","grammar:766:ex:structure":"第〜を読みます","grammar:766:ex:explain":"The key here is the ordinal prefix 「第（だい）」, which attaches to a number to show order; 「第1章」 means chapter 1. 「を」 marks the object, and 「読みます」 is the polite form of 「読む」. The whole sentence means I'll read chapter 1. 「第〜」 is used for formally listing order, as in 「第一に」 (first) and 「第二次」 (the second time); it emphasizes sequence and ranking more than a plain quantity.","grammar:766:ex:words:0:zh":"chapter 1","grammar:766:ex:words:0:note":"だいいっしょう","grammar:766:ex:words:0:pos":"noun","grammar:766:ex:words:1:zh":"(object marker)","grammar:766:ex:words:1:pos":"particle","grammar:766:ex:words:2:zh":"read","grammar:766:ex:words:2:note":"よみます","grammar:766:ex:words:2:pos":"verb","grammar:766:ex:points:0":"❗第（だい）: the ...th (ordinal; 第1章 = chapter 1).","grammar:766:ex:points:1":"読む→読みます。","grammar:766:ex2:trans":"This is the second question.","grammar:766:ex2:structure":"これは第〜の〜です","grammar:766:ex2:words:0:zh":"this","grammar:766:ex2:words:0:pos":"pronoun","grammar:766:ex2:words:1:zh":"(topic)","grammar:766:ex2:words:1:pos":"particle","grammar:766:ex2:words:2:zh":"the second","grammar:766:ex2:words:2:note":"だいに","grammar:766:ex2:words:2:pos":"noun","grammar:766:ex2:words:3:zh":"'s","grammar:766:ex2:words:3:pos":"particle","grammar:766:ex2:words:4:zh":"problem","grammar:766:ex2:words:4:note":"もんだい","grammar:766:ex2:words:4:pos":"noun","grammar:766:ex2:words:5:zh":"is","grammar:766:ex2:words:5:pos":"copula","grammar:766:ex2:points:0":"第2の問題: the second question.","grammar:766:ex2:points:1":"第: ordinal prefix.","grammar:766:ex3:trans":"He came in third place.","grammar:766:ex3:structure":"第〜位に入りました","grammar:766:ex3:words:0:zh":"he","grammar:766:ex3:words:0:note":"かれ","grammar:766:ex3:words:0:pos":"pronoun","grammar:766:ex3:words:1:zh":"(topic)","grammar:766:ex3:words:1:pos":"particle","grammar:766:ex3:words:2:zh":"third place","grammar:766:ex3:words:2:note":"だいさんい","grammar:766:ex3:words:2:pos":"noun","grammar:766:ex3:words:3:zh":"(result)","grammar:766:ex3:words:3:pos":"particle","grammar:766:ex3:words:4:zh":"entered","grammar:766:ex3:words:4:note":"はいりました","grammar:766:ex3:words:4:pos":"verb","grammar:766:ex3:points:0":"❗〜位に入る: to place ...th (in a ranking).","grammar:766:ex3:points:1":"第3位: third place.","grammar:766:ex4:trans":"My birthday is in the first week of May.","grammar:766:ex4:structure":"〜は、〜月の第〜週です","grammar:766:ex4:explain":"The first 「の」 in 「私の誕生日」 shows possession, meaning my birthday. 「は」 brings the birthday up as the topic. 「五月の第1週」 uses the second 「の」 to narrow it down to the first week within May. 「第」 is a prefix showing order and 「週」 is the unit; in this combination 「1週」 is read 「いっしゅう」, so 「第1週」 is read 「だいいっしゅう」. The final 「です」 simply states the time range the birthday falls in.","grammar:766:ex4:words:0:zh":"I","grammar:766:ex4:words:0:note":"わたし","grammar:766:ex4:words:0:pos":"pronoun","grammar:766:ex4:words:1:zh":"(possession)","grammar:766:ex4:words:1:pos":"particle","grammar:766:ex4:words:2:zh":"birthday","grammar:766:ex4:words:2:note":"たんじょうび","grammar:766:ex4:words:2:pos":"noun","grammar:766:ex4:words:3:zh":"(topic)","grammar:766:ex4:words:3:pos":"particle","grammar:766:ex4:words:4:zh":"May","grammar:766:ex4:words:4:note":"ごがつ","grammar:766:ex4:words:4:pos":"noun","grammar:766:ex4:words:5:zh":"(the time range it falls in)","grammar:766:ex4:words:5:pos":"particle","grammar:766:ex4:words:6:zh":"the first week","grammar:766:ex4:words:6:note":"だいいっしゅう","grammar:766:ex4:words:6:pos":"noun","grammar:766:ex4:words:7:zh":"is, falls in (polite copula ending)","grammar:766:ex4:words:7:pos":"auxiliary verb","grammar:766:ex4:points:0":"「第」 plus a number shows order; 「第1週」 is read 「だいいっしゅう」.","grammar:766:ex4:points:1":"「五月」 means the month of May and is read 「ごがつ」.","grammar:766:ex4:points:2":"「Aは時間です」 can state the time of an event directly; you don't always need to add 「に」.","grammar:766:ex5:trans":"I answered the tenth question.","grammar:766:ex5:structure":"第〜に答えました","grammar:766:ex5:words:0:zh":"the tenth","grammar:766:ex5:words:0:note":"だいじゅう","grammar:766:ex5:words:0:pos":"noun","grammar:766:ex5:words:1:zh":"'s","grammar:766:ex5:words:1:pos":"particle","grammar:766:ex5:words:2:zh":"problem","grammar:766:ex5:words:2:note":"しつもん","grammar:766:ex5:words:2:pos":"noun","grammar:766:ex5:words:3:zh":"(object)","grammar:766:ex5:words:3:pos":"particle","grammar:766:ex5:words:4:zh":"(contrast)","grammar:766:ex5:words:4:pos":"particle","grammar:766:ex5:words:5:zh":"answered","grammar:766:ex5:words:5:note":"こたえました","grammar:766:ex5:words:5:pos":"verb","grammar:766:ex5:points:0":"第10の質問: the tenth question.","grammar:766:ex5:points:1":"❗〜に答える: to answer ... (the target takes に)."},"767":{"example:767:exzh":"I expressed my gratitude to him.","example:767:exzh2":"I wrote a thank-you letter.","example:767:exzh3":"I'm grateful to everyone.","example:767:exzh4":"I would like to express my gratitude.","example:767:exzh5":"Don't forget to say thank you."},"768":{"example:768:exzh":"Please open the door.","example:768:exzh2":"The door is closed.","example:768:exzh3":"This door isn't very heavy.","example:768:exzh4":"There's someone outside the door.","example:768:exzh5":"He knocked on the door.","grammar:768:ex:trans":"Please open the door.","grammar:768:ex:structure":"〜を開けてください","grammar:768:ex:explain":"The key here is the transitive verb 「開ける」 (to open); the object is marked with 「を」, and 「ドアを開ける」 means to open the door, stressing that someone opens it. Its intransitive counterpart is 「開く」 (the door opens by itself). 「開けて」 is the te-form plus 「ください」 to make a request. The whole sentence means please open the door. Transitive/intransitive pairs (ドアを開ける / ドアが開く) come up often on exams, so be clear about whether someone is doing the action.","grammar:768:ex:words:0:zh":"door","grammar:768:ex:words:0:note":"loanword","grammar:768:ex:words:0:pos":"noun","grammar:768:ex:words:1:zh":"(object marker)","grammar:768:ex:words:1:pos":"particle","grammar:768:ex:words:2:zh":"open","grammar:768:ex:words:2:note":"あけて","grammar:768:ex:words:2:pos":"verb","grammar:768:ex:words:3:zh":"please","grammar:768:ex:words:3:pos":"auxiliary verb","grammar:768:ex:points:0":"❗開ける (transitive verb, to open the door); ドアを開ける: to open the door.","grammar:768:ex:points:1":"開ける→開けて＋ください。","grammar:768:ex2:trans":"The door is closed.","grammar:768:ex2:structure":"〜が閉まっている","grammar:768:ex2:words:0:zh":"door","grammar:768:ex2:words:0:note":"loanword","grammar:768:ex2:words:0:pos":"noun","grammar:768:ex2:words:1:zh":"(nominative)","grammar:768:ex2:words:1:pos":"particle","grammar:768:ex2:words:2:zh":"is closed","grammar:768:ex2:words:2:note":"しまっている","grammar:768:ex2:words:2:pos":"verb","grammar:768:ex2:points:0":"❗閉まる (intransitive verb, the door closes by itself) ≠ 閉める (transitive verb, to close the door).","grammar:768:ex2:points:1":"〜ている: the state (of being closed).","grammar:768:ex3:trans":"This door isn't very heavy.","grammar:768:ex3:structure":"〜はあまり〜くないです","grammar:768:ex3:explain":"「このドアは」 brings the door up as the topic. 「重い」 becomes 「重くない」 to show it isn't heavy, and with 「あまり」 added the meaning is not very heavy—not that it has no weight at all. Adding 「です」 after the negative form makes the whole sentence polite.","grammar:768:ex3:words:0:zh":"this","grammar:768:ex3:words:0:pos":"pre-noun adjectival","grammar:768:ex3:words:1:zh":"door","grammar:768:ex3:words:1:pos":"noun","grammar:768:ex3:words:2:zh":"(topic)","grammar:768:ex3:words:2:pos":"particle","grammar:768:ex3:words:3:zh":"(with a negative it means not very)","grammar:768:ex3:words:3:pos":"adverb","grammar:768:ex3:words:4:zh":"heavy","grammar:768:ex3:words:4:note":"おもく","grammar:768:ex3:words:4:pos":"i-adjective","grammar:768:ex3:words:5:zh":"(negative)","grammar:768:ex3:words:5:pos":"i-adjective","grammar:768:ex3:words:6:zh":"(polite tone)","grammar:768:ex3:words:6:pos":"auxiliary verb","grammar:768:ex3:points:0":"「あまり＋否定」 shows a low degree; it's usually translated as not very.","grammar:768:ex3:points:1":"The negative form of an i-adjective changes the final 「い」 to 「くない」, e.g. 「重い→重くない」.","grammar:768:ex4:trans":"There's someone outside the door.","grammar:768:ex4:structure":"〜に〜がいます","grammar:768:ex4:words:0:zh":"door","grammar:768:ex4:words:0:note":"loanword","grammar:768:ex4:words:0:pos":"noun","grammar:768:ex4:words:1:zh":"'s","grammar:768:ex4:words:1:pos":"particle","grammar:768:ex4:words:2:zh":"outside","grammar:768:ex4:words:2:note":"そと","grammar:768:ex4:words:2:pos":"noun","grammar:768:ex4:words:3:zh":"(location of existence)","grammar:768:ex4:words:3:pos":"particle","grammar:768:ex4:words:4:zh":"person","grammar:768:ex4:words:4:note":"ひと","grammar:768:ex4:words:4:pos":"noun","grammar:768:ex4:words:5:zh":"(nominative)","grammar:768:ex4:words:5:pos":"particle","grammar:768:ex4:words:6:zh":"there is / are","grammar:768:ex4:words:6:pos":"verb","grammar:768:ex4:points:0":"ドアの外: outside the door.","grammar:768:ex4:points:1":"〜に〜がいる: there is (a person) in/at ...","grammar:768:ex5:trans":"He knocked on the door.","grammar:768:ex5:structure":"〜をノックしました","grammar:768:ex5:words:0:zh":"he","grammar:768:ex5:words:0:note":"かれ","grammar:768:ex5:words:0:pos":"pronoun","grammar:768:ex5:words:1:zh":"(topic)","grammar:768:ex5:words:1:pos":"particle","grammar:768:ex5:words:2:zh":"door","grammar:768:ex5:words:2:note":"loanword","grammar:768:ex5:words:2:pos":"noun","grammar:768:ex5:words:3:zh":"(object marker)","grammar:768:ex5:words:3:pos":"particle","grammar:768:ex5:words:4:zh":"knocked","grammar:768:ex5:words:4:pos":"verb","grammar:768:ex5:points:0":"ノックする: to knock (on a door).","grammar:768:ex5:points:1":"ドアをノックする: to knock on the door.","exam:768:zh":"When you enter this room, please open the door.","exam:768:why":"What you open to enter the room is the 「ドア」. A 「机」 may have drawers, but you can't use 「机を開ける」 to mean opening a door to go into a room."},"769":{"example:769:exzh":"Please show me the evidence.","example:769:exzh2":"He is gathering evidence.","example:769:exzh3":"This evidence is important.","example:769:exzh4":"There isn't enough evidence.","example:769:exzh5":"The court reviewed the evidence."},"771":{"example:771:exzh":"I hope for your success.","example:771:exzh2":"He hopes for peace.","example:771:exzh3":"I hope everyone stays healthy.","example:771:exzh4":"I hope to make my dream come true.","example:771:exzh5":"I'm hoping for a good result."},"772":{"example:772:exzh":"I understand how you feel.","example:772:exzh2":"Understanding this problem is difficult.","example:772:exzh3":"He understood the situation right away.","example:772:exzh4":"I'll study in order to deepen my understanding.","example:772:exzh5":"I want other people to understand too."},"773":{"example:773:exzh":"May I ask a question during class?","example:773:exzh2":"I answered his question.","example:773:exzh3":"If you have any questions, please ask anytime.","example:773:exzh4":"This question is very difficult.","example:773:exzh5":"After I asked the teacher, my understanding deepened.","grammar:773:ex:trans":"May I ask a question during class?","grammar:773:ex:structure":"〜てもいいですか","grammar:773:ex:explain":"The key here is the permission pattern 「〜てもいいですか」 (may I ...?). The verb's te-form plus 「もいいですか」 asks for permission, so 「質問してもいい」 means may I ask a question. 「授業中に」 uses 「に」 to mark the point in time. The whole sentence means may I ask a question during class? To give permission, answer 「いいですよ」; to refuse, 「〜てはいけません」 is common, or the softer 「ちょっと…」.","grammar:773:ex:words:0:zh":"during class","grammar:773:ex:words:0:note":"じゅぎょうちゅう","grammar:773:ex:words:0:pos":"noun","grammar:773:ex:words:1:zh":"(point in time)","grammar:773:ex:words:1:pos":"particle","grammar:773:ex:words:2:zh":"ask a question","grammar:773:ex:words:2:note":"しつもんして","grammar:773:ex:words:2:pos":"verb","grammar:773:ex:words:3:zh":"(also)","grammar:773:ex:words:3:pos":"particle","grammar:773:ex:words:4:zh":"good","grammar:773:ex:words:4:pos":"adjective","grammar:773:ex:words:5:zh":"is","grammar:773:ex:words:5:pos":"copula","grammar:773:ex:words:6:zh":"(question)","grammar:773:ex:words:6:pos":"particle","grammar:773:ex:points:0":"❗〜てもいいですか: may I …? (permission).","grammar:773:ex:points:1":"質問する: to ask a question.","grammar:773:ex2:trans":"I answered his question.","grammar:773:ex2:structure":"〜に答えました","grammar:773:ex2:words:0:zh":"he","grammar:773:ex2:words:0:note":"かれ","grammar:773:ex2:words:0:pos":"pronoun","grammar:773:ex2:words:1:zh":"'s","grammar:773:ex2:words:1:pos":"particle","grammar:773:ex2:words:2:zh":"problem","grammar:773:ex2:words:2:note":"しつもん","grammar:773:ex2:words:2:pos":"noun","grammar:773:ex2:words:3:zh":"(object)","grammar:773:ex2:words:3:pos":"particle","grammar:773:ex2:words:4:zh":"answered","grammar:773:ex2:words:4:note":"こたえました","grammar:773:ex2:words:4:pos":"verb","grammar:773:ex2:points:0":"❗〜に答える: to answer ... (the target takes に).","grammar:773:ex2:points:1":"彼の質問: his question.","grammar:773:ex3:trans":"If you have any questions, feel free to ask anytime.","grammar:773:ex3:structure":"〜ば、いつでも〜てください","grammar:773:ex3:words:0:zh":"problem","grammar:773:ex3:words:0:note":"しつもん","grammar:773:ex3:words:0:pos":"noun","grammar:773:ex3:words:1:zh":"(nominative)","grammar:773:ex3:words:1:pos":"particle","grammar:773:ex3:words:2:zh":"if there is","grammar:773:ex3:words:2:pos":"verb","grammar:773:ex3:words:3:zh":"anytime","grammar:773:ex3:words:3:pos":"adverb","grammar:773:ex3:words:4:zh":"ask","grammar:773:ex3:words:4:note":"きいて","grammar:773:ex3:words:4:pos":"verb","grammar:773:ex3:words:5:zh":"please","grammar:773:ex3:words:5:pos":"auxiliary verb","grammar:773:ex3:points:0":"〜ば: if ...; いつでも: anytime.","grammar:773:ex3:points:1":"聞く: to ask.","grammar:773:ex4:trans":"This question is very difficult.","grammar:773:ex4:structure":"〜はとても〜です","grammar:773:ex4:words:0:zh":"this","grammar:773:ex4:words:0:pos":"pre-noun adjectival","grammar:773:ex4:words:1:zh":"problem","grammar:773:ex4:words:1:note":"しつもん","grammar:773:ex4:words:1:pos":"noun","grammar:773:ex4:words:2:zh":"(topic)","grammar:773:ex4:words:2:pos":"particle","grammar:773:ex4:words:3:zh":"extremely","grammar:773:ex4:words:3:pos":"adverb","grammar:773:ex4:words:4:zh":"difficult","grammar:773:ex4:words:4:note":"むずかしい","grammar:773:ex4:words:4:pos":"adjective","grammar:773:ex4:words:5:zh":"(polite form)","grammar:773:ex4:words:5:pos":"copula","grammar:773:ex4:points:0":"この質問: this question.","grammar:773:ex4:points:1":"難しい: difficult.","grammar:773:ex5:trans":"After I asked the teacher, my understanding deepened.","grammar:773:ex5:structure":"〜た後、〜ました","grammar:773:ex5:words:0:zh":"teacher","grammar:773:ex5:words:0:note":"せんせい","grammar:773:ex5:words:0:pos":"noun","grammar:773:ex5:words:1:zh":"(object)","grammar:773:ex5:words:1:pos":"particle","grammar:773:ex5:words:2:zh":"problem","grammar:773:ex5:words:2:note":"しつもん","grammar:773:ex5:words:2:pos":"noun","grammar:773:ex5:words:3:zh":"(object marker)","grammar:773:ex5:words:3:pos":"particle","grammar:773:ex5:words:4:zh":"did","grammar:773:ex5:words:4:pos":"verb","grammar:773:ex5:words:5:zh":"later, afterwards","grammar:773:ex5:words:5:note":"あと","grammar:773:ex5:words:5:pos":"noun","grammar:773:ex5:words:6:zh":"understanding","grammar:773:ex5:words:6:note":"りかい","grammar:773:ex5:words:6:pos":"noun","grammar:773:ex5:words:7:zh":"(nominative)","grammar:773:ex5:words:7:pos":"particle","grammar:773:ex5:words:8:zh":"deepened","grammar:773:ex5:words:8:note":"ふかまりました","grammar:773:ex5:words:8:pos":"verb","grammar:773:ex5:points:0":"❗〜た後: after ...","grammar:773:ex5:points:1":"深まる: to deepen (intransitive); 理解が深まる: one's understanding deepens."},"774":{"example:774:exzh":"If it rains, I'll stay home.","example:774:exzh2":"If I have time, I'd like to go out and have fun.","example:774:exzh3":"If I can go, I'll join the party.","example:774:exzh4":"Call me when you get to the station.","example:774:exzh5":"Once we've eaten, let's go for a walk.","grammar:774:ex:trans":"If it rains, I'll stay home.","grammar:774:ex:structure":"〜たら、〜","grammar:774:ex:explain":"This is the hypothetical/time pattern 「〜たら」 (if ...; after ...). The verb's ta-form plus 「ら」 gives 「降ったら」, meaning if it rains. 「たら」 can express both a hypothesis (if) and a time sequence (after), and here it's a hypothesis. The whole sentence means if it rains, I'll stay home. 「たら」 is the most casual and versatile conditional; it differs in nuance from ば, と, and なら.","grammar:774:ex:words:0:zh":"rain","grammar:774:ex:words:0:note":"あめ","grammar:774:ex:words:0:pos":"noun","grammar:774:ex:words:1:zh":"(nominative)","grammar:774:ex:words:1:pos":"particle","grammar:774:ex:words:2:zh":"if it rains","grammar:774:ex:words:2:note":"ふったら","grammar:774:ex:words:2:pos":"verb","grammar:774:ex:words:3:zh":"house","grammar:774:ex:words:3:note":"いえ","grammar:774:ex:words:3:pos":"noun","grammar:774:ex:words:4:zh":"(location of existence)","grammar:774:ex:words:4:pos":"particle","grammar:774:ex:words:5:zh":"exist","grammar:774:ex:words:5:pos":"verb","grammar:774:ex:points:0":"❗〜たら: if ...; after ... (hypothetical/time, verb ta-form + ら).","grammar:774:ex:points:1":"雨が降ったら: if it rains.","grammar:774:ex2:trans":"If I have time, I want to go out and have some fun.","grammar:774:ex2:structure":"〜たら、〜たいです","grammar:774:ex2:words:0:zh":"time","grammar:774:ex2:words:0:note":"じかん","grammar:774:ex2:words:0:pos":"noun","grammar:774:ex2:words:1:zh":"(nominative)","grammar:774:ex2:words:1:pos":"particle","grammar:774:ex2:words:2:zh":"if there is","grammar:774:ex2:words:2:pos":"verb","grammar:774:ex2:words:3:zh":"hang out","grammar:774:ex2:words:3:note":"あそび","grammar:774:ex2:words:3:pos":"noun","grammar:774:ex2:words:4:zh":"(purpose)","grammar:774:ex2:words:4:pos":"particle","grammar:774:ex2:words:5:zh":"want to go","grammar:774:ex2:words:5:note":"いきたい","grammar:774:ex2:words:5:pos":"verb","grammar:774:ex2:words:6:zh":"(polite form)","grammar:774:ex2:words:6:pos":"copula","grammar:774:ex2:points:0":"時間があったら: if I have time.","grammar:774:ex2:points:1":"遊びに行きたい: I want to go out and have fun.","grammar:774:ex3:trans":"If I can go, I'll join the party.","grammar:774:ex3:structure":"〜たら、〜します","grammar:774:ex3:words:0:zh":"if I can go","grammar:774:ex3:words:0:note":"いけたら","grammar:774:ex3:words:0:pos":"verb","grammar:774:ex3:words:1:zh":"party","grammar:774:ex3:words:1:note":"loanword","grammar:774:ex3:words:1:pos":"noun","grammar:774:ex3:words:2:zh":"(object)","grammar:774:ex3:words:2:pos":"particle","grammar:774:ex3:words:3:zh":"join","grammar:774:ex3:words:3:note":"さんかします","grammar:774:ex3:words:3:pos":"verb","grammar:774:ex3:points:0":"行けたら: if I can go (行ける, potential form + たら).","grammar:774:ex3:points:1":"〜に参加する: to take part in…","grammar:774:ex4:trans":"Please call me once you get to the station.","grammar:774:ex4:structure":"場所に＋verbたら、action＋してください","grammar:774:ex4:words:0:zh":"station","grammar:774:ex4:words:0:note":"えき; station","grammar:774:ex4:words:0:pos":"noun","grammar:774:ex4:words:1:zh":"to; at","grammar:774:ex4:words:1:pos":"particle","grammar:774:ex4:words:2:zh":"when you arrive; after arriving","grammar:774:ex4:words:2:note":"ついたら; the たら form of 着く","grammar:774:ex4:words:2:pos":"verb","grammar:774:ex4:words:3:zh":"phone call","grammar:774:ex4:words:3:note":"でんわ; 電話","grammar:774:ex4:words:3:pos":"noun","grammar:774:ex4:words:4:zh":"do; make","grammar:774:ex4:words:4:pos":"verb","grammar:774:ex4:words:5:zh":"please","grammar:774:ex4:words:5:pos":"auxiliary verb","grammar:774:ex4:points:0":"「着いたら」 uses たら to show a condition or a point in time; here it means after arriving.","grammar:774:ex4:points:1":"「電話してください」 is a polite way to ask someone to do something.","grammar:774:ex5:trans":"Once we've eaten, let's go for a walk.","grammar:774:ex5:structure":"〜たら、〜行こう","grammar:774:ex5:words:0:zh":"once (we've) eaten","grammar:774:ex5:words:0:note":"たべたら","grammar:774:ex5:words:0:pos":"verb","grammar:774:ex5:words:1:zh":"take a walk","grammar:774:ex5:words:1:note":"さんぽ","grammar:774:ex5:words:1:pos":"noun","grammar:774:ex5:words:2:zh":"(purpose)","grammar:774:ex5:words:2:pos":"particle","grammar:774:ex5:words:3:zh":"let's go","grammar:774:ex5:words:3:note":"いこう","grammar:774:ex5:words:3:pos":"verb","grammar:774:ex5:points:0":"食べたら: after eating, if (we've) eaten.","grammar:774:ex5:points:1":"散歩に行こう: let's go for a walk (volitional form)."},"775":{"example:775:exzh":"I'm anxious about it.","example:775:exzh2":"He's complaining.","example:775:exzh3":"This is inaccurate information.","example:775:exzh4":"She looks unhappy.","example:775:exzh5":"You're having an unlucky day."},"776":{"example:776:exzh":"What he says is certain.","example:776:exzh2":"That is certainly an important issue.","example:776:exzh3":"I'm fairly sure I've read this book before.","example:776:exzh4":"If I remember right, there's a meeting tomorrow, right?","example:776:exzh5":"She has a definite image in mind."},"777":{"example:777:exzh":"That movie is really scary.","example:777:exzh2":"I'm scared of dark places.","example:777:exzh3":"He finds horror movies scary, so he doesn't watch them.","example:777:exzh4":"I had a scary dream.","example:777:exzh5":"I was so scared that I ran away.","grammar:777:ex:trans":"That movie is really scary.","grammar:777:ex:structure":"〜はとても怖いです","grammar:777:ex:explain":"This is an evaluative sentence built on 「〜はとても怖いです」. 「怖い」 (scary, frightening) is an i-adjective in the predicate, 「とても」 modifies the degree, and 「は」 marks 「あの映画」 as the topic. The whole sentence means “That movie is really scary.” 「怖い」 is read 「こわい」 and expresses a subjective feeling of fear; don't confuse it with other words that mean “worrying.” It is a common adjective for describing horror films and things that give you a fright.","grammar:777:ex:words:0:zh":"that","grammar:777:ex:words:0:pos":"pre-noun adjectival","grammar:777:ex:words:1:zh":"movie","grammar:777:ex:words:1:note":"えいが","grammar:777:ex:words:1:pos":"noun","grammar:777:ex:words:2:zh":"(topic)","grammar:777:ex:words:2:pos":"particle","grammar:777:ex:words:3:zh":"extremely","grammar:777:ex:words:3:pos":"adverb","grammar:777:ex:words:4:zh":"scary","grammar:777:ex:words:4:note":"こわい","grammar:777:ex:words:4:pos":"adjective","grammar:777:ex:words:5:zh":"(polite form)","grammar:777:ex:words:5:pos":"copula","grammar:777:ex:points:0":"❗怖い（こわい）: scary, frightening.","grammar:777:ex:points:1":"とても怖い: very scary.","grammar:777:ex2:trans":"I'm scared of dark places.","grammar:777:ex2:structure":"〜が怖いです","grammar:777:ex2:words:0:zh":"dark","grammar:777:ex2:words:0:note":"くらい","grammar:777:ex2:words:0:pos":"adjective","grammar:777:ex2:words:1:zh":"place","grammar:777:ex2:words:1:note":"ばしょ","grammar:777:ex2:words:1:pos":"noun","grammar:777:ex2:words:2:zh":"(object)","grammar:777:ex2:words:2:pos":"particle","grammar:777:ex2:words:3:zh":"fear","grammar:777:ex2:words:3:note":"こわい","grammar:777:ex2:words:3:pos":"adjective","grammar:777:ex2:words:4:zh":"(polite form)","grammar:777:ex2:words:4:pos":"copula","grammar:777:ex2:points:0":"❗〜が怖い: to be scared of … (the thing you fear takes が).","grammar:777:ex2:points:1":"暗い場所: a dark place.","grammar:777:ex3:trans":"He finds horror movies scary, so he doesn't watch them.","grammar:777:ex3:structure":"人は〜が怖いので、〜ません","grammar:777:ex3:explain":"「彼は」 presents the person experiencing the feeling as the topic. 「ホラー映画」 means horror movie, and 「が」 marks what he finds scary and is afraid of. 「怖いので」 uses 「ので」 to give the reason he doesn't watch, and an i-adjective can be followed by 「ので」 directly. 「見る」 drops 「る」 and takes 「ません」, becoming 「見ません」. The second half omits both the subject 「彼」 and the object 「ホラー映画」, and both are clear from the first half.","grammar:777:ex3:words:0:zh":"he","grammar:777:ex3:words:0:note":"かれ","grammar:777:ex3:words:0:pos":"pronoun","grammar:777:ex3:words:1:zh":"(topic)","grammar:777:ex3:words:1:pos":"particle","grammar:777:ex3:words:2:zh":"horror genre","grammar:777:ex3:words:2:pos":"noun","grammar:777:ex3:words:3:zh":"movie","grammar:777:ex3:words:3:note":"えいが","grammar:777:ex3:words:3:pos":"noun","grammar:777:ex3:words:4:zh":"(the object of the fear)","grammar:777:ex3:words:4:pos":"particle","grammar:777:ex3:words:5:zh":"scary, frightening","grammar:777:ex3:words:5:note":"こわい","grammar:777:ex3:words:5:pos":"i-adjective","grammar:777:ex3:words:6:zh":"(reason, cause)","grammar:777:ex3:words:6:pos":"particle","grammar:777:ex3:words:7:zh":"look","grammar:777:ex3:words:7:note":"み","grammar:777:ex3:words:7:pos":"verb","grammar:777:ex3:words:8:zh":"(negative connecting form of the polite ending)","grammar:777:ex3:words:8:pos":"auxiliary verb","grammar:777:ex3:words:9:zh":"(negative)","grammar:777:ex3:words:9:pos":"auxiliary verb","grammar:777:ex3:points:0":"「人は〜が怖い」 means someone is afraid of something, and 「が」 marks the thing feared.","grammar:777:ex3:points:1":"「i-adjective＋ので」 expresses a reason; the i-adjective attaches to 「ので」 directly, with no 「な」.","grammar:777:ex3:points:2":"「見ません」 is the polite negative form of 「見る」.","grammar:777:ex4:trans":"I had a scary dream.","grammar:777:ex4:structure":"〜を見ました","grammar:777:ex4:words:0:zh":"scary","grammar:777:ex4:words:0:note":"こわい","grammar:777:ex4:words:0:pos":"adjective","grammar:777:ex4:words:1:zh":"dream","grammar:777:ex4:words:1:note":"ゆめ","grammar:777:ex4:words:1:pos":"noun","grammar:777:ex4:words:2:zh":"(object marker)","grammar:777:ex4:words:2:pos":"particle","grammar:777:ex4:words:3:zh":"to have (a dream)","grammar:777:ex4:words:3:note":"みました","grammar:777:ex4:words:3:pos":"verb","grammar:777:ex4:points:0":"❗夢を見る: to have a dream (fixed expression).","grammar:777:ex4:points:1":"怖い夢: a scary dream (nightmare).","grammar:777:ex5:trans":"It was so scary that I ran away.","grammar:777:ex5:structure":"〜が〜くて、〜ました","grammar:777:ex5:words:0:zh":"that","grammar:777:ex5:words:0:pos":"pronoun","grammar:777:ex5:words:1:zh":"(nominative)","grammar:777:ex5:words:1:pos":"particle","grammar:777:ex5:words:2:zh":"scary","grammar:777:ex5:words:2:note":"こわくて","grammar:777:ex5:words:2:pos":"adjective","grammar:777:ex5:words:3:zh":"ran away","grammar:777:ex5:words:3:note":"にげました","grammar:777:ex5:words:3:pos":"verb","grammar:777:ex5:points:0":"❗〜くて: because … (the adjective te-form shows cause and effect).","grammar:777:ex5:points:1":"逃げる: to run away."},"778":{"example:778:exzh":"Ah, I'm tired.","example:778:exzh2":"Ah, that's right.","example:778:exzh3":"Ah, what a lovely view.","example:778:exzh4":"Ah, I'm so happy!","example:778:exzh5":"Ah, I forgot.","grammar:778:ex:trans":"Ah, I'm tired.","grammar:778:ex:structure":"あぁ、〜なぁ","grammar:778:ex:explain":"The key word here is the interjection 「あぁ」, the ah that slips out when you realize something, feel moved, or are worn out. The sentence-final 「なぁ」 is a monologue-style exclamatory particle that gives a talking-to-yourself, letting-your-feelings-out tone. 「疲れた」 is the past form of 「疲れる」, meaning I'm tired. The whole sentence means Ah, I'm tired. Putting 「〜なぁ」 at the end softens the tone and lets your mood show — a very everyday expression.","grammar:778:ex:words:0:zh":"Ah","grammar:778:ex:words:0:pos":"interjection","grammar:778:ex:words:1:zh":"tired","grammar:778:ex:words:1:note":"つかれた","grammar:778:ex:words:1:pos":"verb","grammar:778:ex:words:2:zh":"(exclamation)","grammar:778:ex:words:2:pos":"particle","grammar:778:ex:points:0":"❗あぁ: ah (interjection of emotion or realization).","grammar:778:ex:points:1":"なぁ: (monologue-style) exclamation.","grammar:778:ex2:trans":"Ah, that's right.","grammar:778:ex2:structure":"あぁ、そうだった","grammar:778:ex2:words:0:zh":"Ah","grammar:778:ex2:words:0:pos":"interjection","grammar:778:ex2:words:1:zh":"that way","grammar:778:ex2:words:1:pos":"adverb","grammar:778:ex2:words:2:zh":"(past) was","grammar:778:ex2:words:2:pos":"copula","grammar:778:ex2:points:0":"❗あぁ、そうだった: ah, that's right (remembering).","grammar:778:ex2:points:1":"そうだった: so that's how it was.","grammar:778:ex3:trans":"Ah, what a beautiful view.","grammar:778:ex3:structure":"あぁ、〜ですね","grammar:778:ex3:words:0:zh":"Ah","grammar:778:ex3:words:0:pos":"interjection","grammar:778:ex3:words:1:zh":"wonderful","grammar:778:ex3:words:1:note":"すてき","grammar:778:ex3:words:1:pos":"na-adjective","grammar:778:ex3:words:2:zh":"(attributive form)","grammar:778:ex3:words:2:pos":"auxiliary verb","grammar:778:ex3:words:3:zh":"scenery","grammar:778:ex3:words:3:note":"けしき","grammar:778:ex3:words:3:pos":"noun","grammar:778:ex3:words:4:zh":"(polite form)","grammar:778:ex3:words:4:pos":"copula","grammar:778:ex3:words:5:zh":"right?","grammar:778:ex3:words:5:pos":"particle","grammar:778:ex3:points:0":"素敵な景色: a beautiful view.","grammar:778:ex3:points:1":"ね: seeking agreement.","grammar:778:ex4:trans":"Ah, I'm so happy!","grammar:778:ex4:structure":"あぁ、〜！","grammar:778:ex4:words:0:zh":"Ah","grammar:778:ex4:words:0:pos":"interjection","grammar:778:ex4:words:1:zh":"happy","grammar:778:ex4:words:1:note":"うれしい","grammar:778:ex4:words:1:pos":"adjective","grammar:778:ex4:points:0":"あぁ: ah (of joy).","grammar:778:ex4:points:1":"嬉しい: happy, glad.","grammar:778:ex5:trans":"Ah, I forgot.","grammar:778:ex5:structure":"あぁ、〜てた","grammar:778:ex5:words:0:zh":"Ah","grammar:778:ex5:words:0:pos":"interjection","grammar:778:ex5:words:1:zh":"Forgot","grammar:778:ex5:words:1:note":"わすれてた","grammar:778:ex5:words:1:pos":"verb","grammar:778:ex5:points:0":"❗忘れてた: forgot (casual contraction of 忘れていた).","grammar:778:ex5:points:1":"あぁ: ah (of dismay).","exam:778:zh":"Because I remembered an appointment I had forgotten, I said, 「Ah, that's right.」","exam:778:why":"「あぁ」 can show that something suddenly came back to you or that you understood something. 「さようなら」 is a farewell, so it doesn't fit a reaction to remembering an appointment."},"779":{"example:779:exzh":"I don't want to be apart from my family.","example:779:exzh2":"He left the school.","example:779:exzh3":"Please move away a little.","example:779:exzh4":"I live in a place far away.","example:779:exzh5":"She's waiting some distance away."},"780":{"example:780:exzh":"Which book do you like?","example:780:exzh2":"Which station do you get off at?","example:780:exzh3":"Which food do you like best?","example:780:exzh4":"Which road do you take?","example:780:exzh5":"Which movie is interesting?","grammar:780:ex:trans":"Which book do you like?","grammar:780:ex:structure":"どの〜が好きですか","grammar:780:ex:explain":"The point here is the pre-noun adjectival 「どの」 (which …), which attaches directly to a noun to pick one out of several — 「どの本」 means which book. It's the question word of the こそあど series (この・その・あの・どの). The object of liking, 「本」, is marked with 「が」. The whole sentence means Which book do you like? 「どの」 must always be followed by a noun; to say which one on its own, use 「どれ」.","grammar:780:ex:words:0:zh":"which","grammar:780:ex:words:0:pos":"pre-noun adjectival","grammar:780:ex:words:1:zh":"book","grammar:780:ex:words:1:note":"ほん","grammar:780:ex:words:1:pos":"noun","grammar:780:ex:words:2:zh":"(object)","grammar:780:ex:words:2:pos":"particle","grammar:780:ex:words:3:zh":"to like","grammar:780:ex:words:3:note":"すき","grammar:780:ex:words:3:pos":"na-adjective","grammar:780:ex:words:4:zh":"(polite form)","grammar:780:ex:words:4:pos":"copula","grammar:780:ex:words:5:zh":"(question)","grammar:780:ex:words:5:pos":"particle","grammar:780:ex:points:0":"❗どの + noun: which … (pre-noun adjectival, こそあど series).","grammar:780:ex:points:1":"どの本: which book.","grammar:780:ex2:trans":"Which station do you get off at?","grammar:780:ex2:structure":"どの〜で〜のですか","grammar:780:ex2:words:0:zh":"which","grammar:780:ex2:words:0:pos":"pre-noun adjectival","grammar:780:ex2:words:1:zh":"station","grammar:780:ex2:words:1:note":"えき","grammar:780:ex2:words:1:pos":"noun","grammar:780:ex2:words:2:zh":"(place of the action)","grammar:780:ex2:words:2:pos":"particle","grammar:780:ex2:words:3:zh":"Get off","grammar:780:ex2:words:3:note":"おりる","grammar:780:ex2:words:3:pos":"verb","grammar:780:ex2:words:4:zh":"(explanation)","grammar:780:ex2:words:4:pos":"particle","grammar:780:ex2:words:5:zh":"(polite form)","grammar:780:ex2:words:5:pos":"copula","grammar:780:ex2:words:6:zh":"(question)","grammar:780:ex2:words:6:pos":"particle","grammar:780:ex2:points:0":"どの駅で: at which station.","grammar:780:ex2:points:1":"降りる: to get off.","grammar:780:ex3:trans":"Which kind of food do you like best?","grammar:780:ex3:structure":"どの〜が一番好きですか","grammar:780:ex3:words:0:zh":"which","grammar:780:ex3:words:0:pos":"pre-noun adjectival","grammar:780:ex3:words:1:zh":"food","grammar:780:ex3:words:1:note":"たべもの","grammar:780:ex3:words:1:pos":"noun","grammar:780:ex3:words:2:zh":"(object)","grammar:780:ex3:words:2:pos":"particle","grammar:780:ex3:words:3:zh":"the most","grammar:780:ex3:words:3:note":"いちばん","grammar:780:ex3:words:3:pos":"adverb","grammar:780:ex3:words:4:zh":"to like","grammar:780:ex3:words:4:note":"すき","grammar:780:ex3:words:4:pos":"na-adjective","grammar:780:ex3:words:5:zh":"(polite form)","grammar:780:ex3:words:5:pos":"copula","grammar:780:ex3:words:6:zh":"(question)","grammar:780:ex3:words:6:pos":"particle","grammar:780:ex3:points:0":"どの〜が一番好き: which … do you like best.","grammar:780:ex3:points:1":"一番: most.","grammar:780:ex4:trans":"Which road will you take?","grammar:780:ex4:structure":"どの〜を通りますか","grammar:780:ex4:words:0:zh":"which","grammar:780:ex4:words:0:pos":"pre-noun adjectival","grammar:780:ex4:words:1:zh":"road","grammar:780:ex4:words:1:note":"みち","grammar:780:ex4:words:1:pos":"noun","grammar:780:ex4:words:2:zh":"(path)","grammar:780:ex4:words:2:pos":"particle","grammar:780:ex4:words:3:zh":"pass (of time)","grammar:780:ex4:words:3:note":"とおります","grammar:780:ex4:words:3:pos":"verb","grammar:780:ex4:words:4:zh":"(question)","grammar:780:ex4:words:4:pos":"particle","grammar:780:ex4:points:0":"❓道を通る: to go along / pass through (a road) (the route is marked with を).","grammar:780:ex4:points:1":"どの道: which road.","grammar:780:ex5:trans":"Which movie is interesting?","grammar:780:ex5:structure":"どの〜が面白いですか","grammar:780:ex5:words:0:zh":"which","grammar:780:ex5:words:0:pos":"pre-noun adjectival","grammar:780:ex5:words:1:zh":"movie","grammar:780:ex5:words:1:note":"えいが","grammar:780:ex5:words:1:pos":"noun","grammar:780:ex5:words:2:zh":"(nominative)","grammar:780:ex5:words:2:pos":"particle","grammar:780:ex5:words:3:zh":"interesting","grammar:780:ex5:words:3:note":"おもしろい","grammar:780:ex5:words:3:pos":"adjective","grammar:780:ex5:words:4:zh":"(polite form)","grammar:780:ex5:words:4:pos":"copula","grammar:780:ex5:words:5:zh":"(question)","grammar:780:ex5:words:5:pos":"particle","grammar:780:ex5:points:0":"どの映画: which movie.","grammar:780:ex5:points:1":"面白い: interesting, fun.","exam:780:zh":"Please choose one of these four and tell me which bag you like.","exam:780:why":"「どの」 comes before a noun and asks which one among several options. 「この」 points to one specific thing, so it can't express asking someone to choose from among four."},"781":{"example:781:exzh":"The answer to that problem is simple.","example:781:exzh2":"His answer is correct.","example:781:exzh3":"Could you tell me the answer?","example:781:exzh4":"I checked the answers to the test.","example:781:exzh5":"There is no answer to this question.","grammar:781:ex:trans":"The answer to that question is simple.","grammar:781:ex:structure":"〜は簡単です","grammar:781:ex:explain":"The key word 「答え」 (answer) is the noun form of the verb 「答える」 (to answer). 「問題の答え」 links the two with 「の」, giving the answer to the question. 「は簡単です」 uses the na-adjective 「簡単」 as the predicate. The whole sentence means The answer to that question is simple. Japanese often turns a verb stem into a noun (答え, 始まり, 考え) — an important word-building pattern.","grammar:781:ex:words:0:zh":"that","grammar:781:ex:words:0:pos":"pre-noun adjectival","grammar:781:ex:words:1:zh":"problem","grammar:781:ex:words:1:note":"もんだい","grammar:781:ex:words:1:pos":"noun","grammar:781:ex:words:2:zh":"'s","grammar:781:ex:words:2:pos":"particle","grammar:781:ex:words:3:zh":"answer","grammar:781:ex:words:3:note":"こたえ","grammar:781:ex:words:3:pos":"noun","grammar:781:ex:words:4:zh":"(topic)","grammar:781:ex:words:4:pos":"particle","grammar:781:ex:words:5:zh":"easy","grammar:781:ex:words:5:note":"かんたん","grammar:781:ex:words:5:pos":"na-adjective","grammar:781:ex:words:6:zh":"(polite form)","grammar:781:ex:words:6:pos":"copula","grammar:781:ex:points:0":"答え (こたえ): answer (noun form of 答える).","grammar:781:ex:points:1":"問題の答え: the answer to the question.","grammar:781:ex2:trans":"His answer is correct.","grammar:781:ex2:structure":"〜は正しいです","grammar:781:ex2:words:0:zh":"he","grammar:781:ex2:words:0:note":"かれ","grammar:781:ex2:words:0:pos":"pronoun","grammar:781:ex2:words:1:zh":"'s","grammar:781:ex2:words:1:pos":"particle","grammar:781:ex2:words:2:zh":"answer","grammar:781:ex2:words:2:note":"こたえ","grammar:781:ex2:words:2:pos":"noun","grammar:781:ex2:words:3:zh":"(topic)","grammar:781:ex2:words:3:pos":"particle","grammar:781:ex2:words:4:zh":"correct","grammar:781:ex2:words:4:note":"ただしい","grammar:781:ex2:words:4:pos":"adjective","grammar:781:ex2:words:5:zh":"(polite form)","grammar:781:ex2:words:5:pos":"copula","grammar:781:ex2:points:0":"彼の答え: his answer.","grammar:781:ex2:points:1":"正しい: correct.","grammar:781:ex3:trans":"Could you tell me the answer?","grammar:781:ex3:structure":"〜てもらえますか","grammar:781:ex3:words:0:zh":"answer","grammar:781:ex3:words:0:note":"こたえ","grammar:781:ex3:words:0:pos":"noun","grammar:781:ex3:words:1:zh":"(object marker)","grammar:781:ex3:words:1:pos":"particle","grammar:781:ex3:words:2:zh":"tell","grammar:781:ex3:words:2:note":"おしえて","grammar:781:ex3:words:2:pos":"verb","grammar:781:ex3:words:3:zh":"Could you (do … for me)","grammar:781:ex3:words:3:pos":"auxiliary verb","grammar:781:ex3:words:4:zh":"(question)","grammar:781:ex3:words:4:pos":"particle","grammar:781:ex3:points:0":"❗〜てもらえますか: could you please … for me? (polite request).","grammar:781:ex3:points:1":"答えを教える: to tell (someone) the answer.","grammar:781:ex4:trans":"I checked the test answers.","grammar:781:ex4:structure":"〜を確認しました","grammar:781:ex4:words:0:zh":"test","grammar:781:ex4:words:0:note":"loanword","grammar:781:ex4:words:0:pos":"noun","grammar:781:ex4:words:1:zh":"'s","grammar:781:ex4:words:1:pos":"particle","grammar:781:ex4:words:2:zh":"answer","grammar:781:ex4:words:2:note":"こたえ","grammar:781:ex4:words:2:pos":"noun","grammar:781:ex4:words:3:zh":"(object marker)","grammar:781:ex4:words:3:pos":"particle","grammar:781:ex4:words:4:zh":"confirmed","grammar:781:ex4:words:4:note":"かくにんしました","grammar:781:ex4:words:4:pos":"verb","grammar:781:ex4:points:0":"テストの答え: the test answers.","grammar:781:ex4:points:1":"確認する: confirm.","grammar:781:ex5:trans":"There is no answer to this question.","grammar:781:ex5:structure":"〜には〜がありません","grammar:781:ex5:words:0:zh":"this","grammar:781:ex5:words:0:pos":"pre-noun adjectival","grammar:781:ex5:words:1:zh":"problem","grammar:781:ex5:words:1:note":"とい","grammar:781:ex5:words:1:pos":"noun","grammar:781:ex5:words:2:zh":"(object)","grammar:781:ex5:words:2:pos":"particle","grammar:781:ex5:words:3:zh":"(contrast)","grammar:781:ex5:words:3:pos":"particle","grammar:781:ex5:words:4:zh":"answer","grammar:781:ex5:words:4:note":"こたえ","grammar:781:ex5:words:4:pos":"noun","grammar:781:ex5:words:5:zh":"(nominative)","grammar:781:ex5:words:5:pos":"particle","grammar:781:ex5:words:6:zh":"don't have","grammar:781:ex5:words:6:pos":"verb","grammar:781:ex5:points:0":"問い: question, query.","grammar:781:ex5:points:1":"〜には答えがない: there is no answer to …","exam:781:zh":"The answer to the question 「How much is one plus two?」 is 「三」.","exam:781:why":"The result you get from answering a question is the 「答え」. 「意味」 means meaning, and the number three isn't the meaning of this question."},"782":{"example:782:exzh":"Today feels nice, doesn't it?","example:782:exzh2":"Listening to him talk, I felt happy.","example:782:exzh3":"This music feels nostalgic.","example:782:exzh4":"Her smile made me feel warm inside.","example:782:exzh5":"Looking at this painting makes me feel calm.","grammar:782:ex:trans":"It feels good today, doesn't it?","grammar:782:ex:structure":"〜はいい感じだね","grammar:782:ex:explain":"The key word is 「感じ」 (feeling, atmosphere), which comes from the noun form of the verb 「感じる」 (to feel). 「いい感じ」 means feels good or nice vibe — a very casual way of evaluating something. The ending 「だね」 is the plain form plus 「ね」, inviting agreement. The whole sentence means It feels good today, doesn't it? 「感じ」 is extremely versatile and can describe atmosphere, impression or condition, as in 「いい感じの店」.","grammar:782:ex:words:0:zh":"today","grammar:782:ex:words:0:note":"きょう","grammar:782:ex:words:0:pos":"noun","grammar:782:ex:words:1:zh":"(topic)","grammar:782:ex:words:1:pos":"particle","grammar:782:ex:words:2:zh":"good","grammar:782:ex:words:2:pos":"adjective","grammar:782:ex:words:3:zh":"sense","grammar:782:ex:words:3:note":"かんじ","grammar:782:ex:words:3:pos":"noun","grammar:782:ex:words:4:zh":"is","grammar:782:ex:words:4:pos":"copula","grammar:782:ex:words:5:zh":"right?","grammar:782:ex:words:5:pos":"particle","grammar:782:ex:points:0":"❗感じ (かんじ): feeling, atmosphere.","grammar:782:ex:points:1":"いい感じ: feels good, nice vibe.","grammar:782:ex2:trans":"After listening to him talk, I felt happy.","grammar:782:ex2:structure":"〜感じがした","grammar:782:ex2:words:0:zh":"he","grammar:782:ex2:words:0:note":"かれ","grammar:782:ex2:words:0:pos":"pronoun","grammar:782:ex2:words:1:zh":"'s","grammar:782:ex2:words:1:pos":"particle","grammar:782:ex2:words:2:zh":"talk; story","grammar:782:ex2:words:2:note":"はなし","grammar:782:ex2:words:2:pos":"noun","grammar:782:ex2:words:3:zh":"(object marker)","grammar:782:ex2:words:3:pos":"particle","grammar:782:ex2:words:4:zh":"listen","grammar:782:ex2:words:4:note":"きいて","grammar:782:ex2:words:4:pos":"verb","grammar:782:ex2:words:5:zh":"fun","grammar:782:ex2:words:5:note":"たのしい","grammar:782:ex2:words:5:pos":"adjective","grammar:782:ex2:words:6:zh":"sense","grammar:782:ex2:words:6:note":"かんじ","grammar:782:ex2:words:6:pos":"noun","grammar:782:ex2:words:7:zh":"(nominative)","grammar:782:ex2:words:7:pos":"particle","grammar:782:ex2:words:8:zh":"(had) a feeling","grammar:782:ex2:words:8:pos":"verb","grammar:782:ex2:points:0":"❗〜感じがする: to have a … feeling (set expression).","grammar:782:ex2:points:1":"楽しい感じ: a happy feeling.","grammar:782:ex3:trans":"This music gives me a nostalgic feeling.","grammar:782:ex3:structure":"〜感じがする","grammar:782:ex3:words:0:zh":"this","grammar:782:ex3:words:0:pos":"pre-noun adjectival","grammar:782:ex3:words:1:zh":"music","grammar:782:ex3:words:1:note":"おんがく","grammar:782:ex3:words:1:pos":"noun","grammar:782:ex3:words:2:zh":"(topic)","grammar:782:ex3:words:2:pos":"particle","grammar:782:ex3:words:3:zh":"Nostalgic","grammar:782:ex3:words:3:note":"なつかしい","grammar:782:ex3:words:3:pos":"adjective","grammar:782:ex3:words:4:zh":"sense","grammar:782:ex3:words:4:note":"かんじ","grammar:782:ex3:words:4:pos":"noun","grammar:782:ex3:words:5:zh":"(nominative)","grammar:782:ex3:words:5:pos":"particle","grammar:782:ex3:words:6:zh":"(to feel)","grammar:782:ex3:words:6:pos":"verb","grammar:782:ex3:points:0":"懐かしい: nostalgic.","grammar:782:ex3:points:1":"〜感じがする: to give the feeling of …","grammar:782:ex4:trans":"Her smile made me feel warm inside.","grammar:782:ex4:structure":"〜感じがした","grammar:782:ex4:words:0:zh":"she","grammar:782:ex4:words:0:note":"かのじょ","grammar:782:ex4:words:0:pos":"pronoun","grammar:782:ex4:words:1:zh":"'s","grammar:782:ex4:words:1:pos":"particle","grammar:782:ex4:words:2:zh":"Smile","grammar:782:ex4:words:2:note":"えがお","grammar:782:ex4:words:2:pos":"noun","grammar:782:ex4:words:3:zh":"(cause)","grammar:782:ex4:words:3:pos":"particle","grammar:782:ex4:words:4:zh":"Heartwarming","grammar:782:ex4:words:4:pos":"verb","grammar:782:ex4:words:5:zh":"sense","grammar:782:ex4:words:5:note":"かんじ","grammar:782:ex4:words:5:pos":"noun","grammar:782:ex4:words:6:zh":"(nominative)","grammar:782:ex4:words:6:pos":"particle","grammar:782:ex4:words:7:zh":"(to feel)","grammar:782:ex4:words:7:pos":"verb","grammar:782:ex4:points:0":"ほっこりする: to feel warmed (inside), soothing.","grammar:782:ex4:points:1":"〜感じがした: felt a … feeling.","grammar:782:ex5:trans":"Looking at this picture makes you feel calm.","grammar:782:ex5:structure":"〜と、〜感じになる","grammar:782:ex5:words:0:zh":"this","grammar:782:ex5:words:0:pos":"pre-noun adjectival","grammar:782:ex5:words:1:zh":"picture","grammar:782:ex5:words:1:note":"え","grammar:782:ex5:words:1:pos":"noun","grammar:782:ex5:words:2:zh":"(object marker)","grammar:782:ex5:words:2:pos":"particle","grammar:782:ex5:words:3:zh":"look","grammar:782:ex5:words:3:note":"みる","grammar:782:ex5:words:3:pos":"verb","grammar:782:ex5:words:4:zh":"(as soon as…)","grammar:782:ex5:words:4:pos":"particle","grammar:782:ex5:words:5:zh":"Calm","grammar:782:ex5:words:5:note":"おだやか","grammar:782:ex5:words:5:pos":"na-adjective","grammar:782:ex5:words:6:zh":"(attributive form)","grammar:782:ex5:words:6:pos":"auxiliary verb","grammar:782:ex5:words:7:zh":"sense","grammar:782:ex5:words:7:note":"かんじ","grammar:782:ex5:words:7:pos":"noun","grammar:782:ex5:words:8:zh":"(result)","grammar:782:ex5:words:8:pos":"particle","grammar:782:ex5:words:9:zh":"become","grammar:782:ex5:words:9:pos":"verb","grammar:782:ex5:points:0":"❗〜と: as soon as …, then …","grammar:782:ex5:points:1":"穏やかな感じになる: to become calm."},"783":{"example:783:exzh":"I'm wearing a new shirt.","example:783:exzh2":"It's warm today, so I'll wear light clothes.","example:783:exzh3":"He always wears casual clothes.","example:783:exzh4":"I like wearing thick clothes in winter.","example:783:exzh5":"I wore a dress to yesterday's party.","grammar:783:ex:trans":"I'm wearing a new shirt.","grammar:783:ex:structure":"〜を着ています","grammar:783:ex:explain":"The key verb is 「着る」 (to wear), which specifically covers clothing for the upper body or the whole body (shirts, jackets). Combined with 「〜ている」 it describes the state of wearing something, not an action in progress. 「を」 marks the object 「シャツ」. The whole sentence means I'm wearing a new shirt. Note that Japanese uses different verbs for different body parts: 「着る」 for the upper body, 「履く」 for the lower body, shoes and socks, and 「かぶる」 for hats — one of the delicate details of Japanese.","grammar:783:ex:words:0:zh":"new","grammar:783:ex:words:0:note":"あたらしい","grammar:783:ex:words:0:pos":"adjective","grammar:783:ex:words:1:zh":"shirt","grammar:783:ex:words:1:note":"loanword","grammar:783:ex:words:1:pos":"noun","grammar:783:ex:words:2:zh":"(object marker)","grammar:783:ex:words:2:pos":"particle","grammar:783:ex:words:3:zh":"Wearing","grammar:783:ex:words:3:note":"きています","grammar:783:ex:words:3:pos":"verb","grammar:783:ex:points:0":"❗着る (きる): to wear (upper-body or whole-body clothing).","grammar:783:ex:points:1":"〜ている: the (wearing) state.","grammar:783:ex2:trans":"It's warm today, so I'll wear light clothes.","grammar:783:ex2:structure":"〜は暖かいから、薄い服を着ます","grammar:783:ex2:explain":"「今日は暖かい」 says that the weather is warm today, and the following 「から」 marks that as the reason for wearing light clothes. 「薄い」 modifies 「服」 directly, with no 「な」 needed. 「服を」 is the object of 「着る」, and 「着ます」 here means (I) will wear light clothes.","grammar:783:ex2:words:0:zh":"today","grammar:783:ex2:words:0:note":"きょう","grammar:783:ex2:words:0:pos":"noun","grammar:783:ex2:words:1:zh":"(topic)","grammar:783:ex2:words:1:pos":"particle","grammar:783:ex2:words:2:zh":"Warm","grammar:783:ex2:words:2:note":"あたたかい","grammar:783:ex2:words:2:pos":"i-adjective","grammar:783:ex2:words:3:zh":"(reason, cause)","grammar:783:ex2:words:3:pos":"particle","grammar:783:ex2:words:4:zh":"Thin, light","grammar:783:ex2:words:4:note":"うすい","grammar:783:ex2:words:4:pos":"i-adjective","grammar:783:ex2:words:5:zh":"clothes","grammar:783:ex2:words:5:note":"ふく","grammar:783:ex2:words:5:pos":"noun","grammar:783:ex2:words:6:zh":"(object)","grammar:783:ex2:words:6:pos":"particle","grammar:783:ex2:words:7:zh":"wear","grammar:783:ex2:words:7:note":"き","grammar:783:ex2:words:7:pos":"verb","grammar:783:ex2:words:8:zh":"(polite tone)","grammar:783:ex2:words:8:pos":"auxiliary verb","grammar:783:ex2:points:0":"「から」 follows the reason and means because …, so …","grammar:783:ex2:points:1":"i-adjectives can be followed directly by 「から」, with no 「だ」 needed.","grammar:783:ex2:points:2":"「服を着る」 means to put on clothes; 「着る」 is an ichidan (ru-) verb.","grammar:783:ex3:trans":"He always wears casual clothes.","grammar:783:ex3:structure":"〜を着ている","grammar:783:ex3:words:0:zh":"he","grammar:783:ex3:words:0:note":"かれ","grammar:783:ex3:words:0:pos":"pronoun","grammar:783:ex3:words:1:zh":"(topic)","grammar:783:ex3:words:1:pos":"particle","grammar:783:ex3:words:2:zh":"always","grammar:783:ex3:words:2:pos":"adverb","grammar:783:ex3:words:3:zh":"Casual","grammar:783:ex3:words:3:note":"loanword","grammar:783:ex3:words:3:pos":"na-adjective","grammar:783:ex3:words:4:zh":"(attributive form)","grammar:783:ex3:words:4:pos":"auxiliary verb","grammar:783:ex3:words:5:zh":"clothes","grammar:783:ex3:words:5:note":"ふく","grammar:783:ex3:words:5:pos":"noun","grammar:783:ex3:words:6:zh":"(object marker)","grammar:783:ex3:words:6:pos":"particle","grammar:783:ex3:words:7:zh":"Wearing","grammar:783:ex3:words:7:note":"きている","grammar:783:ex3:words:7:pos":"verb","grammar:783:ex3:points:0":"カジュアルな服: casual clothes.","grammar:783:ex3:points:1":"〜を着ている: to be wearing …","grammar:783:ex4:trans":"I like wearing thick clothes in winter.","grammar:783:ex4:structure":"冬は［厚い服を着る］のが好きだ","grammar:783:ex4:explain":"「冬は」 sets up winter as the setting and may also hint at a contrast with other seasons. 「厚い服を着る」 means to wear thick clothes, and adding 「の」 turns it into an action you can talk about. 「のが好きだ」 says that the speaker likes doing this. Here 「の」 is used for nominalization, not to show possession.","grammar:783:ex4:words:0:zh":"winter","grammar:783:ex4:words:0:note":"ふゆ","grammar:783:ex4:words:0:pos":"noun","grammar:783:ex4:words:1:zh":"(topic, contrast)","grammar:783:ex4:words:1:pos":"particle","grammar:783:ex4:words:2:zh":"Thick","grammar:783:ex4:words:2:note":"あつい","grammar:783:ex4:words:2:pos":"i-adjective","grammar:783:ex4:words:3:zh":"clothes","grammar:783:ex4:words:3:note":"ふく","grammar:783:ex4:words:3:pos":"noun","grammar:783:ex4:words:4:zh":"(object)","grammar:783:ex4:words:4:pos":"particle","grammar:783:ex4:words:5:zh":"wear","grammar:783:ex4:words:5:note":"きる","grammar:783:ex4:words:5:pos":"verb","grammar:783:ex4:words:6:zh":"(nominalizes the preceding action)","grammar:783:ex4:words:6:pos":"particle","grammar:783:ex4:words:7:zh":"(the object of liking)","grammar:783:ex4:words:7:pos":"particle","grammar:783:ex4:words:8:zh":"to like","grammar:783:ex4:words:8:note":"すき","grammar:783:ex4:words:8:pos":"na-adjective","grammar:783:ex4:words:9:zh":"(plain-form judgment)","grammar:783:ex4:words:9:pos":"auxiliary verb","grammar:783:ex4:points:0":"「verb in dictionary form + のが好き」 means to like doing something.","grammar:783:ex4:points:1":"「の」 nominalizes the action of wearing thick clothes, and 「が」 marks the object of liking.","grammar:783:ex4:points:2":"「好きだ」 is the plain form; the polite form is 「好きです」.","grammar:783:ex5:trans":"I wore a dress at yesterday's party.","grammar:783:ex5:structure":"〜では〜を着た","grammar:783:ex5:words:0:zh":"yesterday","grammar:783:ex5:words:0:note":"きのう","grammar:783:ex5:words:0:pos":"noun","grammar:783:ex5:words:1:zh":"'s","grammar:783:ex5:words:1:pos":"particle","grammar:783:ex5:words:2:zh":"party","grammar:783:ex5:words:2:note":"loanword","grammar:783:ex5:words:2:pos":"noun","grammar:783:ex5:words:3:zh":"(place)","grammar:783:ex5:words:3:pos":"particle","grammar:783:ex5:words:4:zh":"(contrast)","grammar:783:ex5:words:4:pos":"particle","grammar:783:ex5:words:5:zh":"dress","grammar:783:ex5:words:5:note":"loanword","grammar:783:ex5:words:5:pos":"noun","grammar:783:ex5:words:6:zh":"(object marker)","grammar:783:ex5:words:6:pos":"particle","grammar:783:ex5:words:7:zh":"put on","grammar:783:ex5:words:7:note":"きた","grammar:783:ex5:words:7:pos":"verb","grammar:783:ex5:points:0":"パーティーでは: at the party.","grammar:783:ex5:points:1":"ドレスを着る: to wear a dress.","exam:783:zh":"On cold days, I wear a sweater over my shirt.","exam:783:why":"For upper-body clothing like sweaters, use 「着る」. 「履く」 is used for shoes, socks, trousers and the like, not for sweaters."},"784":{"example:784:exzh":"Look, that's him over there.","example:784:exzh2":"Look, it's about to start.","example:784:exzh3":"Come on, you come along too.","example:784:exzh4":"Look, try watching this interesting movie.","example:784:exzh5":"Look, it's just the right time to eat.","grammar:784:ex:trans":"Look, that's him over there.","grammar:784:ex:structure":"ほら、〜のが〜です","grammar:784:ex:explain":"The key word is the attention-getting interjection 「ほら」, used to draw someone's attention or point something out — like look or see there. In 「あそこにいるのが彼です」, 「の」 nominalizes the person who is over there, and 「が」 marks it, emphasizing that's him. The whole sentence means Look, that's him over there. 「ほら」 carries a slightly proud or prompting tone and is common when pointing something out to someone.","grammar:784:ex:words:0:zh":"look","grammar:784:ex:words:0:pos":"interjection","grammar:784:ex:words:1:zh":"there","grammar:784:ex:words:1:pos":"pronoun","grammar:784:ex:words:2:zh":"(location of existence)","grammar:784:ex:words:2:pos":"particle","grammar:784:ex:words:3:zh":"exist","grammar:784:ex:words:3:pos":"verb","grammar:784:ex:words:4:zh":"(nominalizer)","grammar:784:ex:words:4:pos":"particle","grammar:784:ex:words:5:zh":"(nominative)","grammar:784:ex:words:5:pos":"particle","grammar:784:ex:words:6:zh":"he","grammar:784:ex:words:6:note":"かれ","grammar:784:ex:words:6:pos":"pronoun","grammar:784:ex:words:7:zh":"is","grammar:784:ex:words:7:pos":"copula","grammar:784:ex:points:0":"❗ほら: look, see (drawing the listener's attention).","grammar:784:ex:points:1":"あそこにいるの: the one (person) over there.","grammar:784:ex2:trans":"Look, it's about to start.","grammar:784:ex2:structure":"ほら、もうすぐ〜よ","grammar:784:ex2:words:0:zh":"look","grammar:784:ex2:words:0:pos":"interjection","grammar:784:ex2:words:1:zh":"soon","grammar:784:ex2:words:1:pos":"adverb","grammar:784:ex2:words:2:zh":"begins","grammar:784:ex2:words:2:note":"はじまる","grammar:784:ex2:words:2:pos":"verb","grammar:784:ex2:words:3:zh":"(reminder)","grammar:784:ex2:words:3:pos":"particle","grammar:784:ex2:points:0":"もうすぐ: soon, in a moment.","grammar:784:ex2:points:1":"始まる: to begin (intransitive verb).","grammar:784:ex3:trans":"Look, you come along too.","grammar:784:ex3:structure":"ほら、〜なさい","grammar:784:ex3:words:0:zh":"come","grammar:784:ex3:words:0:pos":"interjection","grammar:784:ex3:words:1:zh":"you","grammar:784:ex3:words:1:note":"きみ","grammar:784:ex3:words:1:pos":"pronoun","grammar:784:ex3:words:2:zh":"also, too","grammar:784:ex3:words:2:pos":"particle","grammar:784:ex3:words:3:zh":"together","grammar:784:ex3:words:3:note":"いっしょに","grammar:784:ex3:words:3:pos":"adverb","grammar:784:ex3:words:4:zh":"Come","grammar:784:ex3:words:4:note":"きなさい","grammar:784:ex3:words:4:pos":"verb","grammar:784:ex3:points:0":"❗〜なさい: (mild command) please do …","grammar:784:ex3:points:1":"君も一緒に: you too, together.","grammar:784:ex4:trans":"Look, try watching this interesting movie.","grammar:784:ex4:structure":"ほら、〜てみて","grammar:784:ex4:words:0:zh":"come","grammar:784:ex4:words:0:pos":"interjection","grammar:784:ex4:words:1:zh":"this","grammar:784:ex4:words:1:pos":"pre-noun adjectival","grammar:784:ex4:words:2:zh":"interesting","grammar:784:ex4:words:2:note":"おもしろい","grammar:784:ex4:words:2:pos":"adjective","grammar:784:ex4:words:3:zh":"movie","grammar:784:ex4:words:3:note":"えいが","grammar:784:ex4:words:3:pos":"noun","grammar:784:ex4:words:4:zh":"(object marker)","grammar:784:ex4:words:4:pos":"particle","grammar:784:ex4:words:5:zh":"try … and see","grammar:784:ex4:words:5:pos":"verb","grammar:784:ex4:points:0":"〜てみて: try doing … (and see).","grammar:784:ex4:points:1":"面白い映画: an interesting movie.","grammar:784:ex5:trans":"Look, it's just the right time to eat.","grammar:784:ex5:structure":"ほら、もう〜よ","grammar:784:ex5:words:0:zh":"look","grammar:784:ex5:words:0:pos":"interjection","grammar:784:ex5:words:1:zh":"already","grammar:784:ex5:words:1:pos":"adverb","grammar:784:ex5:words:2:zh":"The right time to eat","grammar:784:ex5:words:2:note":"たべごろ","grammar:784:ex5:words:2:pos":"noun","grammar:784:ex5:words:3:zh":"(reminder)","grammar:784:ex5:words:3:pos":"particle","grammar:784:ex5:points:0":"❗食べ頃: just the right time to eat (食べ + 頃).","grammar:784:ex5:points:1":"もう: already."},"785":{"example:785:exzh":"Please put the book on the desk.","example:785:exzh2":"He set down the flowers and went home.","example:785:exzh3":"May I put my luggage here?","example:785:exzh4":"I put the plates on the shelf.","example:785:exzh5":"I put the food on the table.","grammar:785:ex:trans":"Please put the book on the desk.","grammar:785:ex:structure":"〔nounの上〕＋に＋noun＋を＋置いてください。 Use に for the place where something is put.","grammar:785:ex:explain":"The key point here is that に marks the end point of placement. 「机の上に置く」 means putting it on the desk: に marks the position 「机の上」 (on the desk) where the object is placed. を marks the object 「本」, and 「置いて」 is the te-form plus 「ください」 to make a request. The whole sentence means please put the book on the desk. With placement verbs such as 置く, 貼る, and 載せる, the destination is always marked with に — that is the main point.","grammar:785:ex:words:0:zh":"desk","grammar:785:ex:words:0:note":"つくえ","grammar:785:ex:words:0:pos":"noun","grammar:785:ex:words:1:zh":"'s","grammar:785:ex:words:1:pos":"particle","grammar:785:ex:words:2:zh":"on top of","grammar:785:ex:words:2:note":"うえ","grammar:785:ex:words:2:pos":"noun","grammar:785:ex:words:3:zh":"(the destination)","grammar:785:ex:words:3:pos":"particle","grammar:785:ex:words:4:zh":"book","grammar:785:ex:words:4:note":"ほん","grammar:785:ex:words:4:pos":"noun","grammar:785:ex:words:5:zh":"(object marker)","grammar:785:ex:words:5:pos":"particle","grammar:785:ex:words:6:zh":"put","grammar:785:ex:words:6:note":"おいて; te-form","grammar:785:ex:words:6:pos":"verb","grammar:785:ex:words:7:zh":"please","grammar:785:ex:words:7:note":"〜てください","grammar:785:ex:words:7:pos":"verb","grammar:785:ex:points:0":"〜の上に置く: to put on top of…","grammar:785:ex:points:1":"〜てください: please do…","grammar:785:ex2:trans":"He put the flowers down and then went home.","grammar:785:ex2:structure":"nounを＋〔verb te-form〕＋verbました。 「置いて帰る」 ＝ put it down and then go back (the te-form links two actions).","grammar:785:ex2:words:0:zh":"he","grammar:785:ex2:words:0:note":"かれ","grammar:785:ex2:words:0:pos":"pronoun","grammar:785:ex2:words:1:zh":"(topic marker)","grammar:785:ex2:words:1:pos":"particle","grammar:785:ex2:words:2:zh":"flowers","grammar:785:ex2:words:2:note":"はな","grammar:785:ex2:words:2:pos":"noun","grammar:785:ex2:words:3:zh":"(object marker)","grammar:785:ex2:words:3:pos":"particle","grammar:785:ex2:words:4:zh":"put down (and then)","grammar:785:ex2:words:4:note":"おいて; te-form linking","grammar:785:ex2:words:4:pos":"verb","grammar:785:ex2:words:5:zh":"went home","grammar:785:ex2:words:5:note":"かえりました","grammar:785:ex2:words:5:pos":"verb","grammar:785:ex2:points:0":"te-form linking: 置いて帰る (put it down and go back)","grammar:785:ex2:points:1":"置く: to place / put","grammar:785:ex3:trans":"May I put the luggage here?","grammar:785:ex3:structure":"placeに＋nounを＋〜てもいいですか。 「〜てもいい」 expresses permission: may I…?","grammar:785:ex3:words:0:zh":"here","grammar:785:ex3:words:0:pos":"pronoun","grammar:785:ex3:words:1:zh":"(the destination)","grammar:785:ex3:words:1:pos":"particle","grammar:785:ex3:words:2:zh":"luggage","grammar:785:ex3:words:2:note":"にもつ","grammar:785:ex3:words:2:pos":"noun","grammar:785:ex3:words:3:zh":"(object marker)","grammar:785:ex3:words:3:pos":"particle","grammar:785:ex3:words:4:zh":"put (too)","grammar:785:ex3:words:4:note":"おいても; te-form＋も","grammar:785:ex3:words:4:pos":"verb","grammar:785:ex3:words:5:zh":"it's okay","grammar:785:ex3:words:5:note":"〜てもいい","grammar:785:ex3:words:5:pos":"adjective","grammar:785:ex3:words:6:zh":"(polite form)","grammar:785:ex3:words:6:pos":"copula","grammar:785:ex3:words:7:zh":"(question)","grammar:785:ex3:words:7:pos":"particle","grammar:785:ex3:points:0":"〜てもいいですか: may I…? (asking permission)","grammar:785:ex3:points:1":"に置く: to put at / in…","grammar:785:ex4:trans":"I put the plate on the shelf.","grammar:785:ex4:structure":"placeに＋nounを＋置きました。","grammar:785:ex4:words:0:zh":"shelf","grammar:785:ex4:words:0:note":"たな","grammar:785:ex4:words:0:pos":"noun","grammar:785:ex4:words:1:zh":"(the destination)","grammar:785:ex4:words:1:pos":"particle","grammar:785:ex4:words:2:zh":"plate / dish","grammar:785:ex4:words:2:note":"おさら","grammar:785:ex4:words:2:pos":"noun","grammar:785:ex4:words:3:zh":"(object marker)","grammar:785:ex4:words:3:pos":"particle","grammar:785:ex4:words:4:zh":"put (past)","grammar:785:ex4:words:4:note":"おきました","grammar:785:ex4:words:4:pos":"verb","grammar:785:ex4:points:0":"棚に置く: to put on the shelf","grammar:785:ex4:points:1":"置きました: polite past","grammar:785:ex5:trans":"I put the food on the table.","grammar:785:ex5:structure":"〔nounの上〕＋に＋noun＋を＋置いた。","grammar:785:ex5:words:0:zh":"desk","grammar:785:ex5:words:0:note":"loanword","grammar:785:ex5:words:0:pos":"noun","grammar:785:ex5:words:1:zh":"'s","grammar:785:ex5:words:1:pos":"particle","grammar:785:ex5:words:2:zh":"on top of","grammar:785:ex5:words:2:note":"うえ","grammar:785:ex5:words:2:pos":"noun","grammar:785:ex5:words:3:zh":"(the destination)","grammar:785:ex5:words:3:pos":"particle","grammar:785:ex5:words:4:zh":"food","grammar:785:ex5:words:4:note":"たべもの","grammar:785:ex5:words:4:pos":"noun","grammar:785:ex5:words:5:zh":"(object marker)","grammar:785:ex5:words:5:pos":"particle","grammar:785:ex5:words:6:zh":"put (past)","grammar:785:ex5:words:6:note":"おいた; ta-form past","grammar:785:ex5:words:6:pos":"verb","grammar:785:ex5:points:0":"〜の上に置く: to put on top of…","grammar:785:ex5:points:1":"置いた: ta-form past (plain form)"},"786":{"example:786:exzh":"This movie is wonderful.","example:786:exzh2":"Her singing voice is wonderful.","example:786:exzh3":"There are many wonderful experiences.","example:786:exzh4":"This painting is wonderful, isn't it?","example:786:exzh5":"A wonderful view spreads out before us."},"787":{"example:787:exzh":"I'm meeting a friend tonight.","example:787:exzh2":"The stars are beautiful tonight.","example:787:exzh3":"What's for dinner tonight?","example:787:exzh4":"I'm going to see a movie tonight.","example:787:exzh5":"It's cold tonight.","grammar:787:ex:trans":"I'm meeting a friend tonight.","grammar:787:ex:structure":"今夜、〜と会います","grammar:787:ex:words:0:zh":"tonight","grammar:787:ex:words:0:note":"こんや","grammar:787:ex:words:0:pos":"noun","grammar:787:ex:words:1:zh":"friend","grammar:787:ex:words:1:note":"ともだち","grammar:787:ex:words:1:pos":"noun","grammar:787:ex:words:2:zh":"with","grammar:787:ex:words:2:pos":"particle","grammar:787:ex:words:3:zh":"meet","grammar:787:ex:words:3:note":"あいます","grammar:787:ex:words:3:pos":"verb","grammar:787:ex:points:0":"今夜 (こんや): tonight.","grammar:787:ex:points:1":"友達と会う: to meet a friend.","grammar:787:ex2:trans":"The stars are beautiful tonight.","grammar:787:ex2:structure":"今夜は〜が綺麗です","grammar:787:ex2:words:0:zh":"tonight","grammar:787:ex2:words:0:note":"こんや","grammar:787:ex2:words:0:pos":"noun","grammar:787:ex2:words:1:zh":"(topic)","grammar:787:ex2:words:1:pos":"particle","grammar:787:ex2:words:2:zh":"star","grammar:787:ex2:words:2:note":"ほし","grammar:787:ex2:words:2:pos":"noun","grammar:787:ex2:words:3:zh":"(nominative)","grammar:787:ex2:words:3:pos":"particle","grammar:787:ex2:words:4:zh":"beautiful","grammar:787:ex2:words:4:note":"きれい","grammar:787:ex2:words:4:pos":"na-adjective","grammar:787:ex2:words:5:zh":"(polite form)","grammar:787:ex2:words:5:pos":"copula","grammar:787:ex2:points:0":"星が綺麗: the stars are beautiful (the subject takes が).","grammar:787:ex2:points:1":"今夜は: tonight (topic).","grammar:787:ex3:trans":"What's for dinner tonight?","grammar:787:ex3:structure":"今夜の〜は何ですか","grammar:787:ex3:words:0:zh":"tonight","grammar:787:ex3:words:0:note":"こんや","grammar:787:ex3:words:0:pos":"noun","grammar:787:ex3:words:1:zh":"'s","grammar:787:ex3:words:1:pos":"particle","grammar:787:ex3:words:2:zh":"dinner","grammar:787:ex3:words:2:note":"ばんごはん","grammar:787:ex3:words:2:pos":"noun","grammar:787:ex3:words:3:zh":"(topic)","grammar:787:ex3:words:3:pos":"particle","grammar:787:ex3:words:4:zh":"what","grammar:787:ex3:words:4:note":"なに","grammar:787:ex3:words:4:pos":"question word","grammar:787:ex3:words:5:zh":"is","grammar:787:ex3:words:5:pos":"copula","grammar:787:ex3:words:6:zh":"(question)","grammar:787:ex3:words:6:pos":"particle","grammar:787:ex3:points:0":"今夜の晩ごはん: tonight's dinner.","grammar:787:ex3:points:1":"何ですか: what is it.","grammar:787:ex4:trans":"I'm going to see a movie tonight.","grammar:787:ex4:structure":"今夜、〜を見に行きます","grammar:787:ex4:words:0:zh":"tonight","grammar:787:ex4:words:0:note":"こんや","grammar:787:ex4:words:0:pos":"noun","grammar:787:ex4:words:1:zh":"movie","grammar:787:ex4:words:1:note":"えいが","grammar:787:ex4:words:1:pos":"noun","grammar:787:ex4:words:2:zh":"(object marker)","grammar:787:ex4:words:2:pos":"particle","grammar:787:ex4:words:3:zh":"look","grammar:787:ex4:words:3:note":"み","grammar:787:ex4:words:3:pos":"noun","grammar:787:ex4:words:4:zh":"(purpose)","grammar:787:ex4:words:4:pos":"particle","grammar:787:ex4:words:5:zh":"go","grammar:787:ex4:words:5:pos":"verb","grammar:787:ex4:points:0":"映画を見に行く: to go see a movie.","grammar:787:ex4:points:1":"今夜: tonight.","grammar:787:ex5:trans":"It's cold tonight.","grammar:787:ex5:structure":"今夜は〜です","grammar:787:ex5:words:0:zh":"tonight","grammar:787:ex5:words:0:note":"こんや","grammar:787:ex5:words:0:pos":"noun","grammar:787:ex5:words:1:zh":"(topic)","grammar:787:ex5:words:1:pos":"particle","grammar:787:ex5:words:2:zh":"cold","grammar:787:ex5:words:2:note":"さむい","grammar:787:ex5:words:2:pos":"adjective","grammar:787:ex5:words:3:zh":"(polite form)","grammar:787:ex5:words:3:pos":"copula","grammar:787:ex5:points:0":"寒い: cold.","grammar:787:ex5:points:1":"今夜は寒い: it's cold tonight."},"788":{"example:788:exzh":"The key was finally found.","example:788:exzh2":"The important documents can't be found.","example:788:exzh3":"He found a good job.","example:788:exzh4":"Where can this book be found?","example:788:exzh5":"It's unclear when it will be found.","grammar:788:ex:trans":"I finally found the key.","grammar:788:ex:structure":"〜が見つかりました","grammar:788:ex:explain":"This sentence asks you to keep the intransitive verb 「見つかる」 and the transitive verb 「見つける」 apart: 「見つかる」 means something has been found (it turns up on its own, taking が), while 「見つける」 means someone actively finds something (taking を). Here 「鍵が見つかりました」 marks the key with 「が」, so the key was found — the focus is on the result, not on who found it. 「ついに」 means finally. The whole sentence means “I finally found the key.”","grammar:788:ex:words:0:zh":"finally","grammar:788:ex:words:0:pos":"adverb","grammar:788:ex:words:1:zh":"key","grammar:788:ex:words:1:note":"かぎ","grammar:788:ex:words:1:pos":"noun","grammar:788:ex:words:2:zh":"(nominative)","grammar:788:ex:words:2:pos":"particle","grammar:788:ex:words:3:zh":"was found","grammar:788:ex:words:3:note":"みつかりました","grammar:788:ex:words:3:pos":"verb","grammar:788:ex:points:0":"❗見つかる (intransitive verb, to be found) vs 見つける (transitive verb, to find).","grammar:788:ex:points:1":"ついに: finally.","grammar:788:ex2:trans":"I can't find the important documents.","grammar:788:ex2:structure":"〜が見つからない","grammar:788:ex2:words:0:zh":"important","grammar:788:ex2:words:0:note":"だいじ","grammar:788:ex2:words:0:pos":"na-adjective","grammar:788:ex2:words:1:zh":"(attributive form)","grammar:788:ex2:words:1:pos":"auxiliary verb","grammar:788:ex2:words:2:zh":"documents","grammar:788:ex2:words:2:note":"しょるい","grammar:788:ex2:words:2:pos":"noun","grammar:788:ex2:words:3:zh":"(nominative)","grammar:788:ex2:words:3:pos":"particle","grammar:788:ex2:words:4:zh":"can't be found","grammar:788:ex2:words:4:note":"みつからない","grammar:788:ex2:words:4:pos":"verb","grammar:788:ex2:points:0":"❗見つからない: can't be found (negative of the intransitive verb).","grammar:788:ex2:points:1":"大事な書類: important documents.","grammar:788:ex3:trans":"He found a good job.","grammar:788:ex3:structure":"〜は〜が見つかった","grammar:788:ex3:words:0:zh":"he","grammar:788:ex3:words:0:note":"かれ","grammar:788:ex3:words:0:pos":"pronoun","grammar:788:ex3:words:1:zh":"(topic)","grammar:788:ex3:words:1:pos":"particle","grammar:788:ex3:words:2:zh":"good","grammar:788:ex3:words:2:pos":"adjective","grammar:788:ex3:words:3:zh":"work","grammar:788:ex3:words:3:note":"しごと","grammar:788:ex3:words:3:pos":"noun","grammar:788:ex3:words:4:zh":"(nominative)","grammar:788:ex3:words:4:pos":"particle","grammar:788:ex3:words:5:zh":"found","grammar:788:ex3:words:5:note":"みつかった","grammar:788:ex3:words:5:pos":"verb","grammar:788:ex3:points:0":"❗〜は〜が見つかる: (someone) finds … (the thing found takes が).","grammar:788:ex3:points:1":"仕事が見つかる: to find a job.","grammar:788:ex4:trans":"Where can I find this book?","grammar:788:ex4:structure":"〜はどこで見つかりますか","grammar:788:ex4:explain":"「この本は」 sets the book as the topic, and 「どこで」 asks where it can be found. 「見つかります」 is the polite form of the intransitive verb 「見つかる」 and focuses on the result — the book being found. Even though it translates as “can be found,” the Japanese does not use the potential form. The final 「か」 marks the question.","grammar:788:ex4:words:0:zh":"this","grammar:788:ex4:words:0:pos":"pre-noun adjectival","grammar:788:ex4:words:1:zh":"book","grammar:788:ex4:words:1:note":"ほん","grammar:788:ex4:words:1:pos":"noun","grammar:788:ex4:words:2:zh":"(topic)","grammar:788:ex4:words:2:pos":"particle","grammar:788:ex4:words:3:zh":"where","grammar:788:ex4:words:3:pos":"pronoun","grammar:788:ex4:words:4:zh":"(the place where it is found)","grammar:788:ex4:words:4:pos":"particle","grammar:788:ex4:words:5:zh":"to be found","grammar:788:ex4:words:5:note":"みつかり","grammar:788:ex4:words:5:pos":"verb","grammar:788:ex4:words:6:zh":"(polite tone)","grammar:788:ex4:words:6:pos":"auxiliary verb","grammar:788:ex4:words:7:zh":"(question)","grammar:788:ex4:words:7:pos":"particle","grammar:788:ex4:points:0":"「見つかる」 is an intransitive verb meaning something is found; its transitive counterpart is 「見つける」.","grammar:788:ex4:points:1":"「どこで」 asks where something is found, and 「で」 marks the place where an event happens.","grammar:788:ex5:trans":"I don't know when it will be found.","grammar:788:ex5:structure":"いつ〜かわからない","grammar:788:ex5:words:0:zh":"when","grammar:788:ex5:words:0:pos":"question word","grammar:788:ex5:words:1:zh":"to be found","grammar:788:ex5:words:1:note":"みつかる","grammar:788:ex5:words:1:pos":"verb","grammar:788:ex5:words:2:zh":"(question)","grammar:788:ex5:words:2:pos":"particle","grammar:788:ex5:words:3:zh":"don't know","grammar:788:ex5:words:3:pos":"verb","grammar:788:ex5:points:0":"❗〜かわからない: don't know …","grammar:788:ex5:points:1":"いつ見つかるか: when it will be found."},"789":{"example:789:exzh":"Please go straight along this road.","example:789:exzh2":"Please tell me the way to the station.","example:789:exzh3":"When you cross the road, there's a park.","example:789:exzh4":"That road is very crowded.","example:789:exzh5":"A new road has been built.","grammar:789:ex:trans":"Please go straight along this road.","grammar:789:ex:structure":"〜をまっすぐ進んでください","grammar:789:ex:explain":"The point here is that 「を」 marks a path of movement. 「道を進む」 means to go along the road; 「を」 here does not mark an object but the route passed through or traveled along — a rather special use of 「を」. 「まっすぐ」 (straight) modifies the action, and 「進んで」 is the te-form plus 「ください」. The whole sentence means Please go straight along this road. Verbs of passing through a place (進む, 歩く, 渡る) often take 「を」 to mark the route.","grammar:789:ex:words:0:zh":"this","grammar:789:ex:words:0:pos":"pre-noun adjectival","grammar:789:ex:words:1:zh":"road","grammar:789:ex:words:1:note":"みち","grammar:789:ex:words:1:pos":"noun","grammar:789:ex:words:2:zh":"(path)","grammar:789:ex:words:2:pos":"particle","grammar:789:ex:words:3:zh":"straight","grammar:789:ex:words:3:pos":"adverb","grammar:789:ex:words:4:zh":"move forward","grammar:789:ex:words:4:note":"すすんで","grammar:789:ex:words:4:pos":"verb","grammar:789:ex:words:5:zh":"please","grammar:789:ex:words:5:pos":"auxiliary verb","grammar:789:ex:points:0":"❓道を進む: to go along the road (the route is marked with を).","grammar:789:ex:points:1":"まっすぐ: straight.","grammar:789:ex2:trans":"Please tell me the way to the station.","grammar:789:ex2:structure":"〜までの道を教えてください","grammar:789:ex2:words:0:zh":"station","grammar:789:ex2:words:0:note":"えき","grammar:789:ex2:words:0:pos":"noun","grammar:789:ex2:words:1:zh":"until","grammar:789:ex2:words:1:pos":"particle","grammar:789:ex2:words:2:zh":"'s","grammar:789:ex2:words:2:pos":"particle","grammar:789:ex2:words:3:zh":"road","grammar:789:ex2:words:3:note":"みち","grammar:789:ex2:words:3:pos":"noun","grammar:789:ex2:words:4:zh":"(object)","grammar:789:ex2:words:4:pos":"particle","grammar:789:ex2:words:5:zh":"Tell, teach","grammar:789:ex2:words:5:note":"おしえて: the te-form of 教える.","grammar:789:ex2:words:5:pos":"verb","grammar:789:ex2:words:6:zh":"please","grammar:789:ex2:words:6:pos":"auxiliary verb","grammar:789:ex2:points:0":"「駅までの道」: 「道」 means road, and 「〜までの道」 is the way to a place — the most common phrasing when asking for directions.","grammar:789:ex2:points:1":"「まで」 marks the endpoint, and 「の」 is needed for it to modify the noun 「道」.","grammar:789:ex2:points:2":"「te-form + ください」 is a polite request: please do …","grammar:789:ex3:trans":"If you cross the street, there's a park.","grammar:789:ex3:structure":"〜を渡ると〜があります","grammar:789:ex3:words:0:zh":"road","grammar:789:ex3:words:0:note":"みち","grammar:789:ex3:words:0:pos":"noun","grammar:789:ex3:words:1:zh":"(path)","grammar:789:ex3:words:1:pos":"particle","grammar:789:ex3:words:2:zh":"Cross","grammar:789:ex3:words:2:note":"わたる","grammar:789:ex3:words:2:pos":"verb","grammar:789:ex3:words:3:zh":"(as soon as…)","grammar:789:ex3:words:3:pos":"particle","grammar:789:ex3:words:4:zh":"park","grammar:789:ex3:words:4:note":"こうえん","grammar:789:ex3:words:4:pos":"noun","grammar:789:ex3:words:5:zh":"(nominative)","grammar:789:ex3:words:5:pos":"particle","grammar:789:ex3:words:6:zh":"there is / are","grammar:789:ex3:words:6:pos":"verb","grammar:789:ex3:points:0":"❗道を渡る: to cross the street.","grammar:789:ex3:points:1":"〜と: as soon as … (cross the street and you're there).","grammar:789:ex4:trans":"That road is very crowded.","grammar:789:ex4:structure":"〜はとても混んでいます","grammar:789:ex4:words:0:zh":"that","grammar:789:ex4:words:0:pos":"pre-noun adjectival","grammar:789:ex4:words:1:zh":"road","grammar:789:ex4:words:1:note":"みち","grammar:789:ex4:words:1:pos":"noun","grammar:789:ex4:words:2:zh":"(topic)","grammar:789:ex4:words:2:pos":"particle","grammar:789:ex4:words:3:zh":"extremely","grammar:789:ex4:words:3:pos":"adverb","grammar:789:ex4:words:4:zh":"crowded","grammar:789:ex4:words:4:note":"こんでいます","grammar:789:ex4:words:4:pos":"verb","grammar:789:ex4:points:0":"混む: to be crowded; 〜ている = 混んでいる, describing a state.","grammar:789:ex4:points:1":"あの道: that road.","grammar:789:ex5:trans":"A new road has been built.","grammar:789:ex5:structure":"〜ができた","grammar:789:ex5:words:0:zh":"new","grammar:789:ex5:words:0:note":"あたらしい","grammar:789:ex5:words:0:pos":"adjective","grammar:789:ex5:words:1:zh":"road","grammar:789:ex5:words:1:note":"みち","grammar:789:ex5:words:1:pos":"noun","grammar:789:ex5:words:2:zh":"(nominative)","grammar:789:ex5:words:2:pos":"particle","grammar:789:ex5:words:3:zh":"Was built","grammar:789:ex5:words:3:pos":"verb","grammar:789:ex5:points:0":"❗〜ができる: (something) is built, is completed.","grammar:789:ex5:points:1":"新しい道ができた: a new road was built.","exam:789:zh":"I didn't know the way to the station, so I walked while looking at a map.","exam:789:why":"「駅までの道」 means the road to the station. 「門」 is a gate, which can't express the route to the station."},"790":{"example:790:exzh":"I memorized a lot of Japanese words.","example:790:exzh2":"This word is difficult, isn't it?","example:790:exzh3":"She uses beautiful language.","example:790:exzh4":"Learning new words is fun.","example:790:exzh5":"I'll look up the meaning of the word.","grammar:790:ex:trans":"I memorized many Japanese words.","grammar:790:ex:structure":"〜をたくさん覚えました","grammar:790:ex:explain":"The key word is 「言葉」 (ことば: language, words). 「言葉をたくさん覚える」 means to memorize a lot of words: 「を」 marks the object and 「たくさん」 is the adverb a lot. 「覚えました」 is the past tense. The whole sentence means I memorized many Japanese words. 「言葉」 can refer both to language in the abstract and to individual words or remarks, so it's used very widely.","grammar:790:ex:words:0:zh":"Japanese","grammar:790:ex:words:0:note":"にほんご","grammar:790:ex:words:0:pos":"noun","grammar:790:ex:words:1:zh":"'s","grammar:790:ex:words:1:pos":"particle","grammar:790:ex:words:2:zh":"Words","grammar:790:ex:words:2:note":"ことば","grammar:790:ex:words:2:pos":"noun","grammar:790:ex:words:3:zh":"(object marker)","grammar:790:ex:words:3:pos":"particle","grammar:790:ex:words:4:zh":"a lot","grammar:790:ex:words:4:pos":"adverb","grammar:790:ex:words:5:zh":"Memorized","grammar:790:ex:words:5:note":"おぼえました","grammar:790:ex:words:5:pos":"verb","grammar:790:ex:points:0":"言葉 (ことば): language, words.","grammar:790:ex:points:1":"覚える: to memorize, to learn by heart.","grammar:790:ex2:trans":"This word is difficult, isn't it?","grammar:790:ex2:structure":"〜は難しいですね","grammar:790:ex2:words:0:zh":"this","grammar:790:ex2:words:0:pos":"pre-noun adjectival","grammar:790:ex2:words:1:zh":"Word","grammar:790:ex2:words:1:note":"ことば","grammar:790:ex2:words:1:pos":"noun","grammar:790:ex2:words:2:zh":"(topic)","grammar:790:ex2:words:2:pos":"particle","grammar:790:ex2:words:3:zh":"difficult","grammar:790:ex2:words:3:note":"むずかしい","grammar:790:ex2:words:3:pos":"adjective","grammar:790:ex2:words:4:zh":"(polite form)","grammar:790:ex2:words:4:pos":"copula","grammar:790:ex2:words:5:zh":"right?","grammar:790:ex2:words:5:pos":"particle","grammar:790:ex2:points:0":"この言葉: this word.","grammar:790:ex2:points:1":"ね: seeking agreement.","grammar:790:ex3:trans":"She uses beautiful language.","grammar:790:ex3:structure":"〜を使います","grammar:790:ex3:words:0:zh":"she","grammar:790:ex3:words:0:note":"かのじょ","grammar:790:ex3:words:0:pos":"pronoun","grammar:790:ex3:words:1:zh":"(topic)","grammar:790:ex3:words:1:pos":"particle","grammar:790:ex3:words:2:zh":"beautiful","grammar:790:ex3:words:2:note":"うつくしい","grammar:790:ex3:words:2:pos":"adjective","grammar:790:ex3:words:3:zh":"languages","grammar:790:ex3:words:3:note":"ことば","grammar:790:ex3:words:3:pos":"noun","grammar:790:ex3:words:4:zh":"(object marker)","grammar:790:ex3:words:4:pos":"particle","grammar:790:ex3:words:5:zh":"use","grammar:790:ex3:words:5:note":"つかいます","grammar:790:ex3:words:5:pos":"verb","grammar:790:ex3:points:0":"言葉を使う: to use words, to use language.","grammar:790:ex3:points:1":"美しい言葉: beautiful words.","grammar:790:ex4:trans":"Learning new words is fun.","grammar:790:ex4:structure":"〜のは楽しいです","grammar:790:ex4:words:0:zh":"new","grammar:790:ex4:words:0:note":"あたらしい","grammar:790:ex4:words:0:pos":"adjective","grammar:790:ex4:words:1:zh":"word","grammar:790:ex4:words:1:note":"ことば","grammar:790:ex4:words:1:pos":"noun","grammar:790:ex4:words:2:zh":"(object marker)","grammar:790:ex4:words:2:pos":"particle","grammar:790:ex4:words:3:zh":"study / learn","grammar:790:ex4:words:3:note":"まなぶ","grammar:790:ex4:words:3:pos":"verb","grammar:790:ex4:words:4:zh":"(nominalizer)","grammar:790:ex4:words:4:pos":"particle","grammar:790:ex4:words:5:zh":"(topic)","grammar:790:ex4:words:5:pos":"particle","grammar:790:ex4:words:6:zh":"interesting","grammar:790:ex4:words:6:note":"たのしい","grammar:790:ex4:words:6:pos":"adjective","grammar:790:ex4:words:7:zh":"(polite form)","grammar:790:ex4:words:7:pos":"copula","grammar:790:ex4:points:0":"新しい言葉: a new word.","grammar:790:ex4:points:1":"〜のは楽しい: doing … is fun.","grammar:790:ex5:trans":"I'll look up the meaning of the word.","grammar:790:ex5:structure":"〜を調べます","grammar:790:ex5:words:0:zh":"word","grammar:790:ex5:words:0:note":"ことば","grammar:790:ex5:words:0:pos":"noun","grammar:790:ex5:words:1:zh":"'s","grammar:790:ex5:words:1:pos":"particle","grammar:790:ex5:words:2:zh":"Meaning","grammar:790:ex5:words:2:note":"いみ","grammar:790:ex5:words:2:pos":"noun","grammar:790:ex5:words:3:zh":"(object marker)","grammar:790:ex5:words:3:pos":"particle","grammar:790:ex5:words:4:zh":"Look up","grammar:790:ex5:words:4:note":"しらべます","grammar:790:ex5:words:4:pos":"verb","grammar:790:ex5:points:0":"言葉の意味: the meaning of the word.","grammar:790:ex5:points:1":"調べる: to look up, to investigate."},"791":{"example:791:exzh":"I like working in an office.","example:791:exzh3":"Some people work from home too.","example:791:exzh4":"She works as a doctor.","example:791:exzh5":"I start working at my new job today.","grammar:791:ex:trans":"I like working in an office.","grammar:791:ex:structure":"〜で働くのが好きです","grammar:791:ex:explain":"This sentence uses the 「〜で働く」 (work at …) pattern: the place of work is marked with 「で」 because working is an action. 「オフィスで働く」 means work at an office, and adding 「〜のが好き」 nominalizes it with 「の」 as the thing you like. The whole sentence means: I like working at an office. 「働く」 is read 「はたらく」 and is a very common verb for working and laboring; the key point is using 「で」 for the place.","grammar:791:ex:words:0:zh":"office","grammar:791:ex:words:0:note":"loanword","grammar:791:ex:words:0:pos":"noun","grammar:791:ex:words:1:zh":"(place)","grammar:791:ex:words:1:pos":"particle","grammar:791:ex:words:2:zh":"work","grammar:791:ex:words:2:note":"はたらく","grammar:791:ex:words:2:pos":"verb","grammar:791:ex:words:3:zh":"(nominalizer)","grammar:791:ex:words:3:pos":"particle","grammar:791:ex:words:4:zh":"(object)","grammar:791:ex:words:4:pos":"particle","grammar:791:ex:words:5:zh":"to like","grammar:791:ex:words:5:note":"すき","grammar:791:ex:words:5:pos":"na-adjective","grammar:791:ex:words:6:zh":"(polite form)","grammar:791:ex:words:6:pos":"copula","grammar:791:ex:points:0":"❗働く（はたらく）: to work, to labor; 〜で働く = work at …","grammar:791:ex:points:1":"〜のが好き: to like doing…","grammar:791:ex3:trans":"Some people work from home too.","grammar:791:ex3:structure":"〜で働く人もいます","grammar:791:ex3:words:0:zh":"house","grammar:791:ex3:words:0:note":"いえ","grammar:791:ex3:words:0:pos":"noun","grammar:791:ex3:words:1:zh":"(place)","grammar:791:ex3:words:1:pos":"particle","grammar:791:ex3:words:2:zh":"work","grammar:791:ex3:words:2:note":"はたらく","grammar:791:ex3:words:2:pos":"verb","grammar:791:ex3:words:3:zh":"person","grammar:791:ex3:words:3:note":"ひと","grammar:791:ex3:words:3:pos":"noun","grammar:791:ex3:words:4:zh":"also, too","grammar:791:ex3:words:4:pos":"particle","grammar:791:ex3:words:5:zh":"there is / are","grammar:791:ex3:words:5:pos":"verb","grammar:791:ex3:points:0":"家で働く: work from home.","grammar:791:ex3:points:1":"〜人もいる: there are also people who…","grammar:791:ex4:trans":"She works as a doctor.","grammar:791:ex4:structure":"〜として働いています","grammar:791:ex4:words:0:zh":"she","grammar:791:ex4:words:0:note":"かのじょ","grammar:791:ex4:words:0:pos":"pronoun","grammar:791:ex4:words:1:zh":"(topic)","grammar:791:ex4:words:1:pos":"particle","grammar:791:ex4:words:2:zh":"doctor","grammar:791:ex4:words:2:note":"いしゃ","grammar:791:ex4:words:2:pos":"noun","grammar:791:ex4:words:3:zh":"as","grammar:791:ex4:words:3:pos":"set phrase","grammar:791:ex4:words:4:zh":"is working","grammar:791:ex4:words:4:note":"はたらいています","grammar:791:ex4:words:4:pos":"verb","grammar:791:ex4:points:0":"❗〜として: as… (in the role of).","grammar:791:ex4:points:1":"医者として働く: work as a doctor.","grammar:791:ex5:trans":"Starting today, I'm working at a new job.","grammar:791:ex5:structure":"〜から〜で働きます","grammar:791:ex5:words:0:zh":"today","grammar:791:ex5:words:0:note":"きょう","grammar:791:ex5:words:0:pos":"noun","grammar:791:ex5:words:1:zh":"from","grammar:791:ex5:words:1:pos":"particle","grammar:791:ex5:words:2:zh":"new","grammar:791:ex5:words:2:note":"あたらしい","grammar:791:ex5:words:2:pos":"adjective","grammar:791:ex5:words:3:zh":"work","grammar:791:ex5:words:3:note":"しごと","grammar:791:ex5:words:3:pos":"noun","grammar:791:ex5:words:4:zh":"(place / content)","grammar:791:ex5:words:4:pos":"particle","grammar:791:ex5:words:5:zh":"work","grammar:791:ex5:words:5:note":"はたらきます","grammar:791:ex5:words:5:pos":"verb","grammar:791:ex5:points:0":"❗今日から: from today.","grammar:791:ex5:points:1":"新しい仕事で働く: work at a new job."},"792":{"example:792:exzh":"I said something rude.","example:792:exzh2":"I think his behavior is rude.","example:792:exzh3":"I apologize for the rudeness.","example:792:exzh4":"Please let me know if I do anything rude.","example:792:exzh5":"That way of saying it is rude.","grammar:792:ex:trans":"I said something rude.","grammar:792:ex:structure":"〜てしまいました","grammar:792:ex:explain":"The core here is 「〜てしまう」, which means did … (by accident, regretfully) and carries a tone of regret or completion. 「言ってしまいました」 means accidentally said it (with regret). 「失礼なこと」 uses the na-adjective 「失礼」 plus 「な」 to modify 「こと」, giving something rude. The whole sentence means I said something rude. In casual speech 「〜てしまう」 often contracts to 「〜ちゃう」.","grammar:792:ex:words:0:zh":"rude","grammar:792:ex:words:0:note":"しつれい","grammar:792:ex:words:0:pos":"na-adjective","grammar:792:ex:words:1:zh":"(attributive form)","grammar:792:ex:words:1:pos":"auxiliary verb","grammar:792:ex:words:2:zh":"thing / matter","grammar:792:ex:words:2:pos":"noun","grammar:792:ex:words:3:zh":"(object marker)","grammar:792:ex:words:3:pos":"particle","grammar:792:ex:words:4:zh":"tell","grammar:792:ex:words:4:note":"いって","grammar:792:ex:words:4:pos":"verb","grammar:792:ex:words:5:zh":"(by accident)","grammar:792:ex:words:5:pos":"auxiliary verb","grammar:792:ex:points:0":"❗〜てしまう: to do … (by accident, regretfully).","grammar:792:ex:points:1":"失礼なこと: something rude.","grammar:792:ex2:trans":"I think his behavior is rude.","grammar:792:ex2:structure":"〜だと思います","grammar:792:ex2:words:0:zh":"he","grammar:792:ex2:words:0:note":"かれ","grammar:792:ex2:words:0:pos":"pronoun","grammar:792:ex2:words:1:zh":"'s","grammar:792:ex2:words:1:pos":"particle","grammar:792:ex2:words:2:zh":"actions","grammar:792:ex2:words:2:note":"こうどう","grammar:792:ex2:words:2:pos":"noun","grammar:792:ex2:words:3:zh":"(topic)","grammar:792:ex2:words:3:pos":"particle","grammar:792:ex2:words:4:zh":"rude","grammar:792:ex2:words:4:note":"しつれい","grammar:792:ex2:words:4:pos":"na-adjective","grammar:792:ex2:words:5:zh":"is","grammar:792:ex2:words:5:pos":"copula","grammar:792:ex2:words:6:zh":"(quotation)","grammar:792:ex2:words:6:pos":"particle","grammar:792:ex2:words:7:zh":"thinks","grammar:792:ex2:words:7:note":"おもいます","grammar:792:ex2:words:7:pos":"verb","grammar:792:ex2:points:0":"失礼だと思う: to think (something) is rude.","grammar:792:ex2:points:1":"彼の行動: his behavior.","grammar:792:ex3:trans":"I apologize for the rudeness.","grammar:792:ex3:structure":"〜をお詫び申し上げます","grammar:792:ex3:words:0:zh":"rude","grammar:792:ex3:words:0:note":"しつれい","grammar:792:ex3:words:0:pos":"noun","grammar:792:ex3:words:1:zh":"(object marker)","grammar:792:ex3:words:1:pos":"particle","grammar:792:ex3:words:2:zh":"Offer an apology","grammar:792:ex3:words:2:note":"おわびもうしあげます","grammar:792:ex3:words:2:pos":"set phrase","grammar:792:ex3:points:0":"❗お詫び申し上げます: to offer an apology (kenjōgo, very formal).","grammar:792:ex3:points:1":"失礼: rudeness, offense.","grammar:792:ex4:trans":"If I've been rude in any way, please let me know.","grammar:792:ex4:structure":"〜たらお知らせください","grammar:792:ex4:words:0:zh":"rude","grammar:792:ex4:words:0:note":"しつれい","grammar:792:ex4:words:0:pos":"noun","grammar:792:ex4:words:1:zh":"(nominative)","grammar:792:ex4:words:1:pos":"particle","grammar:792:ex4:words:2:zh":"if there is","grammar:792:ex4:words:2:pos":"verb","grammar:792:ex4:words:3:zh":"inform","grammar:792:ex4:words:3:note":"おしらせ","grammar:792:ex4:words:3:pos":"noun","grammar:792:ex4:words:4:zh":"please","grammar:792:ex4:words:4:pos":"auxiliary verb","grammar:792:ex4:points:0":"〜たら: if …","grammar:792:ex4:points:1":"お知らせください: please let us know (sonkeigo).","grammar:792:ex5:trans":"That way of saying it is rude.","grammar:792:ex5:structure":"〜は失礼です","grammar:792:ex5:words:0:zh":"that","grammar:792:ex5:words:0:pos":"pre-noun adjectival","grammar:792:ex5:words:1:zh":"way of saying","grammar:792:ex5:words:1:note":"いいかた","grammar:792:ex5:words:1:pos":"noun","grammar:792:ex5:words:2:zh":"(topic)","grammar:792:ex5:words:2:pos":"particle","grammar:792:ex5:words:3:zh":"rude","grammar:792:ex5:words:3:note":"しつれい","grammar:792:ex5:words:3:pos":"na-adjective","grammar:792:ex5:words:4:zh":"(polite form)","grammar:792:ex5:words:4:pos":"copula","grammar:792:ex5:points:0":"❗言い方: way of saying, wording (言う + 方).","grammar:792:ex5:points:1":"失礼です: rude."},"793":{"example:793:exzh":"What is the reason for the attack?","example:793:exzh2":"His attack was unexpected.","example:793:exzh3":"That movie has aggressive content.","example:793:exzh4":"Verbal attacks leave wounds in the heart.","example:793:exzh5":"They are preparing for the enemy's attack."},"794":{"example:794:exzh":"I have a big dream.","example:794:exzh2":"Chasing your dreams is important.","example:794:exzh3":"He is working hard to make his dream come true.","example:794:exzh4":"I had a strange dream last night.","example:794:exzh5":"I have friends I can talk about my dreams with."},"795":{"example:795:exzh":"I am standing here.","example:795:exzh2":"He is standing at the bus stop.","example:795:exzh3":"Please stand up.","example:795:exzh4":"Everyone stood up.","example:795:exzh5":"Standing here is hard.","grammar:795:ex:trans":"I'm standing here.","grammar:795:ex:structure":"〜に立っています","grammar:795:ex:explain":"This sentence uses the intransitive verb 「立つ」 (to stand); the place where you stand is marked with 「に」, so 「ここに立つ」 means stand here, and 「〜ている」 describes the state of standing. The whole sentence means: I'm standing here. Note that 「に」 marks the endpoint of existence or posture (立つ, 座る, 住む); use 「で」 only for the place where a dynamic action takes place. 「立つ」 is read 「たつ」 and pairs with the transitive verb 「立てる」 (to set upright).","grammar:795:ex:words:0:zh":"I","grammar:795:ex:words:0:note":"わたし","grammar:795:ex:words:0:pos":"pronoun","grammar:795:ex:words:1:zh":"(topic)","grammar:795:ex:words:1:pos":"particle","grammar:795:ex:words:2:zh":"here","grammar:795:ex:words:2:pos":"pronoun","grammar:795:ex:words:3:zh":"(location of existence)","grammar:795:ex:words:3:pos":"particle","grammar:795:ex:words:4:zh":"standing","grammar:795:ex:words:4:note":"たっています","grammar:795:ex:words:4:pos":"verb","grammar:795:ex:points:0":"❗立つ（たつ）: to stand (intransitive verb); 〜に立つ = stand at …","grammar:795:ex:points:1":"〜ている: the (standing) state.","grammar:795:ex2:trans":"He's standing at the bus stop.","grammar:795:ex2:structure":"〜で立っています","grammar:795:ex2:words:0:zh":"he","grammar:795:ex2:words:0:note":"かれ","grammar:795:ex2:words:0:pos":"pronoun","grammar:795:ex2:words:1:zh":"(topic)","grammar:795:ex2:words:1:pos":"particle","grammar:795:ex2:words:2:zh":"bus stop","grammar:795:ex2:words:2:note":"バスてい","grammar:795:ex2:words:2:pos":"noun","grammar:795:ex2:words:3:zh":"(place)","grammar:795:ex2:words:3:pos":"particle","grammar:795:ex2:words:4:zh":"standing","grammar:795:ex2:words:4:note":"たっています","grammar:795:ex2:words:4:pos":"verb","grammar:795:ex2:points:0":"❗バス停: bus stop; 〜で立つ = stand at … (で for place).","grammar:795:ex2:points:1":"立っている: be standing.","grammar:795:ex3:trans":"Please stand.","grammar:795:ex3:structure":"立ってください","grammar:795:ex3:words:0:zh":"stand","grammar:795:ex3:words:0:note":"たって","grammar:795:ex3:words:0:pos":"verb","grammar:795:ex3:words:1:zh":"please","grammar:795:ex3:words:1:pos":"auxiliary verb","grammar:795:ex3:points:0":"立ってください: please stand up.","grammar:795:ex3:points:1":"立つ → 立って.","grammar:795:ex4:trans":"Everyone stood up.","grammar:795:ex4:structure":"皆が立ちました","grammar:795:ex4:explain":"「皆」 means everyone; it can also be read as the more formal 「みな」. 「が」 marks who stands up. 「立つ」 is a godan (u-) verb, so with 「ます」 it becomes 「立ちます」, and 「ました」 makes it past. This sentence says everyone stood up; to describe everyone standing now, you can use 「立っています」.","grammar:795:ex4:words:0:zh":"everyone","grammar:795:ex4:words:0:note":"みな","grammar:795:ex4:words:0:pos":"pronoun","grammar:795:ex4:words:1:zh":"(nominative)","grammar:795:ex4:words:1:pos":"particle","grammar:795:ex4:words:2:zh":"stood up","grammar:795:ex4:words:2:note":"たち","grammar:795:ex4:words:2:pos":"verb","grammar:795:ex4:words:3:zh":"(polite tone)","grammar:795:ex4:words:3:pos":"auxiliary verb","grammar:795:ex4:words:4:zh":"(past, completed)","grammar:795:ex4:words:4:pos":"auxiliary verb","grammar:795:ex4:points:0":"「立つ」 is an intransitive verb, so the person who stands up is marked with 「が」.","grammar:795:ex4:points:1":"The polite form of 「立つ」 is 「立ちます」, and the past form is 「立ちました」.","grammar:795:ex5:trans":"It's hard to stand here.","grammar:795:ex5:structure":"〜に立つのは難しい","grammar:795:ex5:words:0:zh":"here","grammar:795:ex5:words:0:pos":"pronoun","grammar:795:ex5:words:1:zh":"(location of existence)","grammar:795:ex5:words:1:pos":"particle","grammar:795:ex5:words:2:zh":"stand","grammar:795:ex5:words:2:note":"たつ","grammar:795:ex5:words:2:pos":"verb","grammar:795:ex5:words:3:zh":"(nominalizer)","grammar:795:ex5:words:3:pos":"particle","grammar:795:ex5:words:4:zh":"(topic)","grammar:795:ex5:words:4:pos":"particle","grammar:795:ex5:words:5:zh":"difficult","grammar:795:ex5:words:5:note":"むずかしい","grammar:795:ex5:words:5:pos":"adjective","grammar:795:ex5:points:0":"ここに立つ: stand here.","grammar:795:ex5:points:1":"〜のは難しい: it is hard to…","exam:795:zh":"All the seats on the train were taken and I couldn't sit, so I decided to stand by the door.","exam:795:why":"When there are no seats, standing by the door uses 「立つ」. 「座る」 contradicts the earlier 「座れない」."},"796":{"example:796:exzh":"The police arrested the criminal.","example:796:exzh2":"He was arrested for wrongdoing.","example:796:exzh3":"What is the reason for the arrest?","example:796:exzh4":"The news of the arrest was reported.","example:796:exzh5":"They were arrested without evidence."},"797":{"example:797:exzh":"As you get older, your stamina declines.","example:797:exzh2":"You're old enough, so don't cry over something like that.","grammar:797:ex:trans":"As you get older, your physical strength declines.","grammar:797:ex:structure":"A と、B (natural result)","grammar:797:ex:words:0:zh":"age","grammar:797:ex:words:0:note":"とし","grammar:797:ex:words:0:pos":"noun","grammar:797:ex:words:1:zh":"(object marker)","grammar:797:ex:words:1:pos":"particle","grammar:797:ex:words:2:zh":"take; increase","grammar:797:ex:words:2:note":"とる","grammar:797:ex:words:2:pos":"verb","grammar:797:ex:words:3:zh":"as soon as…; the moment…","grammar:797:ex:words:3:note":"Condition: when the first part holds true, the second part naturally follows.","grammar:797:ex:words:3:pos":"particle","grammar:797:ex:words:4:zh":"physical strength","grammar:797:ex:words:4:note":"たいりょく","grammar:797:ex:words:4:pos":"noun","grammar:797:ex:words:5:zh":"(nominative)","grammar:797:ex:words:5:pos":"particle","grammar:797:ex:words:6:zh":"go down","grammar:797:ex:words:6:note":"おちる","grammar:797:ex:words:6:pos":"verb","grammar:797:ex:points:0":"歳を取る = to get older; 歳 is read とし here (not さい).","grammar:797:ex:points:1":"〜と: once the first part holds true, the second part naturally follows; often used for general rules.","grammar:797:ex2:trans":"At your age, don't cry over something like that.","grammar:797:ex2:structure":"いい歳をして、〜 (reproach)","grammar:797:ex2:words:0:zh":"good (here meaning “considerable”)","grammar:797:ex2:words:0:note":"いい","grammar:797:ex2:words:0:pos":"adjective","grammar:797:ex2:words:1:zh":"age","grammar:797:ex2:words:1:note":"とし","grammar:797:ex2:words:1:pos":"noun","grammar:797:ex2:words:2:zh":"(object marker)","grammar:797:ex2:words:2:pos":"particle","grammar:797:ex2:words:3:zh":"(having reached)","grammar:797:ex2:words:3:note":"して; te-form","grammar:797:ex2:words:3:pos":"verb","grammar:797:ex2:words:4:zh":"such","grammar:797:ex2:words:4:note":"そんな","grammar:797:ex2:words:4:pos":"pre-noun adjectival","grammar:797:ex2:words:5:zh":"thing / matter","grammar:797:ex2:words:5:note":"こと","grammar:797:ex2:words:5:pos":"formal noun","grammar:797:ex2:words:6:zh":"because","grammar:797:ex2:words:6:note":"expresses cause","grammar:797:ex2:words:6:pos":"particle","grammar:797:ex2:words:7:zh":"don't cry","grammar:797:ex2:words:7:note":"なくな; dictionary form＋な = prohibition","grammar:797:ex2:words:7:pos":"verb","grammar:797:ex2:points:0":"いい歳をして: at your age, you still …; an idiomatic expression conveying reproach.","grammar:797:ex2:points:1":"verb in the dictionary form＋な = a strong prohibition (don't …)"},"798":{"example:798:exzh":"First, please tell me your name.","example:798:exzh2":"Let's solve this problem first.","example:798:exzh3":"First, we need to make a plan.","example:798:exzh4":"First, try asking him.","example:798:exzh5":"First, let's get ready."},"799":{"example:799:exzh":"My father is kind.","example:799:exzh2":"My father is cooking.","example:799:exzh3":"His father is a company employee.","example:799:exzh4":"I watched a movie with my father.","example:799:exzh5":"My father likes traveling."}};